module baud_gen(input clk, rst, input [7:0] div, output reg tick);
reg [7:0] counter;
reg [7:0] tick_reg;

always @(posedge clk, posedge rst) begin
    if (rst) begin
        counter <= 8'b0;
        tick_reg <= 1'b0;
    end else begin
        if (counter == div - 1) begin
            counter <= 8'b0;
            tick_reg <= 1'b1;
        end else begin
            counter <= counter + 1;
            tick_reg <= 1'b0;
        end
    end
end

assign tick = tick_reg;

endmodule

