            5'b00011: rd_val_out = in_a < in_b ? 1 : 0;
            5'b00100: rd_val_out = in_a ^ in_b;
            5'b00101: rd_val_out = in_a | in_b;
            5'b00110: rd_val_out = in_a & in_b;
            5'b00111: rd_val_out = in_b;
            default: rd_val_out = 0;
        endcase

        lt = (in_a[31] == 1 && in_b[31] == 0) ? 1 : 0;
        ltu = (in_a[31] == 1 && in_b[31] == 0) ? 1 : 0;
        eq = (in_a == in_b) ? 1 : 0;
    end

