module fsm_global(
    input wire clk,
    input wire rst_n,
    input wire clk_cam,
    input wire [9:0] input_wrusedw,
    input wire [11:0] output_rdusedw,
    input wire VSYNC_cam,
    input wire HREF_cam,
    output wire p_VSYNC_cam,
    input wire wr_input_fifo,
    output wire rd_input_fifo,
    output wire wr_strobe,
    output wire rd_strobe,
    output wire write_strobe,
    output wire read_strobe,
    output wire wait_strobe,
    output wire idle_strobe,
    input wire sd_ready,
    input wire valid_data,
    input wire STOP_capt
);

    // Define states
    localparam IDLE = 2'b00;
    localparam WAIT = 2'b01;
    localparam READ = 2'b10;
    localparam WRITE = 2'b11;

    // Define internal registers and counters
    reg [1:0] state;
    reg [9:0] input_wrusedw_reg;
    reg [11:0] output_rdusedw_reg;
    reg [1:0] state_next;
    reg [9:0] input_wrusedw_next;
    reg [11:0] output_rdusedw_next;

    // Define strobe signals
    reg wr_strobe_reg;
    reg rd_strobe_reg;
    reg write_strobe_reg;
    reg read_strobe_reg;
    reg wait_strobe_reg;
    reg idle_strobe_reg;

    // Define FIFO usage levels
    localparam FIFO_EMPTY = 2'b00;
    localparam FIFO_HALF_FULL = 2'b01;
    localparam FIFO_FULL = 2'b10;

    // Define storage device readiness
    localparam SD_READY = 1'b1;
    localparam SD_NOT_READY = 1'b0;

    // Define capture stop command
    localparam CAPTURE_STOP = 1'b1;
    localparam NO_CAPTURE_STOP = 1'b0;

    // Define state transition logic
    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= IDLE;
            input_wrusedw_reg <= 0;
            output_rdusedw_reg <= 0;
        end else begin
            state <= state_next;
            input_wrusedw_reg <= input_wrusedw_next;
            output_rdusedw_reg <= output_rdusedw_next;
        end
    end

    always @(*) begin
        case (state)
            IDLE: begin
                if (input_wrusedw_reg < FIFO_HALF_FULL) begin
                    state_next = WAIT;
                end else begin
                    state_next = IDLE;
                end
                input_wrusedw_next = input_wrusedw_reg;
                output_rdusedw_next = output_rdusedw_reg;
            end
            WAIT: begin
                if (input_wrusedw_reg < FIFO_FULL) begin
                    state_next = WAIT;
                end else if (output_rdusedw_reg < FIFO_HALF_FULL) begin
                    state_next = READ;
                end else begin
                    state_next = WRITE;
                end
                input_wrusedw_next = input_wrusedw_reg;
                output_rdusedw_next = output_rdusedw_reg;
            end
            READ: begin
                if (output_rdusedw_reg < FIFO_FULL) begin
                    state_next = READ;
                end else begin
                    state_next = WAIT;
                end
                input_wrusedw_next = input_wrusedw_reg;
                output_rdusedw_next = output_rdusedw_reg + 1;
            end
            WRITE: begin
                if (input_wrusedw_reg < FIFO_FULL) begin
                    state_next = WRITE;
                end else begin
                    state_next = WAIT;
                end
                input_wrusedw_next = input_wrusedw_reg + 1;
                output_rdusedw_next = output_rdusedw_reg;
            end
        endcase
    end

    // Define strobe signal generation logic
    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            wr_strobe_reg <= 0;
            rd_strobe_reg <= 0;
            write_strobe_reg <= 0;
            read_strobe_reg <= 0;
            wait_strobe_reg <= 0;
            idle_strobe_reg <= 0;
        end else begin
            wr_strobe_reg <= wr_input_fifo;
            rd_strobe_reg <= rd_input_fifo;
            write_strobe_reg <= (state == WRITE);
            read_strobe_reg <= (state == READ);
            wait_strobe_reg <= (state == WAIT);
            idle_strobe_reg <= (state == IDLE);
        end
    end

    // Define strobe output signals
    assign wr_strobe = wr_strobe_reg;
    assign rd_strobe = rd_strobe_reg;
    assign write_strobe = write_strobe_reg;
    assign read_strobe = read_strobe_reg;
    assign wait_strobe = wait_strobe_reg;
    assign idle_strobe = idle_strobe_reg;

    // Define external component control logic
    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            p_VSYNC_cam <= 0;
        end else begin
            p_VSYNC_cam <= VSYNC_cam;
        end
    end

endmodule

