module top_properties(input logic clock, read, write, ready);

  // Assertion to check for mutually exclusive read and write conditions at every positive clock edge
  property read_write_exclusive;
    @(posedge clock)
    (read |-> !write) and (write |-> !read);
  endproperty

  // Assertion to enforce timing relationship between the write and ready signals
  property write_ready_timing;
    @(posedge clock)
    (write |-> ##[0:FAIL] ready);
  endproperty

  // Assertions to check the correct behavior of read and write operations
  assert property (read_write_exclusive) else $error("Read and write operations are not mutually exclusive");
  assert property (write_ready_timing) else $error("Write and ready signals are not properly synchronized");

endmodule

