module New_Nine_palette(input logic [0:0] index, output logic [3:0] red, green, blue);

  logic [3:0] color_palette[0:1];

  // Initialize color palette
  initial begin
    color_palette[0] = 4'b0000; // Black
    color_palette[1] = 4'b1101; // Medium gray
  end

  // Select color based on index
  always_comb begin
    if (index == 1'b0) begin
      red = color_palette[0][3:2];
      green = color_palette[0][1:0];
      blue = 2'b00;
    end else begin
      red = color_palette[1][3:2];
      green = color_palette[1][1:0];
      blue = 2'b00;
    end
  end

endmodule

