module keypress_generator(input clk, input reset, output reg [9:0] keypress);

    // Define the array of keypress values
    reg [9:0] keypress_array [0:3] = {10'h000, 10'h001, 10'h002, 10'h003};

    // Define the counter and index
    reg [4:0] counter = 0;
    reg [1:0] index = 0;

    always @(posedge clk) begin
        if (reset) begin
            // Reset all internal states
            counter <= 0;
            index <= 0;
            keypress <= 0;
        end else begin
            // Increment the counter
            counter <= counter + 1;

            // Delay each keypress by 20 clock cycles
            if (counter == 20) begin
                // Increment the index
                index <= index + 1;

                // Check if we have reached the end of the array
                if (index == 4) begin
                    // Continue to output the same key indefinitely
                    keypress <= keypress_array[index];
                end else begin
                    // Output the next keypress
                    keypress <= keypress_array[index];
                end

                // Reset the counter
                counter <= 0;
            end
        end
    end

endmodule

