module eb1_5 #(parameter WIDTH=8, parameter S0=3'o0, parameter S1=3'o1, parameter S2=3'o2, parameter S3=3'o3, parameter S4=3'o4)
(
    input clk,
    input reset_n,
    input [WIDTH-1:0] t0_data,
    input t0_valid,
    output logic t0_ready,
    output logic [WIDTH-1:0] i0_data,
    output logic i0_valid,
    input i0_ready
);

    // State machine parameters
    parameter IDLE = 2'b00;
    parameter CAPTURE_DATA0 = 2'b01;
    parameter CAPTURE_DATA1 = 2'b10;
    parameter OUTPUT_DATA = 2'b11;

    // State machine signals
    reg [1:0] state;
    reg [1:0] next_state;
    reg [WIDTH-1:0] data0;
    reg [WIDTH-1:0] data1;
    reg [WIDTH-1:0] output_data;
    reg output_valid;
    reg output_ready;

    // State machine logic
    always @(posedge clk or negedge reset_n) begin
        if (~reset_n) begin
            state <= IDLE;
            data0 <= 0;
            data1 <= 0;
            output_data <= 0;
            output_valid <= 0;
            output_ready <= 0;
        end else begin
            state <= next_state;
            case (state)
                IDLE: begin
                    if (t0_valid && i0_ready) begin
                        next_state = CAPTURE_DATA0;
                    end else begin
                        next_state = IDLE;
                    end
                end
                CAPTURE_DATA0: begin
                    data0 <= t0_data;
                    next_state = CAPTURE_DATA1;
                end
                CAPTURE_DATA1: begin
                    data1 <= t0_data;
                    next_state = OUTPUT_DATA;
                end
                OUTPUT_DATA: begin
                    output_data <= (state == S0 || state == S1) ? data0 : data1;
                    output_valid <= 1;
                    if (i0_ready) begin
                        output_ready <= 1;
                        next_state = IDLE;
                    end else begin
                        output_ready <= 0;
                        next_state = OUTPUT_DATA;
                    end
                end
            endcase
        end
    end

    // Output ready signal
    always @(posedge clk or negedge reset_n) begin
        if (~reset_n) begin
            t0_ready <= 0;
        end else begin
            case (state)
                IDLE: begin
                    t0_ready <= 1;
                end
                CAPTURE_DATA0: begin
                    t0_ready <= 0;
                end
                CAPTURE_DATA1: begin
                    t0_ready <= 0;
                end
                OUTPUT_DATA: begin
                    t0_ready <= 1;
                end
            endcase
        end
    end

    // Output data and valid signal
    always @(posedge clk or negedge reset_n) begin
        if (~reset_n) begin
            i0_data <= 0;
            i0_valid <= 0;
        end else begin
            i0_data <= output_data;
            i0_valid <= output_valid;
            output_valid <= 0;
        end
    end

    // Assertion for output data validity
    always @(posedge clk or negedge reset_n) begin
        if (~reset_n) begin
            assert (i0_valid == 0) else $error("Output data is valid in the initial state");
        end else begin
            if (state != IDLE) begin
                assert (i0_valid == 1) else $error("Output data is not valid");
            end
        end
    end

endmodule

module fifo_simple #(parameter WIDTH=16, parameter DEPTH=16, parameter PROG_FULL=14)(
module fifo_simple #(parameter WIDTH=16, parameter DEPTH=16, parameter PROG_FULL=14)(
    input wire reset_p,
    input wire clk,
    input wire [WIDTH-1:0] data_i,
    input wire data_we,
    output wire [WIDTH-1:0] data_o,
    input wire data_rd,
    output wire prog_full,
    output wire full,
    output wire empty,
    output reg overflow,
    output reg underflow
);

    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [DEPTH-1:0] wr_ptr;
    reg [DEPTH-1:0] rd_ptr;
    reg [DEPTH-1:0] word_count;

    always @(posedge clk) begin
        if (reset_p) begin
            wr_ptr <= 0;
            rd_ptr <= 0;
            word_count <= 0;
            overflow <= 0;
            underflow <= 0;
        end else begin
            if (data_we && !full) begin
                mem[wr_ptr] <= data_i;
                wr_ptr <= wr_ptr + 1;
                word_count <= word_count + 1;
                if (word_count == DEPTH) begin
                    overflow <= 1;
                end
            end
            if (data_rd && !empty) begin
                data_o <= mem[rd_ptr];
                rd_ptr <= rd_ptr + 1;
                word_count <= word_count - 1;
                if (word_count == 0) begin
                    underflow <= 1;
                end
            end
        end
    end

    assign prog_full = (word_count >= PROG_FULL);
    assign full = (word_count == DEPTH);
    assign empty = (word_count == 0);

endmodule

