module im2_control(
    input wire i_CLK_CPU,
    input wire i_reset,
    input wire i_m1_n,
    input wire i_mreq_n,
    input wire i_iorq_n,
    input wire i_rfsh_n,
    input wire [7:0] i_cpu_d,
    output wire o_reti_decode,
    output wire o_reti_seen
);

    // Define states
    parameter S_0 = 2'b00;
    parameter S_ED_T4 = 2'b01;
    parameter S_4D_T4 = 2'b10;
    parameter S_CB_T4 = 2'b11;

    // Define registers
    reg [1:0] state;
    reg [7:0] opcode;
    reg ifetch_d;
    reg cpu_opcode_capture;

    // Define wires
    wire fetch_cancel;
    wire ifetch;
    wire ifetch_cancel;

    // Define combinational logic
    assign fetch_cancel = i_m1_n & i_mreq_n & i_iorq_n & i_rfsh_n;
    assign ifetch = i_m1_n & i_mreq_n & i_iorq_n & ~i_rfsh_n;
    assign ifetch_cancel = i_m1_n & i_mreq_n & i_iorq_n & i_rfsh_n;

    // Define state machine
    always @(posedge i_CLK_CPU or posedge i_reset) begin
        if (i_reset) begin
            state <= S_0;
            opcode <= 8'b0;
            ifetch_d <= 1'b0;
            cpu_opcode_capture <= 1'b0;
        end else begin
            case (state)
                S_0: begin
                    if (ifetch) begin
                        state <= S_ED_T4;
                        ifetch_d <= 1'b1;
                    end else if (ifetch_cancel) begin
                        state <= S_0;
                        ifetch_d <= 1'b0;
                    end else begin
                        state <= S_0;
                        ifetch_d <= 1'b0;
                    end
                end
                S_ED_T4: begin
                    if (cpu_opcode_capture) begin
                        state <= S_4D_T4;
                        cpu_opcode_capture <= 1'b0;
                    end else begin
                        state <= S_ED_T4;
                    end
                end
                S_4D_T4: begin
                    if (fetch_cancel) begin
                        state <= S_0;
                        ifetch_d <= 1'b0;
                    end else if (ifetch) begin
                        state <= S_ED_T4;
                        ifetch_d <= 1'b1;
                    end else begin
                        state <= S_4D_T4;
                    end
                end
                S_CB_T4: begin
                    if (fetch_cancel) begin
                        state <= S_0;
                        ifetch_d <= 1'b0;
                    end else if (ifetch) begin
                        state <= S_ED_T4;
                        ifetch_d <= 1'b1;
                    end else begin
                        state <= S_CB_T4;
                    end
                end
            endcase
        end
    end

    // Define opcode decoding logic
    always @(posedge i_CLK_CPU or posedge i_reset) begin
        if (i_reset) begin
            opcode <= 8'b0;
        end else begin
            case (state)
                S_ED_T4: begin
                    opcode <= i_cpu_d;
                    cpu_opcode_capture <= 1'b1;
                end
                S_4D_T4: begin
                    opcode <= i_cpu_d;
                    cpu_opcode_capture <= 1'b1;
                end
                S_CB_T4: begin
                    opcode <= i_cpu_d;
                    cpu_opcode_capture <= 1'b1;
                end
                default: begin
                    opcode <= 8'b0;
                    cpu_opcode_capture <= 1'b0;
                end
            endcase
        end
    end

    // Define output signals
    assign o_reti_decode = (state == S_ED_T4) ? 1'b1 : 1'b0;
    assign o_reti_seen = (state == S_4D_T4) ? 1'b1 : 1'b0;

endmodule

