module AXI_WRITE_DATA_CHANNEL_model(
    input wire clk,
    input wire resetn,
    input wire [31:0] data,
    input wire go,
    output reg done,
    output reg [31:0] WDATA,
    output reg [3:0] WSTRB,
    output reg WVALID,
    input wire WREADY
);

    parameter reset = 2'b00, idle = 2'b01, running = 2'b10, complete = 2'b11;
    reg [1:0] current_state, next_state;

    always @(posedge clk or negedge resetn) begin
        if (~resetn) begin
            current_state <= reset;
        end else begin
            current_state <= next_state;
        end
    end

    always @(*) begin
        case (current_state)
            reset: begin
                done <= 1'b0;
                WDATA <= 32'b0;
                WSTRB <= 4'b0000;
                WVALID <= 1'b0;
                next_state = idle;
            end
            idle: begin
                done <= 1'b0;
                WDATA <= 32'b0;
                WSTRB <= 4'b0000;
                WVALID <= 1'b0;
                if (go) begin
                    next_state = running;
                end else begin
                    next_state = idle;
                end
            end
            running: begin
                done <= 1'b0;
                WDATA <= data;
                WSTRB <= 4'b1111;
                WVALID <= 1'b1;
                if (WREADY) begin
                    next_state = complete;
                end else begin
                    next_state = running;
                end
            end
            complete: begin
                done <= 1'b1;
                WDATA <= 32'b0;
                WSTRB <= 4'b0000;
                WVALID <= 1'b0;
                next_state = idle;
            end
            default: begin
                done <= 1'b0;
                WDATA <= 32'b0;
                WSTRB <= 4'b0000;
                WVALID <= 1'b0;
                next_state = reset;
            end
        endcase
    end

endmodule

