    parameter match_mask = 0;

    reg [1:0] state;
    reg [35:0] data0;
    reg [35:0] data1;
    reg [35:0] mask;
    reg [35:0] data;
    reg [35:0] match;
    reg [35:0] eof;

    assign dst_rdy_o = (state == 2'b01) ? src0_rdy_o : src1_rdy_o;
    assign data0_o = data0;
    assign data1_o = data1;
    assign src0_rdy_o = (state == 2'b01) ? dst0_rdy_i : 1'b0;
    assign src1_rdy_o = (state == 2'b10) ? dst1_rdy_i : 1'b0;

    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
            data0 <= 36'b0;
            data1 <= 36'b0;
            mask <= 36'b0;
            data <= 36'b0;
            match <= 36'b0;
            eof <= 1'b0;
        end else if (clear) begin
            state <= 2'b00;
            data0 <= 36'b0;
            data1 <= 36'b0;
            mask <= 36'b0;
            data <= 36'b0;
            match <= 36'b0;
            eof <= 1'b0;
        end else begin
            case (state)
                2'b00: begin // IDLE
                    if (src_rdy_i) begin
                        data <= data_i;
                        mask <= {36{1'b1}};
                        match <= {36{1'b0}};
                        eof <= data_i[0];
                        if (match_data != 0) begin
                            match <= {36{1'b1}} & data_i;
                        end
                        if (match_mask != 0) begin
                            mask <= {36{1'b1}} & match_mask;
                        end
                        if (match == match_data && mask == match_mask) begin
                            state <= 2'b01;
                        end else begin
                            state <= 2'b10;
                        end
                    end
                end
                2'b01: begin // DATA0
                    if (dst0_rdy_i) begin
                        data0 <= data;
                        state <= 2'b00;
                    end
                end
                2'b10: begin // DATA1
                    if (dst1_rdy_i) begin
                        data1 <= data;
                        state <= 2'b00;
                    end
                end
            endcase
        end
    end

