    always @(posedge clk_50m) begin
        if (rst) begin
            rdy <= 1'b0;
        end else if (clken) begin
            rdy <= (state == STOP) ? 1'b1 : 1'b0;
        end
    end

    // Define state machine logic
    always @(*) begin
        case (state)
            START: begin
                if (rx == 1'b0) begin
                    next_state = DATA;
                end else begin
                    next_state = START;
                end
            end
            DATA: begin
                if (bit_counter == 4'b1111) begin
                    next_state = STOP;
                end else begin
                    next_state = DATA;
                end
            end
            STOP: begin
                next_state = START;
            end
            default: begin
                next_state = START;
            end
        endcase
    end

    // Define bit counter logic
    always @(*) begin
        case (state)
            START: begin
                next_bit_counter = 4'b0000;
            end
            DATA: begin
                next_bit_counter = bit_counter + 1;
            end
            STOP: begin
                next_bit_counter = 4'b0000;
            end
            default: begin
                next_bit_counter = 4'b0000;
            end
        endcase
    end

    // Define data register logic
    always @(*) begin
        case (state)
            START: begin
                next_data_reg = 8'b00000000;
            end
            DATA: begin
                next_data_reg = {rx, data_reg[7:1]};
            end
            STOP: begin
                next_data_reg = data_reg;
            end
            default: begin
                next_data_reg = 8'b00000000;
            end
        endcase
    end

    // Assign output register
    assign data = data_reg;

