module Counter2(input clk, input start, input reset, output reg [3:0] count1, output reg [3:0] count2, output reg done);
  parameter mod = 9;
  reg [3:0] count1_next, count2_next;
  reg done_next;

  always @(posedge clk) begin
    if (reset) begin
      count1 <= 0;
      count2 <= 0;
      done <= 0;
    end else begin
      count1 <= count1_next;
      count2 <= count2_next;
      done <= done_next;
    end
  end

  always @(*) begin
    if (start) begin
      if (count1 == mod-1) begin
        count1_next = 0;
        count2_next = count2 + 1;
        done_next = 0;
      end else begin
        count1_next = count1 + 1;
        count2_next = count2;
        done_next = 0;
      end
    end else begin
      count1_next = count1;
      count2_next = count2;
      done_next = 0;
    end

    if (count1 == mod-1 && count2 == mod-1) begin
      done_next = 1;
    end
  end
endmodule

