module Data_Memory(
    input reset,
    input [31:0] address,
    input [31:0] write_data,
    input memRead,
    input memWrite,
    input [2:0] func3,
    output reg [31:0] read_data
);

    parameter MEM_SIZE = 1024; // 1KB memory
    reg [7:0] mem [0:MEM_SIZE-1];

    always @(posedge reset) begin
        // Initialize memory contents from file
        $readmemh("mem.hex", mem);
    end

    always @(posedge memRead) begin
        case (func3)
            3'b000: // Byte read
                read_data <= {24'b0, mem[address]};
            3'b001: // Half-word read
                read_data <= {16'b0, mem[address+1], mem[address]};
            3'b010: // Word read
                read_data <= {mem[address+3], mem[address+2], mem[address+1], mem[address]};
            3'b100: // LB (sign-extension)
                read_data <= {{24{mem[address+1][7]}}, mem[address+1], mem[address]};
            3'b101: // LH (sign-extension)
                read_data <= {{16{mem[address+1][7]}}, mem[address+1], mem[address]};
            default: // LW
                read_data <= {mem[address+3], mem[address+2], mem[address+1], mem[address]};
        endcase
    end

    always @(posedge memWrite) begin
        case (func3)
            3'b000: // Byte write
                mem[address] <= write_data[7:0];
            3'b001: // Half-word write
                mem[address+1] <= write_data[15:0];
            3'b010: // Word write
                mem[address+3] <= write_data[31:24];
                mem[address+2] <= write_data[23:16];
                mem[address+1] <= write_data[15:8];
                mem[address] <= write_data[7:0];
            default: // No write operation
        endcase
    end

endmodule

module UARTTransmitter(input clock, reset, io_valid, input[7:0] io_bits, input tick, output io_ready, tx);

  reg [3:0] state;
  reg [7:0] data;
  reg tx_line;

  always @(posedge clock) begin
    if (reset) begin
      state <= 4'b0000;
      data <= 8'b00000000;
      tx_line <= 1'b1;
      io_ready <= 1'b1;
    end else begin
      case (state)
        4'b0000: begin // Idle state
          if (io_valid) begin
            data <= io_bits;
            state <= 4'b0001;
            io_ready <= 1'b0;
          end
        end
        4'b0001: begin // Start bit
          tx_line <= 1'b0;
          state <= 4'b0010;
        end
        4'b0010: begin // Data bits
          tx_line <= data[0];
          data <= {data[6:0], 1'b0};
          if (tick) begin
            if (state == 4'b0010) begin
              state <= 4'b0011;
            end else begin
              state <= state + 1;
            end
          end
        end
        4'b0011: begin // Stop bit
          tx_line <= 1'b1;
          state <= 4'b0000;
          io_ready <= 1'b1;
        end
      endcase
    end
  end

  assign tx = tx_line;

endmodule

