module control(
    input wire [31:0] instr,
    input wire [31:0] alu_result,
    output reg [1:0] imm_type,
    output reg rf_we,
    output reg alu_imm,
    output reg [2:0] alu_funct3,
    output reg [6:0] alu_funct7,
    output reg mem_we,
    output wire [1:0] mem_access_width,
    output reg halt,
    output reg branch_taken,
    output reg jump,
    output reg jump_reg
);

    // Decode instruction fields
    wire [6:0] opcode = instr[6:0];
    wire [2:0] funct3 = instr[14:12];
    wire [6:0] funct7 = instr[31:25];

    // Initialize control signals
    assign imm_type = 2'b00;
    assign rf_we = 1'b0;
    assign alu_imm = 1'b0;
    assign alu_funct3 = 3'b000;
    assign alu_funct7 = 7'b0000000;
    assign mem_we = 1'b0;
    assign halt = 1'b0;
    assign branch_taken = 1'b0;
    assign jump = 1'b0;
    assign jump_reg = 1'b0;

    // Control logic based on opcode
    always @* begin
        case (opcode)
            7'b0110011: begin // R-type instruction
                rf_we = 1'b1;
                alu_imm = 1'b0;
                alu_funct3 = funct3;
                alu_funct7 = funct7;
            end
            7'b0010011: begin // I-type instruction
                rf_we = 1'b1;
                alu_imm = 1'b1;
                alu_funct3 = funct3;
                alu_funct7 = funct7;
            end
            7'b0100011: begin // S-type instruction
                rf_we = 1'b0;
                alu_imm = 1'b1;
                alu_funct3 = funct3;
                alu_funct7 = funct7;
                mem_we = 1'b1;
                mem_access_width = 2'b10;
            end
            7'b1100011: begin // B-type instruction
                rf_we = 1'b0;
                alu_imm = 1'b1;
                alu_funct3 = funct3;
                alu_funct7 = funct7;
                if (alu_result == 32'b0) begin
                    branch_taken = 1'b1;
                end
            end
            7'b1101111: begin // J-type instruction
                rf_we = 1'b0;
                alu_imm = 1'b1;
                alu_funct3 = funct3;
                alu_funct7 = funct7;
                jump = 1'b1;
                jump_reg = 1'b1;
            end
            7'b1110011: begin // I-type instruction
                rf_we = 1'b1;
                alu_imm = 1'b1;
                alu_funct3 = funct3;
                alu_funct7 = funct7;
                if (alu_result == 32'b0) begin
                    branch_taken = 1'b1;
                end
            end
            7'b0000000: begin // HALT instruction
                halt = 1'b1;
            end
            default: begin
                // No action
            end
        endcase
    end

endmodule

