module buart #(parameter FREQ_MHZ=2, parameter BAUDS=115200)
(
    input clk,
    input resetq,
    output tx,
    input rx,
    input wr,
    input rd,
    input [7:0] tx_data,
    output [7:0] rx_data,
    output busy,
    output valid
);

    // Constants
    localparam BAUD_DIV = FREQ_MHZ * 1000000 / BAUDS;
    localparam BAUD_DIV_HALF = BAUD_DIV / 2;

    // State machine states
    localparam IDLE = 2'b00;
    localparam START = 2'b01;
    localparam DATA = 2'b10;
    localparam STOP = 2'b11;

    // State machine signals
    reg [1:0] state;
    reg [2:0] bit_cnt;
