    reg [31:0] recv_divcnt;
    reg [31:0] send_divcnt;

    // Buffers
    reg [7:0] recv_buf_data;
    reg recv_buf_valid;

    // State machine
    always @(posedge clk, negedge resetq) begin
        if (!resetq) begin
            state <= IDLE;
            bit_cnt <= 0;
            rx_reg <= 0;
            tx_reg <= 0;
            tx_start <= 0;
            tx_stop <= 0;
            rx_valid <= 0;
            tx_busy <= 0;
            baud_cnt <= 0;
            recv_divcnt <= 0;
            send_divcnt <= 0;
            recv_buf_data <= 0;
            recv_buf_valid <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (rx == 0) begin
                        state <= START;
                        bit_cnt <= 0;
                        rx_reg <= 0;
                        baud_cnt <= 0;
                    end
                end
                START: begin
                    if (baud_cnt >= BAUD_DIV_HALF) begin
                        baud_cnt <= 0;
                        if (rx == 1) begin
                            state <= DATA;
                            bit_cnt <= 0;
                            rx_reg <= 0;
                        end
                    end else begin
                        baud_cnt <= baud_cnt + 1;
                    end
                end
                DATA: begin
                    if (baud_cnt >= BAUD_DIV) begin
                        baud_cnt <= 0;
                        rx_reg <= {rx_reg[6:0], rx};
                        bit_cnt <= bit_cnt + 1;
                        if (bit_cnt == 8) begin
                            state <= STOP;
                            bit_cnt <= 0;
                            rx_reg <= 0;
                            rx_valid <= 1;
                            recv_buf_data <= rx_reg;
                            recv_buf_valid <= 1;
                        end
                    end else begin
                        baud_cnt <= baud_cnt + 1;
                    end
                end
                STOP: begin
                    if (baud_cnt >= BAUD_DIV_HALF) begin
                        baud_cnt <= 0;
                        if (rx == 1) begin
                            state <= IDLE;
                            bit_cnt <= 0;
                            rx_reg <= 0;
                            rx_valid <= 0;
                            recv_buf_valid <= 0;
                        end
                    end else begin
                        baud_cnt <= baud_cnt + 1;
                    end
                end
            endcase
        end
    end

    // Transmit logic
    always @(posedge clk, negedge resetq) begin
        if (!resetq) begin
            tx <= 1;
            tx_start <= 0;
            tx_stop <= 0;
            tx_busy <= 0;
            send_divcnt <= 0;
        end else begin
            if (wr) begin
                tx_reg <= tx_data;
                tx_start <= 1;
                tx_stop <= 0;
                tx_busy <= 1;
            end else if (tx_busy) begin
                if (send_divcnt >= BAUD_DIV) begin
                    send_divcnt <= 0;
                    if (tx_start) begin
                        tx <= 0;
                        tx_start <= 0;
                    end else if (tx_stop) begin
                        tx <= 1;
                        tx_stop <= 0;
                        tx_busy <= 0;
                    end else begin
                        tx <= tx_reg[0];
                        tx_reg <= {tx_reg[6:0], 1'b0};
                    end
                end else begin
                    send_divcnt <= send_divcnt + 1;
                end
            end
        end
    end

    // Receive logic
    always @(posedge clk, negedge resetq) begin
        if (!resetq) begin
            recv_divcnt <= 0;
            rx_valid <= 0;
            recv_buf_data <= 0;
            recv_buf_valid <= 0;
        end else begin
            if (rd) begin
                rx_data <= recv_buf_data;
                valid <= recv_buf_valid;
                recv_buf_valid <= 0;
            end
        end
    end

    // Busy signal
    assign busy = tx_busy;

