            V_SYNC <= 1'b0;
        end
        v_sync_counter <= v_sync_counter + 1;
        if (v_sync_counter == V_ACTIVE + V_FRONT_PORCH + V_BACK_PORCH + V_SYNC_WIDTH) begin
            v_sync_counter <= 0;
        end
