        if (RST) begin
            h_counter <= 0;
            v_counter <= 0;
        end else begin
            h_counter <= h_counter + 1;
            if (h_counter == H_ACTIVE + H_FRONT_PORCH + H_BACK_PORCH) begin
                h_counter <= 0;
                v_counter <= v_counter + 1;
                if (v_counter == V_ACTIVE + V_FRONT_PORCH + V_BACK_PORCH) begin
                    v_counter <= 0;
