        end
    end

    // Generate X and Y signals during active display time
    always @(posedge CLK) begin
        if (RST) begin
            x_counter <= 0;
            y_counter <= 0;
        end else begin
            if (h_counter < H_ACTIVE) begin
                x_counter <= h_counter;
