            if (h_counter == H_ACTIVE + H_FRONT_PORCH + H_BACK_PORCH) begin
                h_sync_enable <= 0;
            end
            if (v_counter == V_ACTIVE + V_FRONT_PORCH + V_BACK_PORCH) begin
                v_sync_enable <= 0;
            end
        end
    end

    // Generate DISP_EN enable signal during active display time
    always @(posedge CLK) begin
        if (RST) begin
            disp_en_enable <= 0;
        end else begin
            if (y_counter < V_ACTIVE) begin
                disp_en_enable <= 1;
            end
