module SPI_Slave#(parameter SPI_MODE=0)(
    input i_Rst_L,
    input i_Clk,
    output reg o_RX_DV,
    output reg [7:0] o_RX_Byte,
    input i_TX_DV,
    input [7:0] i_TX_Byte,
    input i_SPI_Clk,
    output reg o_SPI_MISO,
    input i_SPI_MOSI,
    input i_SPI_CS_n
);

    // Internal registers
    reg [7:0] r_RX_Byte;
    reg [7:0] r_TX_Byte;
    reg [2:0] r_Bit_Count;
    reg [1:0] r_Clk_Phase;
    reg [1:0] r_Clk_Polarity;
    reg r_RX_DV;
    reg r_TX_DV;
    reg r_SPI_MISO;
    reg r_SPI_CS_n;

    // Clock phase and polarity
    always @(posedge i_Clk or negedge i_Rst_L) begin
        if (!i_Rst_L) begin
            r_Clk_Phase <= 2'b00;
            r_Clk_Polarity <= 2'b00;
        end else begin
            r_Clk_Phase <= {r_Clk_Phase[0], ~r_Clk_Phase[0]};
            r_Clk_Polarity <= {r_Clk_Polarity[0], r_Clk_Polarity[0]};
        end
    end

    // Receive data
    always @(posedge i_SPI_Clk or negedge i_Rst_L) begin
        if (!i_Rst_L) begin
            r_RX_Byte <= 8'b0;
            r_Bit_Count <= 3'b0;
            r_RX_DV <= 1'b0;
        end else begin
            if (r_Clk_Phase[0] == r_Clk_Polarity[0]) begin
                r_RX_Byte <= {r_RX_Byte[6:0], i_SPI_MOSI};
                r_Bit_Count <= r_Bit_Count + 1;
                if (r_Bit_Count == 7) begin
                    r_RX_DV <= 1'b1;
                    o_RX_Byte <= r_RX_Byte;
                end
            end
        end
    end

    // Transmit data
    always @(posedge i_SPI_Clk or negedge i_Rst_L) begin
        if (!i_Rst_L) begin
            r_TX_Byte <= 8'b0;
            r_Bit_Count <= 3'b0;
            r_TX_DV <= 1'b0;
        end else begin
            if (r_Clk_Phase[0] == r_Clk_Polarity[0]) begin
                if (r_TX_DV) begin
                    o_SPI_MISO <= r_TX_Byte[7];
                    r_TX_Byte <= {r_TX_Byte[6:0], 1'b0};
                    r_Bit_Count <= r_Bit_Count + 1;
                    if (r_Bit_Count == 7) begin
                        r_TX_DV <= 1'b0;
                    end
                end else begin
                    o_SPI_MISO <= 1'b1;
                end
            end
        end
    end

    // Chip select
    always @(posedge i_Clk or negedge i_Rst_L) begin
        if (!i_Rst_L) begin
            r_SPI_CS_n <= 1'b1;
        end else begin
            if (i_SPI_CS_n == 1'b0) begin
                r_SPI_CS_n <= 1'b0;
            end else if (r_TX_DV == 1'b0 && r_RX_DV == 1'b0) begin
                r_SPI_CS_n <= 1'b1;
            end
        end
    end

    // Outputs
    assign o_RX_DV = r_RX_DV;
    assign o_SPI_MISO = r_SPI_MISO;

    // Transmit data
    always @(posedge i_Clk or negedge i_Rst_L) begin
        if (!i_Rst_L) begin
            r_TX_Byte <= 8'b0;
            r_Bit_Count <= 3'b0;
            r_TX_DV <= 1'b0;
        end else begin
            if (i_TX_DV) begin
                r_TX_Byte <= i_TX_Byte;
                r_Bit_Count <= 3'b0;
                r_TX_DV <= 1'b1;
            end else if (r_TX_DV) begin
                r_TX_Byte <= {r_TX_Byte[6:0], 1'b0};
                r_Bit_Count <= r_Bit_Count + 1;
                if (r_Bit_Count == 7) begin
                    r_TX_DV <= 1'b0;
                end
            end
        end
    end

