      if (wren) begin
        for (i = 0; i < inputsize; i = i + 1) begin
          datainmem[address1 + i] <= datain[i*DATA_WIDTH +: DATA_WIDTH];
        end
      end
      if (rden) begin
        for (i = 0; i < DATA_WIDTH*16; i = i + 1) begin
          dataoutmem_unpacked[i] <= datainmem[address2 + i];
        end
        for (i = 0; i < DATA_WIDTH*16; i = i + 1) begin
