module alu(alu_src1, alu_src2, alu_opcode, minus_is_zero, less_than, less_than_unsigned, alu_result);

  input wire [31:0] alu_src1;
  input wire [31:0] alu_src2;
  input wire [3:0] alu_opcode;
  output reg [31:0] alu_result;
  output reg minus_is_zero;
  output reg less_than;
  output reg less_than_unsigned;

  reg [32:0] internal_result;

  always @(*) begin
    case (alu_opcode)
      4'b0000: begin // addition
        internal_result = alu_src1 + alu_src2;
        alu_result = internal_result[31:0];
        minus_is_zero = (internal_result[31] == 1'b0);
        less_than = (internal_result[31] == 1'b1);
        less_than_unsigned = (internal_result[31:0] < alu_src2);
      end
      4'b0001: begin // subtraction
        internal_result = {1'b0, alu_src1} - {1'b0, alu_src2};
        alu_result = internal_result[31:0];
        minus_is_zero = (internal_result[31] == 1'b0);
        less_than = (internal_result[31] == 1'b1);
        less_than_unsigned = (internal_result[31:0] < alu_src2);
      end
      4'b0010: begin // bitwise OR
        alu_result = alu_src1 | alu_src2;
        minus_is_zero = 1'b0;
        less_than = 1'b0;
        less_than_unsigned = 1'b0;
      end
      4'b0011: begin // bitwise AND
        alu_result = alu_src1 & alu_src2;
        minus_is_zero = 1'b0;
        less_than = 1'b0;
        less_than_unsigned = 1'b0;
      end
      4'b0100: begin // bitwise XOR
        alu_result = alu_src1 ^ alu_src2;
        minus_is_zero = 1'b0;
        less_than = 1'b0;
        less_than_unsigned = 1'b0;
      end
      4'b0101: begin // left shift
        alu_result = alu_src1 << alu_src2[4:0];
        minus_is_zero = 1'b0;
        less_than = 1'b0;
        less_than_unsigned = 1'b0;
      end
      4'b0110: begin // right shift signed
        alu_result = alu_src1 >> alu_src2[4:0];
        minus_is_zero = 1'b0;
        less_than = 1'b0;
        less_than_unsigned = 1'b0;
      end
      4'b0111: begin // right shift unsigned
        alu_result = $unsigned(alu_src1) >> alu_src2[4:0];
        minus_is_zero = 1'b0;
        less_than = 1'b0;
        less_than_unsigned = 1'b0;
      end
      default: begin
        alu_result = 32'b0;
        minus_is_zero = 1'b0;
        less_than = 1'b0;
        less_than_unsigned = 1'b0;
      end
    endcase
  end

endmodule

