module KeyEncoder(Columns, Rows, Clock, Reset, OnesDigit, TensDigit, Found);
  input [3:0] Columns;
  input [3:0] Rows;
  input Clock, Reset;
  output reg [3:0] OnesDigit;
  output reg [3:0] TensDigit;
  output reg Found;

  // Define the states of the state machine
  parameter IDLE = 3'b000;
  parameter KEY1 = 3'b001;
  parameter KEY2 = 3'b010;
  parameter KEY3 = 3'b011;
  parameter KEY4 = 3'b100;
  parameter KEY5 = 3'b101;
  parameter KEY6 = 3'b110;
  parameter KEY7 = 3'b111;

  // Define the state register and next state logic
  reg [2:0] state, next_state;
  always @(posedge Clock, posedge Reset) begin
    if (Reset) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  // Define the output logic based on the current state
  always @(state, Columns, Rows) begin
    case (state)
      IDLE: begin
        OnesDigit <= 4'b0000;
        TensDigit <= 4'b0000;
        Found <= 1'b0;
        next_state <= IDLE;
      end
      KEY1: begin
        OnesDigit <= 4'b0001;
        TensDigit <= 4'b0000;
        Found <= 1'b1;
        next_state <= IDLE;
      end
      KEY2: begin
        OnesDigit <= 4'b0010;
        TensDigit <= 4'b0000;
        Found <= 1'b1;
        next_state <= IDLE;
      end
      KEY3: begin
        OnesDigit <= 4'b0011;
        TensDigit <= 4'b0000;
        Found <= 1'b1;
        next_state <= IDLE;
      end
      KEY4: begin
        OnesDigit <= 4'b0100;
        TensDigit <= 4'b0000;
        Found <= 1'b1;
        next_state <= IDLE;
      end
      KEY5: begin
        OnesDigit <= 4'b0101;
        TensDigit <= 4'b0000;
        Found <= 1'b1;
        next_state <= IDLE;
      end
      KEY6: begin
        OnesDigit <= 4'b0110;
        TensDigit <= 4'b0000;
        Found <= 1'b1;
        next_state <= IDLE;
      end
      KEY7: begin
        OnesDigit <= 4'b0111;
        TensDigit <= 4'b0000;
        Found <= 1'b1;
        next_state <= IDLE;
      end
      default: begin
        OnesDigit <= 4'b0000;
        TensDigit <= 4'b0000;
        Found <= 1'b0;
        next_state <= IDLE;
      end
    endcase
  end

  // Define the state transition logic based on the input columns and rows
  always @(state, Columns, Rows) begin
    case (state)
      IDLE: begin
        if (Columns == 4'b0001 && Rows == 4'b0001) begin
          next_state <= KEY1;
        end else if (Columns == 4'b0010 && Rows == 4'b0001) begin
          next_state <= KEY2;
        end else if (Columns == 4'b0011 && Rows == 4'b0001) begin
          next_state <= KEY3;
        end else if (Columns == 4'b0100 && Rows == 4'b0001) begin
          next_state <= KEY4;
        end else if (Columns == 4'b0101 && Rows == 4'b0001) begin
          next_state <= KEY5;
        end else if (Columns == 4'b0110 && Rows == 4'b0001) begin
          next_state <= KEY6;
        end else if (Columns == 4'b0111 && Rows == 4'b0001) begin
          next_state <= KEY7;
        end else begin
          next_state <= IDLE;
        end
      end
      default: begin
        next_state <= IDLE;
      end
    endcase
  end
endmodule

