parameter num_width = 8; // width of the input fixed-point number
parameter num_pos = 4; // position of the fixed-point in the input number
parameter res_width = 10; // width of the output rounded result

input clk;
input signed [num_width-1:0] fixed_num;
output reg signed [res_width:0] round;
output reg overflow;

reg signed [num_width-1:0] original_num;
reg signed [num_width-1:0] extracted_value;
reg signed [num_width-1:0] adjusted_value;
reg signed [num_width-1:0] final_value;
reg round_up;
reg round_down;
reg round_to_zero;

always @(posedge clk) begin
    original_num <= fixed_num;
    extracted_value <= fixed_num >> num_pos;
    round_up <= (fixed_num[num_pos-1:0] >= 5'b10000) && (fixed_num[num_pos-1] == 1'b1);
    round_down <= (fixed_num[num_pos-1:0] < 5'b10000) && (fixed_num[num_pos-1] == 1'b1);
    round_to_zero <= (fixed_num[num_pos-1:0] == 5'b00000);
    if (round_up) begin
        adjusted_value <= extracted_value + 1;
    end else if (round_down) begin
        adjusted_value <= extracted_value - 1;
    end else if (round_to_zero) begin
        adjusted_value <= extracted_value;
    end
    final_value <= (fixed_num[num_pos-1] == 1'b1) ? -adjusted_value : adjusted_value;
    overflow <= (final_value[res_width] != original_num[num_width-1]);
    round <= final_value;
end

endmodule

