module udpLoopback_lbRxMetadataIn_reg_slice #(parameter N=8)(
    input wire clk,
    input wire reset,
    input wire [N-1:0] s_data,
    input wire s_valid,
    output wire s_ready,
    output wire [N-1:0] m_data,
    output wire m_valid,
    input wire m_ready
);

    // Define the states of the FSM
    localparam ZERO = 2'b00;
    localparam ONE = 2'b01;
    localparam TWO = 2'b10;

    // Define the registers
    reg [N-1:0] data_p1;
    reg [N-1:0] data_p2;
    reg [1:0] state;

    // Define the FSM
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            state <= ZERO;
        end else begin
            case (state)
                ZERO: begin
                    if (s_valid && m_ready) begin
                        state <= ONE;
                    end
                end
                ONE: begin
                    if (s_valid && m_ready) begin
                        state <= TWO;
                    end
                end
                TWO: begin
                    if (s_valid && m_ready) begin
                        state <= ZERO;
                    end
                end
            endcase
        end
    end

    // Define the load signals
    wire load_p1;
    wire load_p2;

    assign load_p1 = (state == ONE) && s_valid && m_ready;
    assign load_p2 = (state == TWO) && s_valid && m_ready;

    // Define the output signals
    assign m_data = (state == TWO) ? data_p2 : data_p1;
    assign m_valid = (state == TWO) ? s_valid : 1'b0;
    assign s_ready = (state == ZERO) ? 1'b1 : 1'b0;

    // Define the sequential logic for the registers
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            data_p1 <= 0;
            data_p2 <= 0;
        end else begin
            if (load_p1) begin
                data_p1 <= s_data;
            end
            if (load_p2) begin
                data_p2 <= s_data;
            end
        end
    end

endmodule

module async_fifo_vjtag_to_dap (
