    wrusedw
);

    input aclr;
    input [63:0] data;
    input rdclk;
    input rdreq;
    input wrclk;
    input wrreq;
    output [63:0] q;
    output rdempty;
    output wrfull;
    output [1:0] wrusedw;

    reg [63:0] fifo [0:15];
    reg [3:0] read_ptr = 0;
    reg [3:0] write_ptr = 0;
    reg [1:0] count = 0;
    reg [1:0] usedw = 0;
    reg [1:0] full = 0;
