        if (rdreq && !empty) begin
            q <= fifo[read_ptr];
            read_ptr <= read_ptr + 1;
            count <= count - 1;
            if (read_ptr == 15) begin
                read_ptr <= 0;
            end
        end
    end

    always @(posedge wrclk) begin
        if (wrreq && !full) begin
            fifo[write_ptr] <= data;
            write_ptr <= write_ptr + 1;
            count <= count + 1;
            usedw <= usedw + 1;
            if (write_ptr == 15) begin
                write_ptr <= 0;
            end
        end
    end

    always @(posedge aclr) begin
        if (aclr) begin
            read_ptr <= 0;
            write_ptr <= 0;
            count <= 0;
            usedw <= 0;
            full <= 0;
            empty <= 1;
        end
    end

    assign rdempty = (count == 0);
    assign wrfull = (count == 16);
    assign wrusedw = usedw;

