    reg [1:0] prev_clk;
    reg [1:0] prev_synchroStatus;
    reg [1:0] prev_syncInOut;

    always @(posedge clk) begin
        if (toggle_en != prev_toggle_en) begin
            count <= count + 1;
        end
        if (count == cnt_n) begin
            threshold <= cnt_m;
