        prev_opMode <= opMode;
        prev_synch_en <= synch_en;
        prev_clk <= clk;
        prev_synchroStatus <= synchroStatus;
        prev_syncInOut <= syncInOut;
    end

    always @(posedge clk) begin
        if (opMode == 1'b0) begin
            syncInOut <= synchroStatus;
        end
        else begin
            syncInOut <= synchroStatus;
        end
        prev_opMode <= opMode;
