module shift #(parameter DATA_WIDTH=16, parameter DATA_TYPE="unsigned", parameter SHIFT_VALUE=1, parameter ASYNC=0, parameter OVERFLOW_WARNING=1)(input wire clk, input wire [DATA_WIDTH-1:0] din, output wire [DATA_WIDTH-1:0] dout, output wire [1:0] warning);

  reg [DATA_WIDTH-1:0] shift_reg;
  reg [DATA_WIDTH-1:0] shifted_data;
  reg overflow;

  always @(posedge clk) begin
    if (ASYNC) begin
      shift_reg <= din;
    end else begin
      shift_reg <= shifted_data;
    end
  end

  always @(*) begin
    if (SHIFT_VALUE > 0) begin
      if (DATA_TYPE == "unsigned") begin
        if (SHIFT_VALUE >= DATA_WIDTH) begin
          shifted_data = 0;
          overflow = 0;
        end else begin
          shifted_data = din >> SHIFT_VALUE;
          overflow = (shifted_data > din);
        end
      end else begin
        if (SHIFT_VALUE >= DATA_WIDTH) begin
          shifted_data = (din[DATA_WIDTH-1] == 1) ? {DATA_WIDTH{1'b1}} : {DATA_WIDTH{1'b0}};
          overflow = 0;
        end else begin
          shifted_data = din >> SHIFT_VALUE;
          overflow = (shifted_data[DATA_WIDTH-1] != din[DATA_WIDTH-1]) ? 1 : 0;
        end
      end
    end else begin
      shifted_data = din;
      overflow = 0;
    end
  end

  assign dout = shifted_data;

  always @(*) begin
    if (OVERFLOW_WARNING) begin
      warning = {1'b0, overflow};
    end else begin
      warning = 2'b00;
    end
  end

endmodule

