module alu_32(
    input wire [WORD_SIZE-1:0] input_a,
    input wire [WORD_SIZE-1:0] input_b,
    input wire [CONTROL_SIGNAL_SIZE-1:0] control,
    output wire zero,
    output reg cout,
    output reg err_overflow,
    output reg err_invalid_control,
    output reg [WORD_SIZE-1:0] result
);

parameter WORD_SIZE = 32;
parameter CONTROL_SIGNAL_SIZE = 4;

parameter AND = 4'b0000;
parameter OR = 4'b0001;
parameter ADD = 4'b0010;
parameter ADD_UNSIGNED = 4'b0011;
parameter SUB = 4'b0100;
parameter SLT = 4'b0101;
parameter NOR = 4'b0110;

always @(*) begin
    case (control)
        AND: result = input_a & input_b;
        OR: result = input_a | input_b;
        ADD: result = $signed(input_a) + $signed(input_b);
        ADD_UNSIGNED: result = input_a + input_b;
        SUB: result = $signed(input_a) - $signed(input_b);
        SLT: result = ($signed(input_a) < $signed(input_b)) ? 1 : 0;
        NOR: result = ~(input_a | input_b);
        default: result = 0;
    endcase

    zero = (result == 0) ? 1 : 0;

    if (control == ADD || control == ADD_UNSIGNED) begin
        if (input_a[WORD_SIZE-1] == input_b[WORD_SIZE-1] && input_a[WORD_SIZE-1] != result[WORD_SIZE-1]) begin
            err_overflow = 1;
        end else begin
            err_overflow = 0;
        end
    end else if (control == SUB) begin
        if (input_a[WORD_SIZE-1] != input_b[WORD_SIZE-1] && input_a[WORD_SIZE-1] != result[WORD_SIZE-1]) begin
            err_overflow = 1;
        end else begin
            err_overflow = 0;
        end
    end else begin
        err_overflow = 0;
    end

    if (control == ADD || control == SUB || control == AND || control == OR || control == NOR) begin
        cout = result[WORD_SIZE-1];
    end else begin
        cout = 0;
    end

    if (control == ADD || control == SUB || control == AND || control == OR || control == NOR) begin
        err_invalid_control = 0;
    end else begin
        err_invalid_control = 1;
    end
end

endmodule

