module Processor(input CLK, input print, input [7:0] data, output reg RW, output reg [7:0] Din, output reg ADDR, input IRQ, input [7:0] Dout);

  // Internal registers to hold control signals and data during the transfer process
  reg [7:0] control_reg;
  reg [7:0] data_reg;

  // State machine states
  parameter IDLE = 2'b00;
  parameter WRITE = 2'b01;
  parameter INTERRUPT = 2'b10;

  // State machine variables
  reg [1:0] state;
  reg [7:0] address;
  reg [7:0] data;

  // Timing variables
  reg [7:0] delay_counter;

  // Initialize state machine
  initial begin
    state = IDLE;
    control_reg = 8'b00000000;
    data_reg = 8'b00000000;
    delay_counter = 8'b00000000;
  end

  // State machine
  always @(posedge CLK) begin
    case(state)
      IDLE: begin
        if(print) begin
          state = WRITE;
          control_reg = 8'b00000001;
          data_reg = data;
          address = 8'b00000000;
        end else if(IRQ) begin
          state = INTERRUPT;
          control_reg = 8'b00000010;
          address = 8'b00000000;
        end
      end
      WRITE: begin
        if(delay_counter == 8'b11111111) begin
          Din = data_reg;
          RW = 1;
          ADDR = address;
          state = IDLE;
          control_reg = 8'b00000000;
          data_reg = 8'b00000000;
          delay_counter = 8'b00000000;
        end else begin
          delay_counter = delay_counter + 1;
        end
      end
      INTERRUPT: begin
        if(Dout == 8'b11111111) begin
          Din = data_reg;
          RW = 1;
          ADDR = address;
          state = IDLE;
          control_reg = 8'b00000000;
          data_reg = 8'b00000000;
          delay_counter = 8'b00000000;
        end
      end
    endcase
  end

endmodule

