module pwm #(parameter WAVE_WEIGHT=1024,parameter WAVE_LEN_WIDTH=11)(input wire clk, input wire reset, input wire update, input wire [WAVE_LEN_WIDTH-1:0] wave_length, input wire [WAVE_LEN_WIDTH-1:0] pulse_width, input wire active_high, output wire [WAVE_LEN_WIDTH-1:0] wave_length_out, output wire [WAVE_LEN_WIDTH-1:0] pulse_width_out, output wire active_high_out, input wire enable, output wire pwm_out);
module pwm #(parameter WAVE_WEIGHT=1024,parameter WAVE_LEN_WIDTH=11)(input wire clk, input wire reset, input wire update, input wire [WAVE_LEN_WIDTH-1:0] wave_length, input wire [WAVE_LEN_WIDTH-1:0] pulse_width, input wire active_high, output wire [WAVE_LEN_WIDTH-1:0] wave_length_out, output wire [WAVE_LEN_WIDTH-1:0] pulse_width_out, output wire active_high_out, input wire enable, output wire pwm_out);

  reg [WAVE_LEN_WIDTH-1:0] wave_length_reg;
  reg [WAVE_LEN_WIDTH-1:0] pulse_width_reg;
  reg active_high_reg;
  reg [WAVE_LEN_WIDTH-1:0] counter;
  reg [WAVE_LEN_WIDTH-1:0] wave_length_counter;
  reg [WAVE_LEN_WIDTH-1:0] pulse_width_counter;
  reg [WAVE_LEN_WIDTH-1:0] wave_length_next;
  reg [WAVE_LEN_WIDTH-1:0] pulse_width_next;
  reg active_high_next;
  reg [WAVE_LEN_WIDTH-1:0] wave_length_out_reg;
  reg [WAVE_LEN_WIDTH-1:0] pulse_width_out_reg;
  reg active_high_out_reg;
  reg pwm_out_reg;

  always @(posedge clk) begin
    if (reset) begin
      wave_length_reg <= 0;
      pulse_width_reg <= 0;
      active_high_reg <= 0;
      counter <= 0;
      wave_length_counter <= 0;
      pulse_width_counter <= 0;
      wave_length_next <= 0;
      pulse_width_next <= 0;
      active_high_next <= 0;
      wave_length_out_reg <= 0;
      pulse_width_out_reg <= 0;
      active_high_out_reg <= 0;
      pwm_out_reg <= 0;
    end else begin
      if (update) begin
        wave_length_reg <= wave_length;
        pulse_width_reg <= pulse_width;
        active_high_reg <= active_high;
        wave_length_next <= wave_length_reg;
        pulse_width_next <= pulse_width_reg;
        active_high_next <= active_high_reg;
      end
      if (enable) begin
        if (counter == wave_length_reg) begin
          counter <= 0;
          wave_length_counter <= 0;
          pulse_width_counter <= 0;
        end else begin
          counter <= counter + 1;
          if (counter == wave_length_counter) begin
            wave_length_counter <= wave_length_counter + wave_length_reg;
            pulse_width_counter <= pulse_width_counter + pulse_width_reg;
          end
          if (counter == pulse_width_counter) begin
            pwm_out_reg <= active_high_reg;
          end else begin
            pwm_out_reg <= ~active_high_reg;
          end
        end
      end else begin
        pwm_out_reg <= 0;
      end
      wave_length_out_reg <= wave_length_next;
      pulse_width_out_reg <= pulse_width_next;
      active_high_out_reg <= active_high_next;
    end
  end

  assign wave_length_out = wave_length_out_reg;
  assign pulse_width_out = pulse_width_out_reg;
  assign active_high_out = active_high_out_reg;
  assign pwm_out = pwm_out_reg;

endmodule

module dffeas(d, clk, ena, clrn, prn, aload, asdata, sclr, sload, devclrn, devpor, q);

  parameter POWER_UP = 1'b0;
  parameter WYSIWYG = 1'b0;
  parameter VIOLATION_HANDLING = 1'b0;

  input d;
  input clk;
  input ena;
  input clrn;
  input prn;
  input aload;
  input asdata;
  input sclr;
  input sload;
  input devclrn;
  input devpor;
  output q;

  reg q_tmp;
  reg d_viol;
  reg sclr_viol;
  reg asdata_dly;

  always @(posedge clk or negedge devclrn or negedge devpor) begin
    if (devpor == 1'b0) begin
      q_tmp <= 1'b0;
    end else if (devclrn == 1'b0) begin
      q_tmp <= 1'b1;
    end else if (sclr == 1'b1) begin
      q_tmp <= 1'b0;
    end else if (sload == 1'b1) begin
      q_tmp <= asdata;
    end else if (ena == 1'b1) begin
      if (d_viol == 1'b1) begin
        q_tmp <= q_tmp;
      end else if (sclr_viol == 1'b1) begin
        q_tmp <= q_tmp;
      end else begin
        q_tmp <= d;
      end
    end
  end

  always @(posedge clk) begin
    asdata_dly <= asdata;
  end

  always @(posedge clk) begin
    if (aload == 1'b1) begin
      d_viol <= 1'b0;
    end else if (d != asdata_dly) begin
      d_viol <= 1'b1;
    end
  end

  always @(posedge clk) begin
    if (sclr == 1'b1) begin
      sclr_viol <= 1'b0;
    end else if (sclr_viol == 1'b0 && sclr == 1'b0 && q_tmp != asdata_dly) begin
      sclr_viol <= 1'b1;
    end
  end

  assign q = (VIOLATION_HANDLING == 1'b1 && sclr_viol == 1'b1) ? 1'bz : q_tmp;

endmodule

module scan_hex_led_disp(
    input clk,
    input reset,
    input [3:0] hex3,
    input [3:0] hex2,
    input [3:0] hex1,
    input [3:0] hex0,
    input [3:0] dp,
    output reg [3:0] en,
    output reg [7:0] sseg
);

    reg [3:0] counter;
    reg [3:0] hex_val;
    reg [3:0] dp_val;
    reg [1:0] state;

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            counter <= 4'b0000;
            state <= 2'b00;
            en <= 4'b0000;
            sseg <= 8'b00000000;
        end else begin
            case (state)
                2'b00: begin
                    en <= 4'b0001;
                    hex_val <= hex0;
                    dp_val <= dp[0];
                    state <= 2'b01;
                end
                2'b01: begin
                    en <= 4'b0010;
                    hex_val <= hex1;
                    dp_val <= dp[1];
                    state <= 2'b10;
                end
                2'b10: begin
                    en <= 4'b0100;
                    hex_val <= hex2;
                    dp_val <= dp[2];
                    state <= 2'b11;
                end
                2'b11: begin
                    en <= 4'b1000;
                    hex_val <= hex3;
                    dp_val <= dp[3];
                    state <= 2'b00;
                end
            endcase

            case (hex_val)
                4'b0000: sseg <= 8'b11000000;
                4'b0001: sseg <= 8'b11111001;
                4'b0010: sseg <= 8'b10100100;
                4'b0011: sseg <= 8'b10110000;
                4'b0100: sseg <= 8'b10011001;
                4'b0101: sseg <= 8'b10010010;
                4'b0110: sseg <= 8'b10000010;
                4'b0111: sseg <= 8'b11111000;
                4'b1000: sseg <= 8'b10000000;
                4'b1001: sseg <= 8'b10010000;
                4'b1010: sseg <= 8'b10001000;
                4'b1011: sseg <= 8'b10000011;
                4'b1100: sseg <= 8'b10100111;
                4'b1101: sseg <= 8'b10100001;
                4'b1110: sseg <= 8'b10000110;
                4'b1111: sseg <= 8'b10001110;
            endcase

            if (dp_val) begin
                sseg[7] <= 1'b1;
            end else begin
                sseg[7] <= 1'b0;
            end
        end
    end

endmodule

module linear_layer(
    input [63:0] x0,
    input [63:0] x1,
    input [63:0] x2,
    input [63:0] x3,
    input [63:0] x4,
    output [63:0] o0,
    output [63:0] o1,
    output [63:0] o2,
    output [63:0] o3,
    output [63:0] o4
);

    // Define rotation patterns
    parameter ROT_PATTERN0 = 6'b000001;
    parameter ROT_PATTERN1 = 6'b000010;
    parameter ROT_PATTERN2 = 6'b000100;
    parameter ROT_PATTERN3 = 6'b001000;
    parameter ROT_PATTERN4 = 6'b010000;

    // Apply bitwise operations
    assign o0 = x0 ^ (x1 << ROT_PATTERN0) ^ (x2 << ROT_PATTERN1) ^ (x3 << ROT_PATTERN2) ^ (x4 << ROT_PATTERN3);
    assign o1 = x1 ^ (x2 << ROT_PATTERN0) ^ (x3 << ROT_PATTERN1) ^ (x4 << ROT_PATTERN2) ^ (x0 << ROT_PATTERN3);
    assign o2 = x2 ^ (x3 << ROT_PATTERN0) ^ (x4 << ROT_PATTERN1) ^ (x0 << ROT_PATTERN2) ^ (x1 << ROT_PATTERN3);
    assign o3 = x3 ^ (x4 << ROT_PATTERN0) ^ (x0 << ROT_PATTERN1) ^ (x1 << ROT_PATTERN2) ^ (x2 << ROT_PATTERN3);
    assign o4 = x4 ^ (x0 << ROT_PATTERN0) ^ (x1 << ROT_PATTERN1) ^ (x2 << ROT_PATTERN2) ^ (x3 << ROT_PATTERN3);

endmodule

