      2'b01: tmp = {data_i, 3'b000} >> 1;
      2'b10: tmp = {data_i, 3'b000} >> 2;
      2'b11: tmp = {data_i, 3'b000} >> 3;
    endcase
  end

  assign data_o = tmp;

endmodule

