module binary_updown_counter #(parameter BITS=1)(input wire clk, input wire rst, input wire ena, input wire updown, output reg [BITS-1:0] out, output reg ovf);
    reg [BITS-1:0] cnt;
    wire [BITS-1:0] enable_wires;

    assign enable_wires = {BITS{ena}};

    always @(posedge clk, negedge rst) begin
        if (!rst) begin
            cnt <= 0;
            ovf <= 0;
        end else if (ena) begin
            if (updown) begin
                if (cnt == 0) begin
                    cnt <= {BITS{1'b1}};
                    ovf <= 1;
                end else begin
                    cnt <= cnt - 1;
                    ovf <= 0;
                end
            end else begin
                if (cnt == {BITS{1'b1}}) begin
                    cnt <= 0;
                    ovf <= 1;
                end else begin
                    cnt <= cnt + 1;
                    ovf <= 0;
                end
            end
        end
    end

    always @(posedge clk) begin
        out <= cnt;
    end

    genvar i;
    generate
        for (i = 0; i < BITS; i = i + 1) begin : enable_wire_gen
            always @(posedge clk) begin
                enable_wires[i] <= ena;
            end
        end
    endgenerate
endmodule

module BCD(input [15:0] binary, output wire [3:0] b, output wire [3:0] s, output wire [3:0] g, output wire [3:0] q);
reg [31:0] register;
integer i;

always @(*) begin
    register = {binary, 16'b0};
    for (i = 0; i < 16; i = i + 1) begin
        if (register[3:0] > 4) begin
            register[3:0] = register[3:0] + 3;
        end
        if (register[7:4] > 4) begin
            register[7:4] = register[7:4] + 3;
        end
        if (register[11:8] > 4) begin
            register[11:8] = register[11:8] + 3;
        end
        if (register[15:12] > 4) begin
            register[15:12] = register[15:12] + 3;
        end
        register = {register[30:0], register[31]};
    end
end

assign b = register[3:0];
assign s = register[7:4];
assign g = register[11:8];
assign q = register[15:12];

endmodule

module risc_v_32_mem(m_addr, d_f_mem, inst_decode, mem_out);
