input [31:0] d_f_mem;
input [36:0] inst_decode;
output reg [31:0] mem_out;

wire [1:0] i_lw;
wire i_lbu;
wire i_lb;
wire i_lhu;
wire i_lh;

assign i_lw = inst_decode[36:35];
assign i_lbu = inst_decode[34];
assign i_lb = inst_decode[33];
assign i_lhu = inst_decode[32];
assign i_lh = inst_decode[31];

always @(*) begin
    case (i_lw)
        2'b00: mem_out = d_f_mem;
        2'b01: mem_out = {16'b0, d_f_mem[15:0]};
        2'b10: mem_out = {16'b0, d_f_mem[31:16]};
        2'b11: mem_out = {16'b0, d_f_mem[15:0]};
