    case (i_lbu)
        1'b0: mem_out = d_f_mem;
        1'b1: mem_out = {24'b0, d_f_mem[7:0]};
    endcase

    case (i_lb)
        1'b0: mem_out = d_f_mem;
        1'b1: mem_out = {24'b0, d_f_mem[7:0]};
    endcase

    case (i_lhu)
        1'b0: mem_out = d_f_mem;
        1'b1: mem_out = {16'b0, d_f_mem[15:0]};
    endcase

    case (i_lh)
        1'b0: mem_out = d_f_mem;
