module wb_bridge_16_32#(parameter AWIDTH=16)(
    input wb_clk,
    input wb_rst,
    input A_cyc_i,
    input A_stb_i,
    input A_we_i,
    input [3:0] A_sel_i,
    input [AWIDTH-1:0] A_adr_i,
    input [31:0] A_dat_i,
    output [31:0] A_dat_o,
    output A_ack_o,
    output B_cyc_o,
    output B_stb_o,
    output B_we_o,
    output [1:0] B_sel_o,
    output [AWIDTH-1:0] B_adr_o,
    output [15:0] B_dat_o,
    input [15:0] B_dat_i,
    input B_ack_i
);

    reg [1:0] phase;
    reg [15:0] data_out;
    reg [15:0] data_in;
    reg [AWIDTH-1:0] addr;
    reg [3:0] sel;
    reg we;
    reg stb;
    reg cyc;
    reg ack;

    always @(posedge wb_clk) begin
        if (wb_rst) begin
            phase <= 2'b00;
            data_out <= 16'h0000;
            data_in <= 16'h0000;
            addr <= 0;
            sel <= 4'b0000;
            we <= 1'b0;
            stb <= 1'b0;
            cyc <= 1'b0;
            ack <= 1'b0;
        end else begin
            case (phase)
                2'b00: begin // Idle phase
                    if (A_cyc_i && A_stb_i) begin
                        phase <= 2'b01;
                        addr <= A_adr_i;
                        sel <= A_sel_i;
                        we <= A_we_i;
                        stb <= 1'b1;
                        cyc <= 1'b1;
                        if (A_we_i) begin
                            data_in <= A_dat_i[15:0];
                        end else begin
                            data_in <= 16'h0000;
                        end
                    end
                end
                2'b01: begin // Read phase
                    if (B_ack_i) begin
                        phase <= 2'b10;
                        data_out <= B_dat_i;
                        stb <= 1'b0;
                        cyc <= 1'b0;
                        ack <= 1'b1;
                    end
                end
                2'b10: begin // Write phase
                    if (B_ack_i) begin
                        phase <= 2'b00;
                        stb <= 1'b0;
                        cyc <= 1'b0;
                        ack <= 1'b1;
                    end
                end
            endcase
        end
    end

    assign B_cyc_o = cyc;
    assign B_stb_o = stb;
    assign B_we_o = we;
    assign B_sel_o = sel;
    assign B_adr_o = addr;
    assign B_dat_o = data_out;
    assign A_dat_o = {16'h0000, data_in};
    assign A_ack_o = ack;

endmodule

