module IB_ENDPOINT_OP_DONE_BUFFER(input wire CLK, input wire RESET, input wire [15:0] RD_COMPL_TAG, input wire RD_COMPL_START, input wire RD_COMPL_DONE, input wire [15:0] BM_TAG, input wire BM_DONE, output wire [15:0] OP_TAG, output wire OP_DONE);
module IB_ENDPOINT_OP_DONE_BUFFER(
    input wire CLK,
    input wire RESET,
    input wire [15:0] RD_COMPL_TAG,
    input wire RD_COMPL_START,
    input wire RD_COMPL_DONE,
    input wire [15:0] BM_TAG,
    input wire BM_DONE,
    output wire [15:0] OP_TAG,
    output wire OP_DONE
);

reg [15:0] stored_read_compl_tag;
reg [15:0] stored_bm_tag;
reg read_compl_started;
reg bm_done_started;
reg [15:0] op_tag;
reg op_done;

always @(posedge CLK) begin
    if (RESET) begin
        stored_read_compl_tag <= 16'h0000;
        stored_bm_tag <= 16'h0000;
        read_compl_started <= 1'b0;
        bm_done_started <= 1'b0;
        op_tag <= 16'h0000;
        op_done <= 1'b0;
    end else begin
        if (RD_COMPL_START) begin
            stored_read_compl_tag <= RD_COMPL_TAG;
            read_compl_started <= 1'b1;
        end else if (RD_COMPL_DONE) begin
            op_tag <= stored_read_compl_tag;
            op_done <= 1'b1;
            read_compl_started <= 1'b0;
        end

        if (BM_DONE) begin
            stored_bm_tag <= BM_TAG;
            bm_done_started <= 1'b1;
        end else if (RD_COMPL_DONE) begin
            op_tag <= stored_bm_tag;
            op_done <= 1'b1;
            bm_done_started <= 1'b0;
        end

        if (read_compl_started && !bm_done_started) begin
            op_tag <= stored_read_compl_tag;
            op_done <= 1'b1;
        end else if (!read_compl_started && bm_done_started) begin
            op_tag <= stored_bm_tag;
            op_done <= 1'b1;
        end
    end
end

assign OP_TAG = op_tag;
assign OP_DONE = op_done;

endmodule

