    input shiftnld;
    input captnupdt;
    output mainclk;
    output updateclk;
    output capture;
    output update;

    reg [1:0] state;
    reg [1:0] next_state;

    always @(posedge clk) begin
        state <= next_state;
    end

    always @(captnupdt, shiftnld, state) begin
        case(state)
            2'b00: begin
                if(captnupdt == 2'b01) begin
                    next_state = 2'b01;
                end else begin
                    next_state = 2'b00;
                end
            end
            2'b01: begin
                if(captnupdt == 2'b10) begin
                    next_state = 2'b10;
                end else begin
                    next_state = 2'b01;
                end
            end
            2'b10: begin
                if(shiftnld == 1'b1) begin
                    next_state = 2'b00;
                end else begin
                    next_state = 2'b10;
                end
            end
            default: begin
                next_state = 2'b00;
            end
        endcase
    end

    assign mainclk = (state == 2'b00) ? clk : 1'b0;
    assign updateclk = (state == 2'b01) ? clk : 1'b0;
    assign capture = (state == 2'b10) ? 1'b1 : 1'b0;
    assign update = (state == 2'b01) ? 1'b1 : 1'b0;

endmodule

