module alu#(parameter WIDTH=32)(input [WIDTH-1:0] a, b, input [2:0] m, output reg [WIDTH-1:0] y, output reg zf, output reg cf, output reg of);

  always @(*) begin
    case(m)
      3'b000: begin // addition
        {cf, y} = a + b;
        of = (a[WIDTH-1] == b[WIDTH-1]) && (y[WIDTH-1] != a[WIDTH-1]);
      end
      3'b001: begin // subtraction
        {cf, y} = a - b;
        of = (a[WIDTH-1] != b[WIDTH-1]) && (y[WIDTH-1] != a[WIDTH-1]);
      end
      3'b010: begin // bitwise AND
        y = a & b;
        cf = 1'b0;
        of = 1'b0;
      end
      3'b011: begin // bitwise OR
        y = a | b;
        cf = 1'b0;
        of = 1'b0;
      end
      3'b100: begin // bitwise XOR
        y = a ^ b;
        cf = 1'b0;
        of = 1'b0;
      end
      default: begin // default case
        y = 0;
        cf = 1'b0;
        of = 1'b0;
      end
    endcase
    zf = (y == 0);
  end

endmodule

