module ff_d_nand(output reg Q, input D, CLK, CLR_BAR);

    reg Q_prev;
    integer counter;
    parameter Vcc = 1.8;
    parameter C_L = 1e-15;
    parameter t_hmin = 100;
    parameter t_hmax = 100;

    always @(posedge CLK) begin
        if (CLR_BAR) begin
            Q <= 0;
            counter <= 0;
        end else begin
            Q <= D ^ Q_prev;
            if (Q != Q_prev) begin
                counter <= counter + 1;
            end
        end
        Q_prev <= Q;
    end

    always @(posedge CLK) begin
        if (counter > 0) begin
            $display("Power dissipation: %f mW", counter*C_L*Vcc**2);
            counter <= 0;
        end
    end

endmodule

