    if (count == 32'd1_000_000) begin
        if (inputbtn_input == pre) begin
            outputregbtn_output <= inputbtn_input;
            timer <= 0;
            pre <= inputbtn_input;
        end
        else begin
            timer <= 0;
        end
    end
