    if (~rst_n) begin
        signal_in_prev <= 1'b0;
        rising_out <= 1'b0;
        falling_out <= 1'b0;
    end else begin
        if (signal_in > signal_in_prev) begin
            rising_out <= 1'b1;
            falling_out <= 1'b0;
        end else if (signal_in < signal_in_prev) begin
            rising_out <= 1'b0;
            falling_out <= 1'b1;
        end else begin
            rising_out <= 1'b0;
            falling_out <= 1'b0;
