          out_reg <= ~out_reg;
        end else if (in[0]) begin
          out_reg <= 1'b1;
        end else if (in[1]) begin
          out_reg <= 1'b0;
        end
      end
    end else if (TYPE == "T") begin
      always @(posedge clk) begin
        out_reg <= in;
      end
    end
  endgenerate

  assign out = out_reg;

