module toe_m_axis_rx_data_rsp_metadata_reg_slice#(parameterN=8)(input wire clk, input wire reset, input wire [N-1:0] s_data, input wire s_valid, output wire s_ready, output wire [N-1:0] m_data, output wire m_valid, input wire m_ready);
module toe_m_axis_rx_data_rsp_metadata_reg_slice#(parameterN=8)(input wire clk, input wire reset, input wire [N-1:0] s_data, input wire s_valid, output wire s_ready, output wire [N-1:0] m_data, output wire m_valid, input wire m_ready);

  reg [N-1:0] data_p1;
  reg [N-1:0] data_p2;
  reg load_p1;
  reg load_p2;
  reg [1:0] state;

  always @(posedge clk) begin
    if (reset) begin
      state <= 2'b00;
      load_p1 <= 1'b0;
      load_p2 <= 1'b0;
    end else begin
      case (state)
        2'b00: begin // ZERO state
          if (s_valid && !m_ready) begin
            state <= 2'b01;
            load_p1 <= 1'b1;
          end
        end
        2'b01: begin // ONE state
          if (s_valid && m_ready) begin
            state <= 2'b10;
            load_p2 <= 1'b1;
          end
        end
        2'b10: begin // TWO state
          if (!s_valid && m_ready) begin
            state <= 2'b00;
            load_p1_from_p2 <= 1'b1;
          end
        end
      endcase
    end
  end

  always @(posedge clk) begin
    if (load_p1) begin
      data_p1 <= s_data;
    end
    if (load_p2) begin
      data_p2 <= s_data;
    end
    if (load_p1_from_p2) begin
      data_p1 <= data_p2;
    end
  end

  assign m_data = data_p1;
  assign m_valid = (state == 2'b10) ? 1'b1 : 1'b0;
  assign s_ready = (state == 2'b00) ? 1'b1 : 1'b0;

endmodule

module Incer#(parameter DATA_WIDTH=8)(clk, arstn, din, dout, mode);
