    output [DATA_WIDTH-1:0] dout;

    reg [DATA_WIDTH-1:0] counter;
    reg [1:0] state;

    parameter ADD_STATE = 2'b00;
    parameter INC_STATE = 2'b01;

    always @(posedge clk or negedge arstn) begin
        if (~arstn) begin
            counter <= 0;
            state <= ADD_STATE;
        end
        else begin
            case (state)
                ADD_STATE: begin
                    if (mode) begin
                        counter <= din + 1;
                        state <= ADD_STATE;
                    end
                    else begin
                        counter <= din + 2;
                        state <= INC_STATE;
                    end
                end
                INC_STATE: begin
                    counter <= counter + 1;
                    state <= INC_STATE;
                end
            endcase
        end
    end

    assign dout = counter;

endmodule

