module Counter_Controller #(parameter DWIDTH=7)(
    input clk,
    input rst_n,
    input start_i,
    input [DWIDTH-1:0] cnt_val_i,
    input [DWIDTH-1:0] cnt_i,
    output reg run_o,
    output reg done_o
);

    // Define the states of the FSM
    parameter S_IDLE = 2'b00;
    parameter S_RUN = 2'b01;
    parameter S_DONE = 2'b10;

    // Define the state and state_n registers
    reg [1:0] state, state_n;

    // Define the counter value and counter value_n registers
    reg [DWIDTH-1:0] cnt_val, cnt_val_n;

    // Define the run and done flags
    reg run, done;

    // Define the clock and reset signals
    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= S_IDLE;
            cnt_val <= 0;
            run <= 0;
            done <= 0;
        end else begin
            state <= state_n;
            cnt_val <= cnt_val_n;
            run <= run_o;
            done <= done_o;
        end
    end

    // Define the state machine
    always @(*) begin
        state_n = state;
        cnt_val_n = cnt_val;
        run_o = 0;
        done_o = 0;

        case (state)
            S_IDLE: begin
                if (start_i) begin
                    state_n = S_RUN;
                    cnt_val_n = cnt_val_i;
                end
            end
            S_RUN: begin
                if (cnt_i >= cnt_val) begin
                    state_n = S_DONE;
                    run_o = 1;
                end else begin
                    cnt_val_n = cnt_val - 1;
                end
            end
            S_DONE: begin
                done_o = 1;
                state_n = S_IDLE;
            end
        endcase
    end

endmodule

