module Control(
    input clk,
    input start,
    output reg [3:0] direction,
    output reg ready
);

    // Define the states
    parameter IDLE = 2'b00;
    parameter RUNNING = 2'b01;
    parameter DONE = 2'b10;

    // Define the state register
    reg [1:0] state;

    // Define the direction encoding scheme
    parameter UP = 4'b0001;
    parameter DOWN = 4'b0010;
    parameter LEFT = 4'b0100;
    parameter RIGHT = 4'b1000;

    // Define the state transition rules
    always @(posedge clk) begin
        case (state)
            IDLE: begin
                if (start) begin
                    state <= RUNNING;
                    direction <= UP;
                    ready <= 1'b0;
                end
            end
            RUNNING: begin
                if (state[1:0] == 2'b00) begin
                    direction <= DOWN;
                end else if (state[1:0] == 2'b01) begin
                    direction <= LEFT;
                end else if (state[1:0] == 2'b10) begin
                    direction <= RIGHT;
                end
                if (state[1:0] == 2'b11) begin
                    state <= DONE;
                    ready <= 1'b1;
                end
            end
            DONE: begin
                if (start) begin
                    state <= IDLE;
                    ready <= 1'b0;
                end
            end
        endcase
    end

endmodule

