module parc_ifu_esl_lfsr(
  input clk,
  input rst_n,
  input [15:0] lfsr_seed,
  input lfsr_ld,
  input lfsr_step,
  output reg [15:0] lfsr_state_f,
  output reg lfsr_out_f
);

  reg [15:0] lfsr_state;
  reg [15:0] lfsr_next_state;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      lfsr_state <= 16'h0000;
    end else if (lfsr_ld) begin
      lfsr_state <= lfsr_seed;
    end else begin
      lfsr_state <= lfsr_next_state;
    end
  end

  always @(*) begin
    lfsr_next_state[0] = lfsr_state[15] ^ lfsr_state[14];
    lfsr_next_state[1] = lfsr_state[0];
    lfsr_next_state[2] = lfsr_state[1];
    lfsr_next_state[3] = lfsr_state[2];
    lfsr_next_state[4] = lfsr_state[3];
    lfsr_next_state[5] = lfsr_state[4];
    lfsr_next_state[6] = lfsr_state[5];
    lfsr_next_state[7] = lfsr_state[6];
    lfsr_next_state[8] = lfsr_state[7];
    lfsr_next_state[9] = lfsr_state[8];
    lfsr_next_state[10] = lfsr_state[9];
    lfsr_next_state[11] = lfsr_state[10];
    lfsr_next_state[12] = lfsr_state[11];
    lfsr_next_state[13] = lfsr_state[12];
    lfsr_next_state[14] = lfsr_state[13];
    lfsr_next_state[15] = lfsr_state[14] ^ lfsr_state[15];
  end

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      lfsr_out_f <= 1'b0;
    end else if (lfsr_ld) begin
      lfsr_out_f <= lfsr_seed[15];
    end else if (lfsr_step) begin
      lfsr_out_f <= lfsr_next_state[15];
    end
  end

  assign lfsr_state_f = lfsr_state;

endmodule

