module murmur3_data(
    input clk,
    input rstn,
    input [127:0] i_data,
    input ld_init,
    input ld_partial,
    input [1:0] sel_mux,
    input ld_seed,
    input sel_init_seed,
    input ld_result,
    input ld_partial_hash_sub,
    input ld_res_sub_1,
    input ld_res_sub_2,
    input ld_final,
    output [31:0] o_hash_key
);

    // Internal registers
    reg [31:0] h1, h2, h3, h4;
    reg [31:0] k1, k2, k3, k4;
    reg [31:0] s1, s2, s3, s4;
    reg [31:0] partial_hash;
    reg [31:0] res_sub_1, res_sub_2;
    reg [31:0] final;

    // Constants
    parameter [31:0] c1 = 0x239b961b;
    parameter [31:0] c2 = 0xab0e978d;
    parameter [31:0] c3 = 0x85ebca6b;
    parameter [31:0] c4 = 0xc2b2ae3d;

    // Initialization
    always @(posedge clk or negedge rstn) begin
        if (!rstn) begin
            h1 <= 0;
            h2 <= 0;
            h3 <= 0;
            h4 <= 0;
            k1 <= 0;
            k2 <= 0;
            k3 <= 0;
            k4 <= 0;
            s1 <= 0;
            s2 <= 0;
            s3 <= 0;
            s4 <= 0;
            partial_hash <= 0;
            res_sub_1 <= 0;
            res_sub_2 <= 0;
            final <= 0;
        end else begin
            if (ld_init) begin
                h1 <= i_data[31:0];
                h2 <= i_data[63:32];
                h3 <= i_data[95:64];
                h4 <= i_data[127:96];
            end
            if (ld_seed) begin
                h1 <= sel_init_seed ? 0 : h1;
                h2 <= sel_init_seed ? 0 : h2;
                h3 <= sel_init_seed ? 0 : h3;
                h4 <= sel_init_seed ? 0 : h4;
            end
        end
    end

    // Partial hashing
    always @(posedge clk) begin
        if (ld_partial) begin
            k1 <= i_data[31:0];
            k2 <= i_data[63:32];
            k3 <= i_data[95:64];
            k4 <= i_data[127:96];
        end
        s1 <= k1 * c1;
        s2 <= k2 * c2;
        s3 <= k3 * c3;
        s4 <= k4 * c4;
    end

    // Seed updating
    always @(posedge clk) begin
        if (ld_seed) begin
            h1 <= h1 + s1;
            h2 <= h2 + s2;
            h3 <= h3 + s3;
            h4 <= h4 + s4;
        end
    end

    // Result finalization
    always @(posedge clk) begin
        if (ld_result) begin
            res_sub_1 <= h1 ^ h2 ^ h3 ^ h4;
        end
        if (ld_partial_hash_sub) begin
            partial_hash <= res_sub_1;
        end
        if (ld_res_sub_1) begin
            res_sub_1 <= res_sub_1 * c1;
        end
        if (ld_res_sub_2) begin
            res_sub_2 <= res_sub_1 * c2;
        end
        if (ld_final) begin
            final <= res_sub_2 + partial_hash;
        end
    end

    // Output
    assign o_hash_key = final;

endmodule

