// Control flags
reg preamble_captured;
reg payload_captured;
reg crc_captured;

// State machine states
parameter IDLE = 4'b0000;
parameter CAPTURE_PREAMBLE = 4'b0001;
parameter CAPTURE_PAYLOAD = 4'b0010;
parameter CAPTURE_CRC = 4'b0011;
parameter VALIDATE_CRC = 4'b0100;
parameter CORRECT_ERROR = 4'b0101;
parameter OUTPUT_PAYLOAD = 4'b0110;

// CRC calculation
function [31:0] crc_calc;
  input [31:0] data;
  input [31:0] crc;
  begin
    crc_calc = crc ^ data;
    for (int i = 0; i < 32; i = i + 1) begin
      if (crc_calc[31] == 1) begin
        crc_calc = (crc_calc << 1) ^ GEN_POLY;
      end else begin
        crc_calc = crc_calc << 1;
      end
    end
  end
endfunction

// CRC error detection
function [31:0] crc_error_detect;
  input [31:0] data;
  input [31:0] crc;
  begin
    crc_error_detect = crc_calc(data, crc) ^ 32'hFFFFFFFF;
  end
endfunction

// Single-bit error correction
function [31:0] single_bit_error_correction;
  input [31:0] data;
  input [31:0] crc;
  begin
    for (int i = 0; i < 32; i = i + 1) begin
      if (crc_error_detect(data ^ (1 << i), crc) == 0) begin
        single_bit_error_correction = data ^ (1 << i);
      end
    end
  end
endfunction

// Main state machine
always @(posedge Clk) begin
  case (state)
    IDLE: begin
      if (Input1 == 1'b1) begin
        state <= CAPTURE_PREAMBLE;
        counter <= 0;
      end
    end
    CAPTURE_PREAMBLE: begin
      preamble[counter] <= Input1;
      counter <= counter + 1;
      if (counter == 16) begin
        preamble_captured <= 1;
        state <= CAPTURE_PAYLOAD;
        counter <= 0;
      end
    end
    CAPTURE_PAYLOAD: begin
      payload[counter] <= Input1;
      counter <= counter + 1;
      if (counter == 12000) begin
        payload_captured <= 1;
        state <= CAPTURE_CRC;
        counter <= 0;
      end
    end
    CAPTURE_CRC: begin
      crc_data[counter] <= Input1;
      counter <= counter + 1;
      if (counter == 32) begin
        crc_captured <= 1;
        state <= VALIDATE_CRC;
        counter <= 0;
      end
    end
    VALIDATE_CRC: begin
      if (crc_error_detect(payload, crc_data) == 0) begin
        state <= OUTPUT_PAYLOAD;
      end else begin
        state <= CORRECT_ERROR;
      end
    end
    CORRECT_ERROR: begin
      payload <= single_bit_error_correction(payload, crc_data);
      state <= OUTPUT_PAYLOAD;
    end
    OUTPUT_PAYLOAD: begin
      Z <= payload;
      state <= IDLE;
    end
  endcase
