    case(ALUSel[2:0])
      3'b000: ALU_o = A + B;
      3'b001: ALU_o = A - B;
      3'b010: ALU_o = A << B[4:0];
      3'b011: ALU_o = A >> B[4:0];
      3'b100: ALU_o = A ^ B;
      3'b101: ALU_o = A & B;
      3'b110: ALU_o = A | B;
      3'b111: ALU_o = (A < B) ? 1 : 0;
    endcase

    if(ALUSel[3]) begin
      ALU_o = ~ALU_o + 1;
    end
  end

