module button_pulse #(parameter MAX_COUNT=8, parameter DEC_COUNT=2, parameter MIN_COUNT=1)(
    input wire clk,
    input wire clk_en,
    input wire button,
    input wire reset,
    output reg pulse
);

    reg [31:0] count;
    reg [31:0] comp;

    always @(posedge clk) begin
        if (reset) begin
            count <= MAX_COUNT-1;
            comp <= MAX_COUNT-1;
            pulse <= 0;
        end else if (clk_en) begin
            if (button) begin
                count <= count - DEC_COUNT;
                if (count < MIN_COUNT) begin
                    count <= MAX_COUNT-1;
                    comp <= MAX_COUNT-1;
                    pulse <= 1;
                end
            end else begin
                count <= MAX_COUNT-1;
                comp <= MAX_COUNT-1;
                pulse <= 0;
            end
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            comp <= MAX_COUNT-1;
        end else if (clk_en) begin
            if (button) begin
                if (count < MIN_COUNT) begin
                    comp <= comp - DEC_COUNT;
                end
            end else begin
                comp <= MAX_COUNT-1;
            end
        end
    end

endmodule

