module echo_server_application_m_axis_read_package_reg_slice#(parameter N=8)(
  input wire clk,
  input wire reset,
  input wire [N-1:0] s_data,
  input wire s_valid,
  output wire s_ready,
  output wire [N-1:0] m_data,
  output wire m_valid,
  input wire m_ready
);

  // Internal registers
  reg [N-1:0] data_p1;
  reg [N-1:0] data_p2;
  reg load_p1;
  reg load_p2;
  reg load_p1_from_p2;
  reg [1:0] state;
  reg [1:0] next_state;

  // FSM state machine
  always @(posedge clk) begin
    if (reset) begin
      state <= 2'b00;
    end else begin
      state <= next_state;
    end
  end

  // FSM next state logic
  always @(*) begin
    case (state)
      2'b00: begin // ZERO state
        if (s_valid && m_ready) begin
          next_state = 2'b01;
        end else begin
          next_state = 2'b00;
        end
      end
      2'b01: begin // ONE state
        if (s_valid && m_ready) begin
          next_state = 2'b10;
        end else begin
          next_state = 2'b01;
        end
      end
      2'b10: begin // TWO state
        if (s_valid && m_ready) begin
          next_state = 2'b00;
        end else begin
          next_state = 2'b10;
        end
      end
      default: begin
        next_state = 2'b00;
      end
    endcase
  end

  // FSM output logic
  assign s_ready = (state == 2'b00) ? 1'b1 : 1'b0;
  assign m_valid = (state == 2'b01) ? 1'b1 : 1'b0;

  // Data transfer logic
  always @(posedge clk) begin
    if (reset) begin
      data_p1 <= 0;
      data_p2 <= 0;
      load_p1 <= 0;
      load_p2 <= 0;
      load_p1_from_p2 <= 0;
    end else begin
      case (state)
        2'b00: begin // ZERO state
          if (s_valid && m_ready) begin
            data_p1 <= s_data;
            load_p1 <= 1'b1;
          end
        end
        2'b01: begin // ONE state
          if (s_valid && m_ready) begin
            data_p2 <= data_p1;
            load_p2 <= 1'b1;
          end
        end
        2'b10: begin // TWO state
          if (s_valid && m_ready) begin
            m_data <= data_p2;
            load_p1_from_p2 <= 1'b1;
          end
        end
        default: begin
          // Do nothing
        end
      endcase
    end
  end

  // Register load logic
  always @(posedge clk) begin
    if (reset) begin
      load_p1 <= 0;
      load_p2 <= 0;
      load_p1_from_p2 <= 0;
    end else begin
      load_p1 <= (state == 2'b00) ? 1'b1 : 1'b0;
      load_p2 <= (state == 2'b01) ? 1'b1 : 1'b0;
      load_p1_from_p2 <= (state == 2'b10) ? 1'b1 : 1'b0;
    end
  end

endmodule

module fsm_seq_10010_moore(
  input clk,
  input rst_n,
  input x,
  output reg z
);

  parameter S1 = 3'b001;
  parameter S2 = 3'b010;
  parameter S3 = 3'b011;
  parameter S4 = 3'b100;
  parameter S5 = 3'b101;
  parameter S6 = 3'b110;

  reg [2:0] state, next;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      state <= S1;
    end else begin
      state <= next;
    end
  end

  always @(*) begin
    case (state)
      S1: begin
        if (x == 1'b0) begin
          next = S2;
        end else begin
          next = S1;
        end
      end
      S2: begin
        if (x == 1'b0) begin
          next = S3;
        end else begin
          next = S1;
        end
      end
      S3: begin
        if (x == 1'b0) begin
          next = S4;
        end else begin
          next = S1;
        end
      end
      S4: begin
        if (x == 1'b0) begin
          next = S5;
        end else begin
          next = S1;
        end
      end
      S5: begin
        if (x == 1'b0) begin
          next = S6;
        end else begin
          next = S1;
        end
      end
      S6: begin
        if (x == 1'b0) begin
          next = S6;
        end else begin
          next = S1;
        end
      end
    endcase
  end

  always @(posedge clk) begin
    if (state == S6) begin
      z <= 1'b1;
    end else begin
      z <= 1'b0;
    end
  end

endmodule

