  // Lookup table to map 4-bit input to 7-segment pattern
  reg [6:0] seg_lut [0:15] = {7'b100_0000, 7'b111_1001, 7'b010_0100, 7'b011_0000,
                              7'b001_1001, 7'b001_0010, 7'b000_0010, 7'b111_1000,
                              7'b000_0000, 7'b001_1000, 7'b000_0011, 7'b100_0110,
                              7'b010_0000, 7'b000_1111, 7'b000_0110, 7'b000_1100};

  // Anode control logic
  always @* begin
    case (dig)
      2'b00: anode = 4'b1110;
      2'b01: anode = 4'b1101;
      2'b10: anode = 4'b1011;
      2'b11: anode = 4'b0111;
    endcase
  end

  // Segment control logic
  always @* begin
    case (dig)
      2'b00: seg = seg_lut[data[3:0]];
      2'b01: seg = seg_lut[data[7:4]];
      2'b10: seg = seg_lut[data[11:8]];
      2'b11: seg = seg_lut[data[15:12]];
    endcase
  end

endmodule

