  always @(posedge clk_i) begin
    if (reset_i) begin
      write_ptr <= 0;
      read_ptr <= 0;
      full <= 0;
      empty <= 1;
    end else begin
      if (v_i && !full) begin
        mem[write_ptr] <= data_i;
        write_ptr <= write_ptr + 1;
        if (write_ptr == 1024) begin
          write_ptr <= 0;
        end
        if (write_ptr == read_ptr) begin
          full <= 1;
        end
        empty <= 0;
      end
      if (yumi_i && !empty) begin
        data_o <= mem[read_ptr];
        read_ptr <= read_ptr + 1;
        if (read_ptr == 1024) begin
          read_ptr <= 0;
        end
        if (read_ptr == write_ptr) begin
          empty <= 1;
        end
        full <= 0;
      end
    end
  end

  // Output signals
  assign ready_o = ~full;
  assign v_o = ~empty;

endmodule

