  input [15:0] key_buffer_in;
  input clk, keypad_int;
  input [1:0] key_row, key_col;

  reg [3:0] keypad_scanner_out;
  reg [15:0] key_buffer;
  reg [1:0] key_row_reg, key_col_reg;
  reg [3:0] key_digit;
  reg [1:0] state;

  keypad_scanner keypad_scanner_inst(.clk(clk), .keypad_int(keypad_int), .key_row(key_row_reg), .key_col(key_col_reg), .keypad_out(keypad_scanner_out));

  always @(posedge clk) begin
    if (keypad_int) begin
      key_row_reg <= key_row;
      key_col_reg <= key_col;
      state <= 2'b00;
    end else if (state == 2'b00) begin
      key_digit <= keypad_scanner_out;
      state <= 2'b01;
    end else if (state == 2'b01) begin
      key_buffer <= {key_buffer[14:0], key_digit};
      state <= 2'b10;
