module IF_stage#(parameter MEM_WIDTH=8,parameter WIDTH,parameter OFF_WIDTH=6)(clk,reset,addr,instr,jump,stall,jumpOffset);

    input clk,reset,jump,stall;
    output [WIDTH-1:0] instr;
    output [MEM_WIDTH-1:0] addr;
    input [OFF_WIDTH-1:0] jumpOffset;

    reg [MEM_WIDTH-1:0] PC;
    reg [WIDTH-1:0] instruction;
    reg [MEM_WIDTH-1:0] target_addr;

    // Instruction memory
    reg [WIDTH-1:0] instruction_memory [0:(1<<MEM_WIDTH)-1];

    // Sign extend unit
    assign target_addr = PC + {jumpOffset, {OFF_WIDTH-1{1'b0}}};

    // PC update logic
    always @(posedge clk) begin
        if (reset) begin
            PC <= 0;
        end else if (jump) begin
            PC <= target_addr;
        end else if (!stall) begin
            PC <= PC + 1;
        end
    end

    // Instruction fetch logic
    always @(posedge clk) begin
        if (reset) begin
            instruction <= 0;
        end else if (!stall) begin
            instruction <= instruction_memory[PC];
        end
    end

    // Output signals
    assign addr = PC;
    assign instr = instruction;

endmodule

