  gh_delay #(.DELAY(31)) delay6(.CLK(CLK), .rst(rst), .srst(srst), .D(Q_d8), .Q(Q_d16));

  always @(posedge CLK) begin
    if (rst || srst) begin
      Q <= 1'b0;
    end else begin
      case (DELAY)
        5'b00001: Q <= D_d1;
        5'b00010: Q <= Q_d1;
        5'b00100: Q <= Q_d2;
        5'b01000: Q <= Q_d4;
        5'b10000: Q <= Q_d8;
        5'b11111: Q <= Q_d16;
        default: Q <= 1'b0;
      endcase
    end
  end

endmodule

