module countUD5L(input clk, input Up, input Dw, input reset, input LD, input [4:0] D, output [4:0] Q, output UTC, output DTC);

  reg [4:0] count;
  reg [4:0] next_count;

  always @(posedge clk) begin
    if (reset) begin
      count <= 5'b0;
    end else if (LD) begin
      count <= D;
    end else begin
      count <= next_count;
    end
  end

  always @(*) begin
    if (Up) begin
      next_count = count + 1;
    end else begin
      next_count = count - 1;
    end
  end

  assign Q = count;
  assign UTC = (count == 5'b11111) ? 1 : 0;
  assign DTC = (count == 5'b00000) ? 1 : 0;

endmodule

