module serial2parallel(
  input clk,
  input rst_n,
  input din_serial,
  input din_valid,
  output reg [7:0] dout_parallel,
  output reg dout_valid
);

  reg [7:0] shift_reg;
  reg [2:0] bit_count;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      shift_reg <= 8'b0;
      bit_count <= 3'b0;
      dout_valid <= 1'b0;
    end else begin
      if (din_valid) begin
        shift_reg <= {shift_reg[6:0], din_serial};
        bit_count <= bit_count + 1;
        if (bit_count == 3'b111) begin
          dout_parallel <= shift_reg;
          dout_valid <= 1'b1;
          bit_count <= 3'b0;
          shift_reg <= 8'b0;
        end
      end
    end
  end

endmodule

