module comparator_3bit_tb;

  // Inputs
  reg [2:0] A;
  reg [2:0] B;

  // Outputs
  wire A_greater;
  wire A_equal;
  wire A_less;

  // Instantiate the Unit Under Test (UUT)
  comparator_3bit uut (
    .A(A), 
    .B(B), 
    .A_greater(A_greater), 
    .A_equal(A_equal), 
    .A_less(A_less)
  );

  integer i;
  integer error;

  initial begin
    // Initialize inputs
    A = 0;
    B = 0;

    // Initialize error count
    error = 0;

    // Run 100 test cases
    for (i = 0; i < 100; i = i + 1) begin
      // Generate random input values
      A = $random;
      B = $random;

      // Apply inputs to the comparator
      #1;

      // Check if the output signals accurately reflect the relationship between A and B
      if ((A > B) != A_greater || (A == B) != A_equal || (A < B) != A_less) begin
        $display("Test case %d failed: A = %d, B = %d, A_greater = %d, A_equal = %d, A_less = %d", i, A, B, A_greater, A_equal, A_less);
        error = error + 1;
      end
    end

    // Provide a summary of the test
    if (error == 0) begin
      $display("Design passed.");
    end else begin
      $display("Design failed with %d failures.", error);
    end
  end

endmodule

