    input devpor,
    output q
);

    parameter power_up = "low";
    parameter violation = "accept";

    reg q_reg;
    wire q_next;

    assign q = q_reg;

    always @(posedge clk or negedge clrn) begin
        if (!clrn) begin
            q_reg <= 1'b0;
        end else if (aload) begin
            q_reg <= asdata;
        end else if (sclr) begin
            q_reg <= 1'b0;
        end else if (sload) begin
            q_reg <= sload;
        end else if (ena) begin
            q_reg <= q_next;
        end
    end

    assign q_next = (ena & d) | (ena & q_reg);

    specify
        $setup(posedge clk, negedge clrn, 0, 0, 0, 0);
        $hold(posedge clk, negedge clrn, 0, 0, 0, 0);
        (posedge clk => (q +: q_next)) = (0, 0);
