module clock_divider(
    input wire clock,
    output reg clock_div
);

parameter input_frequency = 50_000_000; // Hz
parameter output_frequency = 10_000_000; // Hz

localparam counter_limit = input_frequency / output_frequency;

reg [31:0] counter = 0;

always @(posedge clock) begin
    if (counter == counter_limit - 1) begin
        counter <= 0;
        clock_div <= ~clock_div;
    end else begin
        counter <= counter + 1;
    end
end

endmodule

