module ps2_host_to_kb(
module ps2_host_to_kb(
    input wire clk,
    inout wire ps2clk_ext,
    inout wire ps2data_ext,
    input wire [7:0] data,
    input wire dataload,
    output wire ps2busy,
    output wire ps2error
);

    // PS2 communication protocol timing requirements
    parameter CLK_LOW_TIME = 600;
    parameter CLK_HIGH_TIME = 600;
    parameter DATA_LOW_TIME = 600;
    parameter DATA_HIGH_TIME = 600;
    parameter PARITY_LOW_TIME = 600;
    parameter PARITY_HIGH_TIME = 600;
    parameter TIMEOUT_TIME = 10000;

    // State machine states
    parameter IDLE = 2'b00;
    parameter START = 2'b01;
    parameter DATA = 2'b10;
    parameter PARITY = 2'b11;

    // State machine signals
    reg [1:0] state = IDLE;
    reg [3:0] bit_count = 0;
    reg [7:0] data_reg = 0;
    reg parity_reg = 0;
    reg [31:0] timeout_count = 0;

    // PS2 bus signals
    reg ps2clk = 1;
    reg ps2data = 1;

    // Busy and error signals
    reg busy = 0;
    reg error = 0;

    // Clock synchronization
    reg clk_sync = 0;
    reg clk_sync_prev = 0;

    // Data synchronization
    reg data_sync = 0;
    reg data_sync_prev = 0;

    // Parity generation
    reg parity = 0;

    // Timeout monitoring
    reg timeout = 0;

    // Sequential logic
    always @(posedge clk) begin
        // Clock synchronization
        clk_sync <= ps2clk_ext;
        if (clk_sync != clk_sync_prev) begin
            clk_sync_prev <= clk_sync;
            if (clk_sync == 1) begin
                // Clock high
                if (state == START) begin
                    state <= DATA;
                    bit_count <= 0;
                end else if (state == DATA) begin
                    bit_count <= bit_count + 1;
                    if (bit_count == 8) begin
                        state <= PARITY;
                        bit_count <= 0;
                    end
                end else if (state == PARITY) begin
                    state <= IDLE;
                    busy <= 0;
                    error <= 0;
                end
            end else begin
                // Clock low
                if (state == START) begin
                    state <= IDLE;
                    busy <= 0;
                    error <= 0;
                end else if (state == DATA) begin
                    bit_count <= bit_count + 1;
                    if (bit_count == 8) begin
                        state <= PARITY;
                        bit_count <= 0;
                    end
                end else if (state == PARITY) begin
                    state <= IDLE;
                    busy <= 0;
                    error <= 0;
                end
            end
        end

        // Data synchronization
        data_sync <= ps2data_ext;
        if (data_sync != data_sync_prev) begin
            data_sync_prev <= data_sync;
            if (data_sync == 1) begin
                // Data high
                if (state == DATA) begin
                    data_reg[bit_count] <= 1;
                end
            end else begin
                // Data low
                if (state == DATA) begin
                    data_reg[bit_count] <= 0;
                end
            end
        end

        // Parity generation
        if (state == DATA) begin
            parity_reg <= parity_reg ^ data_reg[bit_count];
        end

        // Timeout monitoring
        if (state == IDLE) begin
            timeout_count <= 0;
        end else if (state == START || state == DATA || state == PARITY) begin
            timeout_count <= timeout_count + 1;
            if (timeout_count >= TIMEOUT_TIME) begin
                timeout <= 1;
                state <= IDLE;
                busy <= 0;
                error <= 1;
            end
        end

        // PS2 bus signals
        if (state == IDLE) begin
            ps2clk <= 1;
            ps2data <= 1;
        end else if (state == START) begin
            ps2clk <= 0;
            ps2data <= 0;
        end else if (state == DATA) begin
            ps2clk <= 1;
            ps2data <= data_reg[bit_count];
        end else if (state == PARITY) begin
            ps2clk <= 0;
            ps2data <= parity_reg;
        end

        // Busy and error signals
        if (state == IDLE) begin
            busy <= 0;
            error <= 0;
        end else if (state == START) begin
            busy <= 1;
            error <= 0;
        end else if (state == DATA || state == PARITY) begin
            busy <= 1;
            error <= 0;
        end else if (state == ERROR) begin
            busy <= 0;
            error <= 1;
        end
    end

    // Data load
    always @(posedge clk) begin
        if (dataload) begin
            state <= START;
            data_reg <= data;
            parity_reg <= 0;
            for (int i = 0; i < 8; i = i + 1) begin
                parity_reg <= parity_reg ^ data[i];
            end
            timeout_count <= 0;
            timeout <= 0;
        end
    end

    // Output signals
    assign ps2clk_ext = ps2clk;
    assign ps2data_ext = ps2data;
    assign ps2busy = busy;
    assign ps2error = error;

endmodule

