module adder_word(input wire [31:0] a, input wire [31:0] b, input wire carry_in, output wire [31:0] sum, output wire carry_out);

  wire [7:0] carry_in_byte;
  wire [7:0] carry_out_byte;
  wire [7:0] sum_byte;

  // Instantiate 8-bit adders
  adder_byte adder0(a[7:0], b[7:0], carry_in_byte[0], sum_byte[0], carry_out_byte[0]);
  adder_byte adder1(a[15:8], b[15:8], carry_in_byte[1], sum_byte[1], carry_out_byte[1]);
  adder_byte adder2(a[23:16], b[23:16], carry_in_byte[2], sum_byte[2], carry_out_byte[2]);
  adder_byte adder3(a[31:24], b[31:24], carry_in_byte[3], sum_byte[3], carry_out_byte[3]);

  // Propagate carry between byte adders
  assign carry_in_byte[1] = carry_out_byte[0];
  assign carry_in_byte[2] = carry_out_byte[1];
  assign carry_in_byte[3] = carry_out_byte[2];

  // Combine byte sums to get final sum
  assign sum = {sum_byte[3], sum_byte[2], sum_byte[1], sum_byte[0]};

  // Output carry from most significant byte adder
  assign carry_out = carry_out_byte[3];

endmodule

// 8-bit adder module
module adder_byte(input wire [7:0] a, input wire [7:0] b, input wire carry_in, output wire [7:0] sum, output wire carry_out);

  wire [7:0] tmp_sum;
  wire [7:0] tmp_carry;

  // Full adder for each bit
  full_adder fa0(a[0], b[0], carry_in, tmp_sum[0], tmp_carry[0]);
  full_adder fa1(a[1], b[1], tmp_carry[0], tmp_sum[1], tmp_carry[1]);
  full_adder fa2(a[2], b[2], tmp_carry[1], tmp_sum[2], tmp_carry[2]);
  full_adder fa3(a[3], b[3], tmp_carry[2], tmp_sum[3], tmp_carry[3]);
  full_adder fa4(a[4], b[4], tmp_carry[3], tmp_sum[4], tmp_carry[4]);
  full_adder fa5(a[5], b[5], tmp_carry[4], tmp_sum[5], tmp_carry[5]);
  full_adder fa6(a[6], b[6], tmp_carry[5], tmp_sum[6], tmp_carry[6]);
  full_adder fa7(a[7], b[7], tmp_carry[6], tmp_sum[7], carry_out);

  // Combine bit sums to get final sum
  assign sum = {tmp_sum[7], tmp_sum[6], tmp_sum[5], tmp_sum[4], tmp_sum[3], tmp_sum[2], tmp_sum[1], tmp_sum[0]};

endmodule

// Full adder module
module full_adder(input wire a, input wire b, input wire carry_in, output wire sum, output wire carry_out);

  assign sum = a ^ b ^ carry_in;
  assign carry_out = (a & b) | (a & carry_in) | (b & carry_in);

endmodule

