module gh_delay_programmable_63(
    input wire CLK,
    input wire rst,
    input wire srst,
    input wire D,
    input wire [5:0] DELAY,
    output wire Q
);

    wire [31:0] Q_d32;
    wire [15:0] Q_d16;
    wire [7:0] Q_d8;
    wire [3:0] Q_d4;
    wire [1:0] Q_d2;
    wire Q_d1;

    gh_delay #(.DELAY(32)) delay32(
        .CLK(CLK),
        .rst(rst),
        .srst(srst),
        .D(D),
        .Q(Q_d32)
    );

    gh_delay #(.DELAY(16)) delay16(
        .CLK(CLK),
        .rst(rst),
        .srst(srst),
        .D(Q_d32),
        .Q(Q_d16)
    );

    gh_delay #(.DELAY(8)) delay8(
        .CLK(CLK),
        .rst(rst),
        .srst(srst),
        .D(Q_d16),
        .Q(Q_d8)
    );

    gh_delay #(.DELAY(4)) delay4(
        .CLK(CLK),
        .rst(rst),
        .srst(srst),
        .D(Q_d8),
        .Q(Q_d4)
    );

    gh_delay #(.DELAY(2)) delay2(
        .CLK(CLK),
        .rst(rst),
        .srst(srst),
        .D(Q_d4),
        .Q(Q_d2)
    );

    gh_delay #(.DELAY(1)) delay1(
        .CLK(CLK),
        .rst(rst),
        .srst(srst),
        .D(Q_d2),
        .Q(Q_d1)
    );

    assign Q = (DELAY == 0) ? D :
               (DELAY[5]) ? Q_d32 :
               (DELAY[4]) ? Q_d16 :
               (DELAY[3]) ? Q_d8 :
               (DELAY[2]) ? Q_d4 :
               (DELAY[1]) ? Q_d2 :
               Q_d1;

endmodule

