                    green <= 1'b0;
                    state <= S2;
                end
                S2: begin
                    red <= 1'b0;
                    yellow <= 1'b1;
                    green <= 1'b1;
                    state <= S3;
                end
                S3: begin
                    red <= 1'b0;
                    yellow <= 1'b0;
                    green <= 1'b1;
                    state <= S0;
