module d_ff_gates(d, clk, q, q_bar);
module d_ff_gates(d, clk, q, q_bar);
  input d, clk;
  output q, q_bar;
  reg q, q_bar;
  wire not_d, not_clk, nand_1, nand_2, nand_3, nand_4;

  // Generate inverted versions of the clock and data inputs
  not not_d_gate(not_d, d);
  not not_clk_gate(not_clk, clk);

  // Generate NAND gates to control the latching mechanism
  nand nand_1_gate(nand_1, not_d, q_bar);
  nand nand_2_gate(nand_2, not_clk, nand_1);
  nand nand_3_gate(nand_3, d, q);
  nand nand_4_gate(nand_4, clk, nand_3);

  // Update the output based on the captured data
  always @(posedge clk) begin
    q <= nand_3;
    q_bar <= nand_4;
  end
endmodule

module cycloneiv_hssi_tx_pma_sub_tx_rx_det_rcv_det_control(
module cycloneiv_hssi_tx_pma_sub_tx_rx_det_rcv_det_control(
  input wire clk,
  input wire rcv_det_en,
  input wire rcv_det_pdb,
  input wire com_pass,
  input wire probe_pass,
  output wire det_on,
  output wire detect_valid,
  output wire rcv_found
);

  // Synchronize raw detection signal with clock
  reg sync_rcv_det_pdb;
  always @(posedge clk) begin
    sync_rcv_det_pdb <= rcv_det_pdb;
  end

  // FSM states
  localparam IDLE = 2'b00;
  localparam DETECT = 2'b01;
  localparam VALIDATE = 2'b10;
  reg [1:0] state;

  // FSM logic
  always @(posedge clk) begin
    case (state)
      IDLE: begin
        if (rcv_det_en && sync_rcv_det_pdb) begin
          state <= DETECT;
        end
      end
      DETECT: begin
        if (com_pass && probe_pass) begin
          state <= VALIDATE;
        end else begin
          state <= IDLE;
        end
      end
      VALIDATE: begin
        if (sync_rcv_det_pdb) begin
          rcv_found <= 1'b1;
          detect_valid <= 1'b1;
          state <= IDLE;
        end else begin
          rcv_found <= 1'b0;
          detect_valid <= 1'b0;
          state <= IDLE;
        end
      end
    endcase
  end

  // Output signals
  assign det_on = (state == DETECT);

endmodule

