module uart_transmitter(
module uart_transmitter(
    input clk,
    input rst_n,
    input [7:0] data_in,
    input start,
    output reg [7:0] data_out,
    output reg done
);

    // Define states
    parameter IDLE = 2'b00;
    parameter START_BIT = 2'b01;
    parameter DATA_BITS = 2'b10;
    parameter PARITY_BIT = 2'b11;
    parameter STOP_BIT = 2'b100;

    // Define shift register
    reg [9:0] shift_reg;

    // Define bit counter
    reg [3:0] bit_counter;

    // Define state machine
    reg [1:0] state;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= IDLE;
            bit_counter <= 0;
            shift_reg <= 0;
            data_out <= 0;
            done <= 0;
        end
        else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        state <= START_BIT;
                        bit_counter <= 0;
                        shift_reg <= {1'b0, data_in, 1'b0};
                    end
                end
                START_BIT: begin
                    data_out <= shift_reg[0];
                    shift_reg <= {shift_reg[9:1], 1'b0};
                    bit_counter <= bit_counter + 1;
                    if (bit_counter == 10) begin
                        state <= DATA_BITS;
                        bit_counter <= 0;
                    end
                end
                DATA_BITS: begin
                    data_out <= shift_reg[0];
                    shift_reg <= {shift_reg[9:1], 1'b0};
                    bit_counter <= bit_counter + 1;
                    if (bit_counter == 8) begin
                        state <= PARITY_BIT;
                        bit_counter <= 0;
                    end
                end
                PARITY_BIT: begin
                    data_out <= shift_reg[0];
                    shift_reg <= {shift_reg[9:1], 1'b0};
                    bit_counter <= bit_counter + 1;
                    if (bit_counter == 1) begin
                        state <= STOP_BIT;
                        bit_counter <= 0;
                    end
                end
                STOP_BIT: begin
                    data_out <= shift_reg[0];
                    shift_reg <= {shift_reg[9:1], 1'b1};
                    bit_counter <= bit_counter + 1;
                    if (bit_counter == 10) begin
                        state <= IDLE;
                        bit_counter <= 0;
                        done <= 1;
                    end
                end
            endcase
        end
    end

endmodule

