module addr_decode #(
module addr_decode #(
  parameter int unsigned NoIndices = 32'd0,
  parameter int unsigned NoRules = 32'd0,
  parameter type addr_t = logic,
  parameter type rule_t = logic,
  parameter int unsigned IdxWidth = (NoIndices > 32'd1) ? $clog2(NoIndices) : 32'd1,
  parameter type idx_t = logic[IdxWidth-1:0]
) (
  input addr_t addr_i,
  input rule_t[NoRules-1:0] addr_map_i,
  output idx_t idx_o,
  output logic dec_valid_o,
  output logic dec_error_o,
  input logic en_default_idx_i,
  input idx_t default_idx_i
);

  // Check for overlaps in address ranges
  for (int i = 0; i < NoRules; i++) begin
    for (int j = i+1; j < NoRules; j++) begin
      if (addr_map_i[i].start_addr >= addr_map_i[j].start_addr && addr_map_i[i].start_addr < addr_map_i[j].end_addr) begin
        $error("Overlap detected in address ranges: %d-%d and %d-%d", addr_map_i[i].start_addr, addr_map_i[i].end_addr, addr_map_i[j].start_addr, addr_map_i[j].end_addr);
      end
      if (addr_map_i[i].end_addr > addr_map_i[j].start_addr && addr_map_i[i].end_addr <= addr_map_i[j].end_addr) begin
        $error("Overlap detected in address ranges: %d-%d and %d-%d", addr_map_i[i].start_addr, addr_map_i[i].end_addr, addr_map_i[j].start_addr, addr_map_i[j].end_addr);
      end
    end
    if (addr_map_i[i].start_addr >= addr_map_i[i].end_addr) begin
      $error("Invalid address range: %d-%d", addr_map_i[i].start_addr, addr_map_i[i].end_addr);
    end
  end

  // Decode address
  always_comb begin
    dec_valid_o = 1'b0;
    dec_error_o = 1'b0;
    idx_o = default_idx_i;
    for (int i = 0; i < NoRules; i++) begin
      if (addr_i >= addr_map_i[i].start_addr && addr_i < addr_map_i[i].end_addr) begin
        idx_o = addr_map_i[i].idx;
        dec_valid_o = 1'b1;
        break;
      end
    end
    if (!dec_valid_o && en_default_idx_i) begin
      dec_error_o = 1'b1;
    end
  end

  // Assertion to ensure only one rule matches the address
  for (int i = 0; i < NoRules; i++) begin
    for (int j = i+1; j < NoRules; j++) begin
      if (addr_i >= addr_map_i[i].start_addr && addr_i < addr_map_i[i].end_addr && addr_i >= addr_map_i[j].start_addr && addr_i < addr_map_i[j].end_addr) begin
        $error("Multiple rules match the address: %d", addr_i);
      end
    end
  end

endmodule

