    end else begin
      if (stage == 4'b1111) begin
        shift_reg <= {shift_reg[14:0], ccff_head};
        stage <= 4'b0;
      end else begin
        shift_reg <= {shift_reg[14:0], shift_reg[15]};
        stage <= stage + 1;
      end
    end
  end

  assign ccff_tail = shift_reg[0];
  assign mem_out = shift_reg;
  assign mem_outb = ~shift_reg;

endmodule

module key_filter(clk, rst_n, key_pin, key_status, key_event);

  // Module interface
  input clk;
  input rst_n;
  input key_pin;
  output reg key_status;
  output reg key_event;

  // Internal registers and wires
  reg [1:0] state;
  reg [31:0] counter;
  reg [1:0] shift_reg;
  reg key_edge;
  reg key_edge_prev;
  reg key_edge_stable;
  reg key_edge_stable_prev;
  reg key_edge_stable_prev_prev;
  reg key_edge_stable_prev_prev_prev;

  // FSM states
  parameter IDLE = 2'b00;
  parameter PRESS = 2'b01;
  parameter STEADY = 2'b10;
  parameter RELEASE = 2'b11;

  // Counter reset enable
  wire counter_reset;

  // Key edge detection
  assign key_edge = key_pin ^ key_pin_prev;
  assign key_edge_stable = key_edge & ~key_edge_prev & ~key_edge_prev_prev & ~key_edge_prev_prev_prev;

  // Counter logic
  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      counter <= 0;
    end else if (counter_reset) begin
      counter <= 0;
    end else if (key_edge_stable) begin
      counter <= counter + 1;
    end
  end

  // FSM state transition logic
  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      state <= IDLE;
    end else begin
      case (state)
        IDLE: begin
          if (key_edge_stable) begin
            state <= PRESS;
          end
        end
        PRESS: begin
          if (counter >= 32'hFFFFFFFF) begin
            state <= STEADY;
          end
        end
        STEADY: begin
          if (key_edge_stable) begin
            state <= RELEASE;
          end
        end
        RELEASE: begin
          if (counter >= 32'hFFFFFFFF) begin
            state <= IDLE;
          end
        end
      endcase
    end
  end

  // Key status and event detection logic
  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      key_status <= 1'b0;
      key_event <= 1'b0;
    end else begin
      case (state)
        IDLE: begin
          key_status <= 1'b0;
          key_event <= 1'b0;
        end
        PRESS: begin
          key_status <= 1'b1;
          key_event <= 1'b0;
        end
        STEADY: begin
          key_status <= 1'b1;
          key_event <= 1'b0;
        end
        RELEASE: begin
          key_status <= 1'b0;
          key_event <= 1'b1;
        end
      endcase
    end
  end

  // Shift register for edge detection
  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      shift_reg <= 2'b00;
    end else begin
      shift_reg <= {shift_reg[0], key_pin};
    end
  end

  // Counter reset enable logic
  assign counter_reset = (state == IDLE) ? 1'b1 : 1'b0;

  // Key pin previous state
  reg key_pin_prev;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      key_pin_prev <= 1'b0;
    end else begin
      key_pin_prev <= key_pin;
    end
  end

  // Key edge previous states
  reg key_edge_prev;
  reg key_edge_prev_prev;
  reg key_edge_prev_prev_prev;
  reg key_edge_prev_prev_prev_prev;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      key_edge_prev <= 1'b0;
      key_edge_prev_prev <= 1'b0;
      key_edge_prev_prev_prev <= 1'b0;
      key_edge_prev_prev_prev_prev <= 1'b0;
    end else begin
      key_edge_prev <= key_edge;
      key_edge_prev_prev <= key_edge_prev;
      key_edge_prev_prev_prev <= key_edge_prev_prev;
      key_edge_prev_prev_prev_prev <= key_edge_prev_prev_prev;
    end
  end

endmodule

module apb_master(
    input [7:0] addr,
    input data_valid,
    input [31:0] data,
    input data_dir,
    output [31:0] read_out_data,
    output transaction_done,
    input apb_clk,
    input apb_reset,
    output apb_write,
    output apb_selx,
    output apb_en,
    output [31:0] apb_wdata,
    input [31:0] apb_rdata,
    input apb_ready,
    output [7:0] apb_addr,
    output apb_tranerr
);

    // Define states
    parameter IDLE = 2'b00;
    parameter SETUP = 2'b01;
    parameter ACCESS = 2'b10;

    // Define state registers
    reg [1:0] state;
    reg [31:0] read_data;
    reg [31:0] write_data;
    reg [7:0] apb_addr_reg;
    reg apb_write_reg;
    reg apb_selx_reg;
    reg apb_en_reg;
    reg [31:0] apb_wdata_reg;
    reg [31:0] apb_rdata_reg;
    reg apb_ready_reg;
    reg apb_tranerr_reg;
    reg [31:0] timeout_count;

    // Define state transitions
    always @(posedge apb_clk) begin
        if (apb_reset) begin
            state <= IDLE;
            read_data <= 0;
            write_data <= 0;
            apb_addr_reg <= 0;
            apb_write_reg <= 0;
            apb_selx_reg <= 0;
            apb_en_reg <= 0;
            apb_wdata_reg <= 0;
            apb_rdata_reg <= 0;
            apb_ready_reg <= 0;
            apb_tranerr_reg <= 0;
            timeout_count <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (data_valid) begin
                        state <= SETUP;
                        apb_addr_reg <= addr;
                        apb_write_reg <= data_dir;
                        apb_selx_reg <= 1;
                        apb_en_reg <= 1;
                        apb_wdata_reg <= data;
                    end
                end
                SETUP: begin
                    if (apb_ready_reg) begin
                        state <= ACCESS;
                        apb_addr_reg <= addr;
                        apb_write_reg <= data_dir;
                        apb_selx_reg <= 1;
                        apb_en_reg <= 1;
                        apb_wdata_reg <= data;
                        timeout_count <= 0;
                    end
                end
                ACCESS: begin
                    if (apb_ready_reg) begin
                        if (apb_write_reg) begin
                            state <= IDLE;
                            transaction_done <= 1;
                        end else begin
                            state <= IDLE;
                            read_data <= apb_rdata_reg;
                            transaction_done <= 1;
                        end
                    end else if (timeout_count == 1000) begin
                        state <= IDLE;
                        apb_tranerr_reg <= 1;
                    end else begin
                        timeout_count <= timeout_count + 1;
                    end
                end
            endcase
        end
    end

    // Assign output signals
    assign apb_write = apb_write_reg;
    assign apb_selx = apb_selx_reg;
    assign apb_en = apb_en_reg;
    assign apb_wdata = apb_wdata_reg;
    assign apb_addr = apb_addr_reg;
    assign apb_tranerr = apb_tranerr_reg;
    assign read_out_data = read_data;

    // Assign input signals
    always @(posedge apb_clk) begin
        if (apb_reset) begin
            apb_rdata_reg <= 0;
            apb_ready_reg <= 0;
        end else begin
            apb_rdata_reg <= apb_rdata;
            apb_ready_reg <= apb_ready;
        end
    end

endmodule

