      if (sw == 3'b000) begin
        sw <= 3'b001;
      end else if (sw == 3'b001) begin
        sw <= 3'b010;
      end else if (sw == 3'b010) begin
        sw <= 3'b011;
      end else if (sw == 3'b011) begin
        sw <= 3'b100;
      end else if (sw == 3'b100) begin
        sw <= 3'b101;
      end else if (sw == 3'b101) begin
        sw <= 3'b110;
      end else if (sw == 3'b110) begin
        sw <= 3'b111;
      end else if (sw == 3'b111) begin
        sw <= 3'b000;
      end
    end
  end

  // Monitor the output signals
  always @(posedge clk) begin
    if (reset) begin
      h3 <= 8'b0;
      h2 <= 8'b0;
      h1 <= 8'b0;
      h0 <= 8'b0;
    end else begin
      h3 <= dut.h3;
      h2 <= dut.h2;
      h1 <= dut.h1;
      h0 <= dut.h0;
    end
  end

  // Generate a sequence of input patterns
  initial begin
    reset = 1;
    #100 reset = 0;
    #1000 $finish;
  end

endmodule

module VGA_Sig_Gen(
    input CLK,
    input RESET,
    input RE,
    input [15:0] CONFIG_COLOURS,
    output reg DPR_CLK,
    output reg [14:0] VGA_ADDR,
    input VGA_DATA,
    output reg VGA_HS,
    output reg VGA_VS,
    output reg [7:0] VGA_COLOUR
);

    // Parameters
    parameter H_TOTAL_PIXELS = 800;
    parameter V_TOTAL_PIXELS = 525;
    parameter H_DISPLAY_AREA = 640;
    parameter V_DISPLAY_AREA = 480;
    parameter H_PORCH_TIME = 16;
    parameter V_PORCH_TIME = 10;

    // Internal registers
    reg [9:0] h_counter;
    reg [9:0] v_counter;
    reg [1:0] state;
    reg [7:0] color_data;

    // State machine states
    parameter IDLE = 2'b00;
    parameter ACTIVE = 2'b01;
    parameter FRAME_END = 2'b10;

    // Color configuration
    reg [7:0] color_config[0:15];
    initial begin
        color_config[0] = 8'h00;
        color_config[1] = 8'h00;
        color_config[2] = 8'h00;
        color_config[3] = 8'h00;
        color_config[4] = 8'h00;
        color_config[5] = 8'h00;
        color_config[6] = 8'h00;
        color_config[7] = 8'h00;
        color_config[8] = 8'h00;
        color_config[9] = 8'h00;
        color_config[10] = 8'h00;
        color_config[11] = 8'h00;
        color_config[12] = 8'h00;
        color_config[13] = 8'h00;
        color_config[14] = 8'h00;
        color_config[15] = 8'h00;
    end

    // Counters
    always @(posedge CLK) begin
        if (RESET) begin
            h_counter <= 0;
            v_counter <= 0;
            state <= IDLE;
            DPR_CLK <= 0;
            VGA_ADDR <= 0;
            VGA_HS <= 0;
            VGA_VS <= 0;
            VGA_COLOUR <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (h_counter == H_TOTAL_PIXELS - 1) begin
                        h_counter <= 0;
                        if (v_counter == V_TOTAL_PIXELS - 1) begin
                            v_counter <= 0;
                            state <= FRAME_END;
                            VGA_VS <= 1;
                        end else begin
                            v_counter <= v_counter + 1;
                            state <= ACTIVE;
                            VGA_VS <= 0;
                        end
                    end else begin
                        h_counter <= h_counter + 1;
                        state <= ACTIVE;
                        VGA_HS <= 0;
                    end
                end
                ACTIVE: begin
                    if (h_counter == H_DISPLAY_AREA - 1) begin
                        h_counter <= 0;
                        if (v_counter == V_DISPLAY_AREA - 1) begin
                            v_counter <= 0;
                            state <= FRAME_END;
                            VGA_VS <= 1;
                        end else begin
                            v_counter <= v_counter + 1;
                            state <= ACTIVE;
                            VGA_VS <= 0;
                        end
                    end else begin
                        h_counter <= h_counter + 1;
                        state <= ACTIVE;
                        VGA_HS <= 0;
                    end
                end
                FRAME_END: begin
                    if (h_counter == H_TOTAL_PIXELS - 1) begin
                        h_counter <= 0;
                        if (v_counter == V_TOTAL_PIXELS - 1) begin
                            v_counter <= 0;
                            state <= IDLE;
                            VGA_VS <= 0;
                        end else begin
                            v_counter <= v_counter + 1;
                            state <= ACTIVE;
                            VGA_VS <= 0;
                        end
                    end else begin
                        h_counter <= h_counter + 1;
                        state <= FRAME_END;
                        VGA_HS <= 1;
                    end
                end
            endcase
        end
    end

    // Color data
    always @(posedge CLK) begin
        if (RESET) begin
            color_data <= 0;
        end else if (RE) begin
            color_data <= CONFIG_COLOURS[color_data];
        end
    end

    // Output signals
    always @(posedge CLK) begin
        if (RESET) begin
            VGA_ADDR <= 0;
            VGA_COLOUR <= 0;
        end else begin
            case (state)
                IDLE: begin
                    VGA_ADDR <= 0;
                    VGA_COLOUR <= 0;
                end
                ACTIVE: begin
                    VGA_ADDR <= {v_counter, h_counter};
                    VGA_COLOUR <= color_config[color_data];
                end
                FRAME_END: begin
                    VGA_ADDR <= 0;
                    VGA_COLOUR <= 0;
                end
            endcase
        end
    end

    // Display clock
    always @(posedge CLK) begin
        if (RESET) begin
            DPR_CLK <= 0;
        end else begin
            DPR_CLK <= ~DPR_CLK;
        end
    end

endmodule

module APB_master(
    input Transfer,
    input Wr_Rd,
    input [4:0] Address,
    input [31:0] write_data,
    output reg [31:0] read_data,
    input PCLK,
    input PRESETn,
    input PREADY,
    input [31:0] PRDATA,
    input PSLVERR,
    output reg [4:0] PADDR,
    output reg PSELx,
    output reg PENABLE,
    output reg PWRITE,
    output reg [31:0] PWDATA
);

    // Define states
    parameter IDLE = 2'b00;
    parameter SETUP = 2'b01;
    parameter ACCESS = 2'b10;

    // Define state register and next state logic
    reg [1:0] state, next_state;
    always @(posedge PCLK or negedge PRESETn) begin
        if (~PRESETn) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Define output logic based on state
    always @(*) begin
        case (state)
            IDLE: begin
                PSELx <= 1'b0;
                PENABLE <= 1'b0;
                PWRITE <= Wr_Rd;
                PWDATA <= write_data;
                PADDR <= Address;
                next_state <= SETUP;
            end
            SETUP: begin
                PSELx <= 1'b1;
                PENABLE <= 1'b0;
                PWRITE <= Wr_Rd;
                PWDATA <= write_data;
                PADDR <= Address;
                next_state <= ACCESS;
            end
            ACCESS: begin
                PSELx <= 1'b1;
                PENABLE <= 1'b1;
                PWRITE <= Wr_Rd;
                PWDATA <= write_data;
                PADDR <= Address;
                if (PREADY) begin
                    read_data <= PRDATA;
                    next_state <= IDLE;
                end else begin
                    next_state <= ACCESS;
                end
            end
            default: begin
                PSELx <= 1'b0;
                PENABLE <= 1'b0;
                PWRITE <= 1'b0;
                PWDATA <= 32'b0;
                PADDR <= 5'b0;
                next_state <= IDLE;
            end
        endcase
    end

endmodule

