    $hold(negedge A3, 0, 0, 0);
    $hold(negedge A4, 0, 0, 0);

    (A1 +: A2) = (Y *: 0);
    (A3 +: A4) = (Y *: 0);
    (A1 +: A3) = (Y *: 0);
    (A2 +: A4) = (Y *: 0);

    (A1 +: A2 +: A3 +: A4) = (Y *: 0);
  endspecify

