    input captnupdt;
    output mainclk;
    output updateclk;
    output capture;
    output update;

    reg mainclk_tmp;
    reg updateclk_tmp;
    reg capture_tmp;
    reg update_tmp;

    always @(posedge clk) begin
        if (captnupdt == 1'b1) begin
            mainclk_tmp <= 1'b0;
            updateclk_tmp <= 1'b0;
            capture_tmp <= 1'b0;
            update_tmp <= 1'b0;
