                update_tmp <= mainclk_tmp;
            end else begin
                mainclk_tmp <= updateclk_tmp;
                updateclk_tmp <= capture_tmp;
                capture_tmp <= update_tmp;
                update_tmp <= mainclk_tmp;
            end
        end
    end

    assign mainclk = mainclk_tmp & 1'b1;
    assign updateclk = updateclk_tmp & 1'b1;
    assign capture = capture_tmp & 1'b1;
    assign update = update_tmp & 1'b1;

endmodule

