module CFGLUT5(CDO,O5,O6,CDI,CE,CLK,I0,I1,I2,I3,I4);
    output CDO;
    output O5;
    output O6;
    input CDI;
    input CE;
    input CLK;
    input I4;
    input I3;
    input I2;
    input I1;
    input I0;

    reg [4:0] data_reg;
    reg [4:0] address_reg;
    reg [4:0] lut_out;
    reg [4:0] serial_data;
    reg [4:0] prev_address;
    reg [4:0] prev_data;
    reg [4:0] prev_serial_data;
    reg [4:0] next_data;
    reg [4:0] next_serial_data;
    reg [4:0] cascade_out;
    reg [4:0] lut_in;

    always @(posedge CLK) begin
        if (CE) begin
            address_reg <= {I4, I3, I2, I1, I0};
            if (address_reg != prev_address) begin
                prev_data <= data_reg;
                prev_serial_data <= serial_data;
                data_reg <= prev_data;
                serial_data <= prev_serial_data;
            end
            if (CDI) begin
                next_data <= {data_reg[3:0], CDI};
                next_serial_data <= {serial_data[3:0], CDI};
            end else begin
                next_data <= data_reg;
                next_serial_data <= serial_data;
            end
            data_reg <= next_data;
            serial_data <= next_serial_data;
            lut_in <= {data_reg[4], data_reg[3], data_reg[2], data_reg[1], data_reg[0]};
            lut_out <= {lut_in[4], lut_in[3], lut_in[2], lut_in[1], lut_in[0]};
            cascade_out <= lut_out[4];
            O5 <= lut_out[3];
            O6 <= lut_out[2];
            CDO <= lut_out[1];
        end
    end

    initial begin
        data_reg <= 5'b00000;
        address_reg <= 5'b00000;
        serial_data <= 5'b00000;
        prev_address <= 5'b00000;
        prev_data <= 5'b00000;
        prev_serial_data <= 5'b00000;
        next_data <= 5'b00000;
        next_serial_data <= 5'b00000;
        cascade_out <= 1'b0;
    end

endmodule

