module uart_tx_tester(
    input clk_50M,
    input run_test_raw,
    input tx_busy,
    output reg [7:0] data_out,
    output reg trigger
);

    parameter MSG_DELAY = 1000000; // Delay between messages in clock cycles

    // Define states
    parameter IDLE = 2'b00;
    parameter LOAD_DATA = 2'b01;
    parameter TRIGGER_TX = 2'b10;
    parameter POLL_BUSY = 2'b11;

    // Define delays
    parameter DATA_DELAY = 10; // Delay between data bits in clock cycles
    parameter BIT_DELAY = 10; // Delay between bits in clock cycles

    // Define message
    parameter MSG = "HelloWorld!";

    // Define internal registers
    reg [1:0] state;
    reg [7:0] data;
    reg [31:0] delay;
    reg [31:0] bit_delay;
    reg [31:0] data_delay;

    // Initialize internal registers
    initial begin
        state = IDLE;
        data = 8'h00;
        delay = 0;
        bit_delay = 0;
        data_delay = 0;
    end

    // State machine
    always @(posedge clk_50M) begin
        case (state)
            IDLE: begin
                if (run_test_raw) begin
                    state = LOAD_DATA;
                    data = MSG[0];
                    delay = 0;
                    bit_delay = 0;
                    data_delay = 0;
                end
            end
            LOAD_DATA: begin
                if (data_delay < DATA_DELAY) begin
                    data_delay = data_delay + 1;
                end else begin
                    data_delay = 0;
                    if (bit_delay < BIT_DELAY) begin
                        bit_delay = bit_delay + 1;
                    end else begin
                        bit_delay = 0;
                        data = MSG[data + 1];
                        if (data == 8'h00) begin
                            state = IDLE;
                            delay = 0;
                            bit_delay = 0;
                            data_delay = 0;
                        end
                    end
                end
            end
            TRIGGER_TX: begin
                trigger = 1;
                state = POLL_BUSY;
            end
            POLL_BUSY: begin
                if (tx_busy) begin
                    trigger = 0;
                    state = LOAD_DATA;
                end
            end
        endcase
    end

    // Output data
    always @(posedge clk_50M) begin
        if (state == TRIGGER_TX) begin
            data_out = data;
        end else begin
            data_out = 8'h00;
        end
    end

    // Delay between messages
    always @(posedge clk_50M) begin
        if (state == IDLE) begin
            if (delay < MSG_DELAY) begin
                delay = delay + 1;
            end else begin
                delay = 0;
                state = LOAD_DATA;
                data = MSG[0];
                data_delay = 0;
                bit_delay = 0;
            end
        end
    end

endmodule

