module gtx_tx_reset_controller(
    input wire clk,
    input wire ref_clk,
    input wire powerup_channel,
    output reg tx_running,
    output reg txreset,
    output reg txuserrdy,
    output reg txpmareset,
    output reg txpcsreset,
    output reg pllpd,
    output reg pllreset,
    output reg plllocken,
    input wire plllock,
    output reg resetsel,
    input wire txresetdone
);

    // Define states
    parameter IDLE = 2'b00;
    parameter RESET_TX = 2'b01;
    parameter WAIT_TX_RESET = 2'b10;
    parameter RESET_PLL = 2'b11;

    // Define counters
    reg [31:0] counter;
    reg [1:0] state;

    // Define metastability registers
    reg [1:0] state_meta;
    reg [31:0] counter_meta;

    // Synchronize signals across clock domains
    always @(posedge clk) begin
        state_meta <= state;
        counter_meta <= counter;
    end

    // State machine
    always @(posedge clk) begin
        case (state)
            IDLE: begin
                if (powerup_channel == 1'b0) begin
                    state <= IDLE;
                    counter <= 0;
                    txreset <= 1'b1;
                    txuserrdy <= 1'b0;
                    txpmareset <= 1'b1;
                    txpcsreset <= 1'b1;
                    pllpd <= 1'b0;
                    pllreset <= 1'b1;
                    plllocken <= 1'b0;
                    resetsel <= 1'b0;
                end else if (counter_meta == 32'hFFFFFFFF) begin
                    state <= RESET_TX;
                    counter <= 0;
                    txreset <= 1'b0;
                    txuserrdy <= 1'b1;
                    txpmareset <= 1'b0;
                    txpcsreset <= 1'b0;
                    pllpd <= 1'b1;
                    pllreset <= 1'b0;
                    plllocken <= 1'b1;
                    resetsel <= 1'b1;
                end else begin
                    counter <= counter_meta + 1;
                end
            end
            RESET_TX: begin
                if (counter_meta == 32'hFFFFFFFF) begin
                    state <= WAIT_TX_RESET;
                    counter <= 0;
                    txreset <= 1'b0;
                    txuserrdy <= 1'b1;
                    txpmareset <= 1'b0;
                    txpcsreset <= 1'b0;
                    pllpd <= 1'b1;
                    pllreset <= 1'b0;
                    plllocken <= 1'b1;
                    resetsel <= 1'b1;
                end else begin
                    counter <= counter_meta + 1;
                end
            end
            WAIT_TX_RESET: begin
                if (txresetdone == 1'b1) begin
                    state <= RESET_PLL;
                    counter <= 0;
                    txreset <= 1'b0;
                    txuserrdy <= 1'b1;
                    txpmareset <= 1'b0;
                    txpcsreset <= 1'b0;
                    pllpd <= 1'b1;
                    pllreset <= 1'b0;
                    plllocken <= 1'b1;
                    resetsel <= 1'b1;
                end else begin
                    counter <= counter_meta + 1;
                end
            end
            RESET_PLL: begin
                if (counter_meta == 32'hFFFFFFFF) begin
                    state <= IDLE;
                    counter <= 0;
                    txreset <= 1'b0;
                    txuserrdy <= 1'b1;
                    txpmareset <= 1'b0;
                    txpcsreset <= 1'b0;
                    pllpd <= 1'b1;
                    pllreset <= 1'b0;
                    plllocken <= 1'b1;
                    resetsel <= 1'b1;
                end else begin
                    counter <= counter_meta + 1;
                end
            end
        endcase
    end

    // Set tx_running high only after successful PLL lock and reset completion
    always @(posedge clk) begin
        if (plllock == 1'b1 && txresetdone == 1'b1) begin
            tx_running <= 1'b1;
        end else begin
            tx_running <= 1'b0;
        end
    end

endmodule

