module datapath(clk, startGameEn, user_x, user_y, enemy_x, enemy_y, enem_grid, x, y, colour);

    input clk, startGameEn;
    input [7:0] user_x, user_y;
    input [7:0] enemy_x, enemy_y;
    input [160*120-1:0] enem_grid;
    output reg [7:0] x;
    output reg [6:0] y;
    output reg [2:0] colour;

    reg [7:0] x_next;
    reg [6:0] y_next;
    reg [2:0] colour_next;

    always @(posedge clk) begin
        if (startGameEn) begin
            x <= 8'd0;
            y <= 7'd0;
            colour <= 3'b000;
        end else begin
            x <= x_next;
            y <= y_next;
            colour <= colour_next;
        end
    end

    always @(*) begin
        if (x == 8'd160) begin
            x_next = 8'd0;
            y_next = y + 1;
        end else begin
            x_next = x + 1;
            y_next = y;
        end

        if (y == 7'd120) begin
            colour_next = 3'b000;
        end else if (x == user_x && y == user_y) begin
            colour_next = 3'b001;
        end else if (x == enemy_x && y == enemy_y) begin
            colour_next = 3'b010;
        end else if (enem_grid[y*160 + x] == 1'b1) begin
            colour_next = 3'b100;
        end else begin
            colour_next = 3'b000;
        end
    end

endmodule

module sonar(input clk, rst_n, input do_measure, input sonar_pulse, output reg [7:0] inches, output reg sonar_trigger=0, output reg READY=0);

  // Define states
  parameter STANDBY = 2'b00;
  parameter START_MEASURE = 2'b01;
  parameter WAIT_FOR_PULSE = 2'b10;
  parameter COUNT_PULSE = 2'b11;

  // Define registers
  reg [1:0] state;
  reg [7:0] timeCount;
  reg [7:0] pulseCount;
  reg [7:0] timeoutCounter;

  // Define constants
  parameter TIMEOUT_COUNT_MAX = 8'd255;
  parameter PULSE_COUNT_MAX = 8'd255;
  parameter INCHES_PER_CYCLE = 8'd1;

  // Define state machine
  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      state <= STANDBY;
      timeCount <= 0;
      pulseCount <= 0;
      timeoutCounter <= 0;
      inches <= 0;
      sonar_trigger <= 0;
      READY <= 0;
    end else begin
      case (state)
        STANDBY: begin
          if (do_measure) begin
            state <= START_MEASURE;
            sonar_trigger <= 1;
          end
        end
        START_MEASURE: begin
          if (sonar_pulse) begin
            state <= WAIT_FOR_PULSE;
            timeoutCounter <= 0;
          end else if (timeoutCounter == TIMEOUT_COUNT_MAX) begin
            state <= STANDBY;
            inches <= 0;
            READY <= 1;
          end else begin
            timeoutCounter <= timeoutCounter + 1;
          end
        end
        WAIT_FOR_PULSE: begin
          if (~sonar_pulse) begin
            state <= COUNT_PULSE;
            pulseCount <= 0;
          end
        end
        COUNT_PULSE: begin
          if (sonar_pulse) begin
            pulseCount <= pulseCount + 1;
            if (pulseCount == PULSE_COUNT_MAX) begin
              state <= STANDBY;
              inches <= pulseCount * INCHES_PER_CYCLE;
              READY <= 1;
            end
          end else begin
            state <= STANDBY;
            inches <= pulseCount * INCHES_PER_CYCLE;
            READY <= 1;
          end
        end
      endcase
    end
  end

  // Update timeCount register
  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      timeCount <= 0;
    end else if (state == COUNT_PULSE) begin
      timeCount <= timeCount + 1;
    end
  end

endmodule

