module voting (
  input [2:0] a0,
  input [2:0] a1,
  input [2:0] a2,
  input [2:0] a3,
  input [2:0] a4,
  output reg [2:0] out
);

  wire [4:0] sum0, sum1, sum2;
  wire [2:0] max_sum;
  wire error;

  // Full adder for sum0
  full_adder fa0(a0[0], a1[0], a2[0], sum0[0]);
  full_adder fa1(a0[1], a1[1], a2[1], sum0[1]);
  full_adder fa2(a0[2], a1[2], a2[2], sum0[2]);

  // Full adder for sum1
  full_adder fa3(a3[0], a4[0], sum0[0], sum1[0]);
  full_adder fa4(a3[1], a4[1], sum0[1], sum1[1]);
  full_adder fa5(a3[2], a4[2], sum0[2], sum1[2]);

  // Full adder for sum2
  full_adder fa6(sum1[0], sum1[1], sum1[2], sum2[0]);
  full_adder fa7(sum1[3], sum1[4], sum2[0], sum2[1]);
  full_adder fa8(sum1[4], sum2[1], sum2[0], sum2[2]);

  // Error detection
  assign error = (sum0[2] !== sum1[2]) || (sum1[2] !== sum2[2]);

  // Max sum detection
  assign max_sum = (sum0 > sum1) ? sum0 : sum1;
  assign max_sum = (max_sum > sum2) ? max_sum : sum2;

  // Output selection
  always @(*) begin
    if (error) begin
      out = 3'b111; // Error occurred
    end else begin
      case (max_sum)
        3'b000: out = 3'b000; // No majority vote
        3'b001: out = 3'b001; // Vote for option 1
        3'b010: out = 3'b010; // Vote for option 2
        3'b011: out = 3'b011; // Vote for option 3
        3'b100: out = 3'b100; // Vote for option 4
        3'b101: out = 3'b101; // Vote for option 5
        3'b110: out = 3'b110; // Vote for option 6
        3'b111: out = 3'b111; // Vote for option 7
      endcase
    end
  end

endmodule

