);

  reg [1:0] state;
  reg [1:0] grant;
  reg [1:0] counter;
  reg [129-1:0] data0;
  reg [129-1:0] data1;
  reg [11-1:0] channel0;
  reg [11-1:0] channel1;
  reg startofpacket0;
  reg startofpacket1;
  reg endofpacket0;
  reg endofpacket1;
  reg ready0;
  reg ready1;
  reg valid0;
  reg valid1;

  always @(posedge clk) begin
    if (reset) begin
      state <= 2'b00;
      grant <= 2'b00;
      counter <= 2'b00;
      data0 <= 129'b0;
      data1 <= 129'b0;
      channel0 <= 11'b0;
      channel1 <= 11'b0;
      startofpacket0 <= 1'b0;
      startofpacket1 <= 1'b0;
      endofpacket0 <= 1'b0;
      endofpacket1 <= 1'b0;
      ready0 <= 1'b0;
      ready1 <= 1'b0;
      valid0 <= 1'b0;
      valid1 <= 1'b0;
    end else begin
      case (state)
        2'b00: begin // idle state
          if (sink0_valid && sink1_valid) begin
            if (counter == 2'b00) begin
              grant <= 2'b00;
              counter <= 2'b01;
            end else begin
              grant <= 2'b01;
              counter <= 2'b00;
            end
          end else if (sink0_valid) begin
            grant <= 2'b00;
          end else if (sink1_valid) begin
            grant <= 2'b01;
          end
          state <= 2'b01;
        end
        2'b01: begin // grant state
          if (grant == 2'b00) begin
            data0 <= sink0_data;
            channel0 <= sink0_channel;
            startofpacket0 <= sink0_startofpacket;
            endofpacket0 <= sink0_endofpacket;
            ready0 <= sink0_ready;
            valid0 <= sink0_valid;
          end else begin
            data1 <= sink1_data;
            channel1 <= sink1_channel;
            startofpacket1 <= sink1_startofpacket;
            endofpacket1 <= sink1_endofpacket;
            ready1 <= sink1_ready;
            valid1 <= sink1_valid;
          end
          state <= 2'b10;
        end
        2'b10: begin // output state
          if (grant == 2'b00) begin
            src_valid <= valid0;
            src_data <= data0;
            src_channel <= channel0;
            src_startofpacket <= startofpacket0;
            src_endofpacket <= endofpacket0;
            ready0 <= src_ready;
          end else begin
            src_valid <= valid1;
            src_data <= data1;
            src_channel <= channel1;
            src_startofpacket <= startofpacket1;
            src_endofpacket <= endofpacket1;
            ready1 <= src_ready;
          end
          state <= 2'b00;
        end
      endcase
    end
  end

