module sr04_receiver(input CLK, input reset, input echo, output reg trig, output reg [23:0] distance);
    reg [23:0] count;
    reg [1:0] state;
    parameter IDLE = 2'b00, TRIGGER = 2'b01, MEASURE = 2'b10;

    always @(posedge CLK) begin
        if (reset) begin
            count <= 0;
            state <= IDLE;
            trig <= 0;
            distance <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (echo) begin
                        state <= TRIGGER;
                        trig <= 1;
                        count <= 0;
                    end
                end
                TRIGGER: begin
                    if (count == 100000) begin
                        state <= MEASURE;
                        trig <= 0;
                        count <= 0;
                    end else begin
                        count <= count + 1;
                    end
                end
                MEASURE: begin
                    if (count == 100000) begin
                        distance <= count;
                        state <= IDLE;
                        count <= 0;
                    end else begin
                        count <= count + 1;
                    end
                end
            endcase
        end
    end
endmodule

