module CIRCUIT2(a, b, c, x, z, Clk, Rst);
    input [31:0] a, b, c;
    input Clk, Rst;
    output [31:0] x, z;

    reg [31:0] a_reg, b_reg, c_reg, x_reg, z_reg;
    reg [31:0] add_ab, add_ac, sub_bc, comp_result;
    reg [1:0] mux_select;

    // Register inputs
    always @(posedge Clk) begin
        if (Rst) begin
            a_reg <= 0;
            b_reg <= 0;
            c_reg <= 0;
        end else begin
            a_reg <= a;
            b_reg <= b;
            c_reg <= c;
        end
    end

    // Addition operations
    assign add_ab = a_reg + b_reg;
    assign add_ac = a_reg + c_reg;

    // Subtraction operation
    assign sub_bc = a_reg - b_reg;

    // Comparator
    assign comp_result = (add_ab > add_ac) ? 1 : 0;

    // Multiplexer selection
    always @(*) begin
        if (comp_result == 1) begin
            mux_select = 2'b01; // Right shift
        end else begin
            mux_select = 2'b10; // Left shift
        end
    end

    // Multiplexer
    always @(*) begin
        case (mux_select)
            2'b01: z_reg = sub_bc >> 1;
            2'b10: z_reg = sub_bc << 1;
            default: z_reg = 0;
        endcase
    end

    // Register outputs
    always @(posedge Clk) begin
        if (Rst) begin
            x_reg <= 0;
            z_reg <= 0;
        end else begin
            x_reg <= add_ab;
            z_reg <= z_reg;
        end
    end

    assign x = x_reg;
    assign z = z_reg;

endmodule

