module FPAddSub_reduced(clk, rst, a, b, operation, result, flags);

  // Define constants
  localparam MANTISSA_WIDTH = 23;
  localparam EXPONENT_WIDTH = 8;
  localparam SIGN_WIDTH = 1;
  localparam FLAGS_WIDTH = 5;

  // Define wires
  wire [31:0] a_wire, b_wire;
  wire [MANTISSA_WIDTH-1:0] mantissa_a, mantissa_b, mantissa_result;
  wire [EXPONENT_WIDTH-1:0] exponent_a, exponent_b, exponent_result;
  wire sign_a, sign_b, sign_result;
  wire [FLAGS_WIDTH-1:0] flags_wire;

  // Define registers
  reg [31:0] pipe_1, pipe_2, pipe_3;

  // Define stages
  stage_sign_and_exponent stage_1(clk, rst, a, b, operation, a_wire, b_wire, exponent_a, exponent_b, sign_a, sign_b);
  stage_mantissa_addition stage_2(clk, rst, a_wire, b_wire, mantissa_a, mantissa_b, mantissa_result);
  stage_normalization stage_3(clk, rst, mantissa_result, exponent_result, sign_result, result);
  stage_result_packaging stage_4(clk, rst, result, flags_wire);

  // Assign flags
  assign flags = flags_wire;

  // Assign intermediate results
  assign a_wire = {sign_a, exponent_a, mantissa_a};
  assign b_wire = {sign_b, exponent_b, mantissa_b};
  assign mantissa_result = pipe_1[MANTISSA_WIDTH-1:0];
  assign exponent_result = pipe_2[EXPONENT_WIDTH-1:0];
  assign sign_result = pipe_3[SIGN_WIDTH-1:0];

  // Assign flags
  assign flags_wire[0] = (exponent_result == 0) ? 1'b1 : 1'b0; // Underflow
  assign flags_wire[1] = (exponent_result == 255) ? 1'b1 : 1'b0; // Overflow
  assign flags_wire[2] = (mantissa_result == 0) ? 1'b1 : 1'b0; // Zero
  assign flags_wire[3] = (sign_result == 1) ? 1'b1 : 1'b0; // Negative
  assign flags_wire[4] = (operation == 1) ? 1'b1 : 1'b0; // Subtraction

  // Pipeline registers
  always @(posedge clk) begin
    if (rst) begin
      pipe_1 <= 0;
      pipe_2 <= 0;
      pipe_3 <= 0;
    end else begin
      pipe_1 <= {sign_result, exponent_result, mantissa_result};
      pipe_2 <= {sign_result, exponent_result};
      pipe_3 <= {sign_result};
    end
  end

endmodule

