  // Higher bit addition
  assign sum_higher[1] = i_a[1] ^ i_b[1] ^ carry_lower;
  assign carry_higher = (i_a[1] & i_b[1]) | (i_a[1] & carry_lower) | (i_b[1] & carry_lower);

  // Output
  assign o_sum = {sum_higher[1], sum_lower[0]};
  assign o_carry = carry_higher;

