module debounce_circuit(
    input clk,
    input n_reset,
    input button_in,
    output reg out
);

parameter max_bit = 8;

reg [max_bit-1:0] q_reg;
reg [max_bit-1:0] q_next;
reg f1, f2;
wire q_add;
wire q_reset;

always @(posedge clk or negedge n_reset) begin
    if (n_reset == 0) begin
        q_reg <= 0;
    end else begin
        q_reg <= q_next;
    end
end

always @(*) begin
    q_next = q_reg;
    if (q_add) begin
        q_next = q_reg + 1;
    end
    if (q_reset) begin
        q_next = 0;
    end
end

assign q_add = (f1 & ~f2);
assign q_reset = (~f1 & f2);

always @(posedge clk) begin
    f1 <= button_in;
    f2 <= f1;
end

always @(*) begin
    if (q_reg == max_bit-1) begin
        out = 1;
    end else begin
        out = 0;
    end
end

endmodule

