  reg [3:0] wp;
  reg [3:0] rp;
  reg w_flag;
  reg r_flag;

  always @(posedge clock) begin
    if (sclr) begin
      wp <= 0;
      rp <= 0;
      w_flag <= 0;
      r_flag <= 0;
      full <= 0;
      empty <= 1;
    end else begin
      if (wrreq && !full) begin
        mem[wp] <= data;
        wp <= wp + 1;
        if (wp == 16) begin
          wp <= 0;
        end
        w_flag <= 1;
        if (rp == wp) begin
          full <= 1;
        end
        empty <= 0;
      end
      if (rdreq && !empty) begin
        q <= mem[rp];
        rp <= rp + 1;
        if (rp == 16) begin
          rp <= 0;
        end
        r_flag <= 1;
        if (wp == rp) begin
          empty <= 1;
        end
        full <= 0;
      end
    end
  end

