            8'b00000011: y = {u0, u1, u2, u3, u4, u5, u6, u7} + {s0, s1, s2, s3, s4, s5, s6, s7};
            8'b00000100: y = {u0, u1, u2, u3, u4, u5, u6, u7} - {s0, s1, s2, s3, s4, s5, s6, s7};
            8'b00000101: y = {u0, u1, u2, u3, u4, u5, u6, u7} & {s0, s1, s2, s3, s4, s5, s6, s7};
