module mul8x3u_0BH(A, B, O);
    input [7:0] A;
    input [2:0] B;
    output [10:0] O;

    wire [7:0] A_extended;
    wire [2:0] B_extended;
    wire [15:0] partial_products;
    wire [3:0] carry;
    wire [10:0] sum;

    // Extend inputs to 16 bits
    assign A_extended = {A, 8'b0};
    assign B_extended = {B, 5'b0};

    // Generate partial products
    assign partial_products[0] = A_extended[0] & B_extended[0];
    assign partial_products[1] = A_extended[0] & B_extended[1];
    assign partial_products[2] = A_extended[0] & B_extended[2];
    assign partial_products[3] = A_extended[1] & B_extended[0];
    assign partial_products[4] = A_extended[1] & B_extended[1];
    assign partial_products[5] = A_extended[1] & B_extended[2];
    assign partial_products[6] = A_extended[2] & B_extended[0];
    assign partial_products[7] = A_extended[2] & B_extended[1];
    assign partial_products[8] = A_extended[2] & B_extended[2];
    assign partial_products[9] = A_extended[3] & B_extended[0];
    assign partial_products[10] = A_extended[3] & B_extended[1];
    assign partial_products[11] = A_extended[3] & B_extended[2];
    assign partial_products[12] = A_extended[4] & B_extended[0];
    assign partial_products[13] = A_extended[4] & B_extended[1];
    assign partial_products[14] = A_extended[4] & B_extended[2];
    assign partial_products[15] = A_extended[5] & B_extended[0];
    assign partial_products[16] = A_extended[5] & B_extended[1];
    assign partial_products[17] = A_extended[5] & B_extended[2];
    assign partial_products[18] = A_extended[6] & B_extended[0];
    assign partial_products[19] = A_extended[6] & B_extended[1];
    assign partial_products[20] = A_extended[6] & B_extended[2];
    assign partial_products[21] = A_extended[7] & B_extended[0];
    assign partial_products[22] = A_extended[7] & B_extended[1];
    assign partial_products[23] = A_extended[7] & B_extended[2];

    // Generate carry
    assign carry[0] = partial_products[0] | partial_products[1] | partial_products[2];
    assign carry[1] = partial_products[3] | partial_products[4] | partial_products[5];
    assign carry[2] = partial_products[6] | partial_products[7] | partial_products[8];
    assign carry[3] = partial_products[9] | partial_products[10] | partial_products[11];
    assign carry[4] = partial_products[12] | partial_products[13] | partial_products[14];
    assign carry[5] = partial_products[15] | partial_products[16] | partial_products[17];
    assign carry[6] = partial_products[18] | partial_products[19] | partial_products[20];
    assign carry[7] = partial_products[21] | partial_products[22] | partial_products[23];

    // Generate sum
    assign sum[0] = partial_products[0] ^ carry[0];
    assign sum[1] = partial_products[1] ^ carry[0] ^ carry[1];
    assign sum[2] = partial_products[2] ^ carry[0] ^ carry[1] ^ carry[2];
    assign sum[3] = partial_products[3] ^ carry[1] ^ carry[2] ^ carry[3];
    assign sum[4] = partial_products[4] ^ carry[1] ^ carry[2] ^ carry[3] ^ carry[4];
    assign sum[5] = partial_products[5] ^ carry[1] ^ carry[2] ^ carry[3] ^ carry[4] ^ carry[5];
    assign sum[6] = partial_products[6] ^ carry[2] ^ carry[3] ^ carry[4] ^ carry[5] ^ carry[6];
    assign sum[7] = partial_products[7] ^ carry[2] ^ carry[3] ^ carry[4] ^ carry[5] ^ carry[6] ^ carry[7];
    assign sum[8] = partial_products[8] ^ carry[2] ^ carry[3] ^ carry[4] ^ carry[5] ^ carry[6] ^ carry[7];
    assign sum[9] = partial_products[9] ^ carry[3] ^ carry[4] ^ carry[5] ^ carry[6] ^ carry[7];
    assign sum[10] = partial_products[10] ^ carry[3] ^ carry[4] ^ carry[5] ^ carry[6] ^ carry[7];

    // Assign output
    assign O = {sum[10], sum[9], sum[8], sum[7], sum[6], sum[5], sum[4], sum[3], sum[2], sum[1], sum[0]};

endmodule

