module AdderTreePipelined #(parameter DATA_WIDTH=32, parameter LENGTH=8, parameter OUT_WIDTH=DATA_WIDTH+$clog2(LENGTH), parameter DELAY_STAGES=$clog2(LENGTH))
(
    input rst,
    input clk,
    input in_advance,
    input signed [LENGTH*DATA_WIDTH-1:0] in_addends,
    output signed [OUT_WIDTH-1:0] out_sum
);

    // Define internal signals
    wire [LENGTH-1:0] split_addends [1:LENGTH];
    wire [OUT_WIDTH-1:0] subtree_sums [1:LENGTH];
    wire [OUT_WIDTH-1:0] stage_sums [0:DELAY_STAGES-1];
    wire [OUT_WIDTH-1:0] final_sum;

    // Split the input addends into two halves
    for (i = 0; i < LENGTH; i = i + 2) begin
        assign split_addends[i/2] = {in_addends[i*DATA_WIDTH+DATA_WIDTH-1:i*DATA_WIDTH], in_addends[(i+1)*DATA_WIDTH+DATA_WIDTH-1:(i+1)*DATA_WIDTH]};
    end

    // Recursively split the addends into smaller groups and process them by subtrees
    for (i = 1; i <= LENGTH; i = i * 2) begin
        for (j = 0; j < LENGTH/i; j = j + 1) begin
            AdderTreePipelined #(.DATA_WIDTH(DATA_WIDTH), .LENGTH(i), .OUT_WIDTH(OUT_WIDTH), .DELAY_STAGES(DELAY_STAGES)) subtree (
                .rst(rst),
                .clk(clk),
                .in_advance(in_advance),
                .in_addends(split_addends[j*i+i-1:j*i]),
                .out_sum(subtree_sums[j*i+i-1:j*i])
            );
        end
    end

    // Combine the results from the subtrees
    for (i = 0; i < LENGTH; i = i + 1) begin
        assign stage_sums[0][i*DATA_WIDTH+DATA_WIDTH-1:i*DATA_WIDTH] = subtree_sums[i];
    end

    // Pipeline the results through stages
    for (i = 1; i < DELAY_STAGES; i = i + 1) begin
        for (j = 0; j < LENGTH/2**i; j = j + 1) begin
            assign stage_sums[i][j*2**i*DATA_WIDTH+DATA_WIDTH-1:j*2**i*DATA_WIDTH] = stage_sums[i-1][j*2**i*2*DATA_WIDTH+DATA_WIDTH-1:j*2**i*2*DATA_WIDTH] + stage_sums[i-1][(j*2**i+1)*2*DATA_WIDTH+DATA_WIDTH-1:(j*2**i+1)*2*DATA_WIDTH];
        end
    end

    // Assign the final sum
    assign final_sum = stage_sums[DELAY_STAGES-1];

    // Output the final sum
    assign out_sum = final_sum;

endmodule

