    assign pA = {pA5, pA4, pA3, pA2, pA1, pA0};
    assign pB = {pB5, pB4, pB3, pB2, pB1, pB0};

    // Generate initial sum and carry terms
    assign {g[0], p[0]} = pA ^ pB;
    assign c[0] = cIn;

