module add16u_1JH(A,B,O);
    input [15:0] A,B;
    output [16:0] O;

    wire [15:0] sum;
    wire [16:0] carry;

    assign carry[0] = 1'b0;
    assign O[0] = sum[0];
    assign O[1] = sum[1];
    assign O[2] = 1'b0;
    assign O[3] = 1'b0;
    assign O[4] = carry[15];

    genvar i;
    generate
        for (i = 0; i < 16; i = i + 1) begin : adder
            assign sum[i] = A[i] ^ B[i] ^ carry[i];
            assign carry[i+1] = (A[i] & B[i]) | (A[i] & carry[i]) | (B[i] & carry[i]);
        end
    endgenerate

    assign O[16] = carry[16];

endmodule

