module multi_seven_seg_6(input clk, input rst, input [15:0] value, output reg [6:0] segs, output reg [3:0] sel);
module multi_seven_seg_6(input clk, input rst, input [15:0] value, output reg [6:0] segs, output reg [3:0] sel);

  // Parameters
  parameter NUM_DIGITS = 4;
  parameter DIV_FACTOR = 16;
  parameter BIT_WIDTH = 4;

  // Internal signals
  reg [3:0] digit_index;
  reg [3:0] digit_value;
  reg [6:0] seg_value;
  reg [3:0] sel_value;

  // Counter
  always @(posedge clk, posedge rst) begin
    if (rst) begin
      digit_index <= 0;
    end else begin
      digit_index <= digit_index + 1;
    end
  end

  // Seven-segment decoder
  always @(*) begin
    case (digit_value)
      4'b0000: seg_value = 7'b1000000;
      4'b0001: seg_value = 7'b1111001;
      4'b0010: seg_value = 7'b0100100;
      4'b0011: seg_value = 7'b0110000;
      4'b0100: seg_value = 7'b0011001;
      4'b0101: seg_value = 7'b0010010;
      4'b0110: seg_value = 7'b0000010;
      4'b0111: seg_value = 7'b1111000;
      4'b1000: seg_value = 7'b0000000;
      4'b1001: seg_value = 7'b0010000;
      default: seg_value = 7'b0000000;
    endcase
  end

  // Digit decoder
  always @(*) begin
    case (digit_index)
      0: sel_value = 4'b0001;
      1: sel_value = 4'b0010;
      2: sel_value = 4'b0100;
      3: sel_value = 4'b1000;
      default: sel_value = 4'b0000;
    endcase
  end

  // Multiplexer
  always @(*) begin
    case (digit_index)
      0: segs = seg_value;
      1: segs = seg_value;
      2: segs = seg_value;
      3: segs = seg_value;
      default: segs = 7'b0000000;
    endcase
  end

  // Assign digit value
  always @(posedge clk, posedge rst) begin
    if (rst) begin
      digit_value <= 0;
    end else begin
      digit_value <= value[digit_index*BIT_WIDTH +: BIT_WIDTH];
    end
  end

endmodule

