        case(current_state)
            S0: begin
                if(in == 3'b011) begin
                    current_state <= S1;
                    state <= 1'b1;
                end else begin
                    current_state <= S0;
                    state <= 1'b0;
                end
            end
            S1: begin
                if(in == 3'b011) begin
                    current_state <= S1;
                    state <= 1'b1;
                end else begin
                    current_state <= S0;
                    state <= 1'b0;
                end
            end
        endcase
    end

    initial begin
        current_state <= S0;
        state <= 1'b0;
    end
endmodule

