    input wire zedboard_clk,
    input wire enable,
    input wire reset,
    output reg timerOutput
);

    reg [31:0] timer_value;
    parameter MAX_COUNT = 100000;

    always @(posedge zedboard_clk) begin
        if (reset) begin
            timer_value <= 0;
            timerOutput <= 0;
        end else if (enable) begin
            if (timer_value == MAX_COUNT) begin
                timer_value <= 0;
                timerOutput <= 1;
            end else begin
                timer_value <= timer_value + 1;
                timerOutput <= 0;
            end
        end
    end

