        case (data)
            8'h00: begin red = 4'h0; green = 4'h0; blue = 4'h0; end // black
            8'h01: begin red = 4'hF; green = 4'h0; blue = 4'h0; end // red
            8'h02: begin red = 4'h0; green = 4'hF; blue = 4'h0; end // green
            8'h03: begin red = 4'hF; green = 4'hF; blue = 4'h0; end // yellow
            8'h04: begin red = 4'h0; green = 4'h0; blue = 4'hF; end // blue
            8'h05: begin red = 4'hF; green = 4'h0; blue = 4'hF; end // purple
            8'h06: begin red = 4'h0; green = 4'hF; blue = 4'hF; end // cyan
            8'h07: begin red = 4'hF; green = 4'hF; blue = 4'hF; end // white
            default: begin red = 4'h0; green = 4'h0; blue = 4'h0; end // black
        endcase
    end
endmodule

module Walk2R_example(input logic vga_clk, input logic [9:0] DrawX, DrawY, input logic blank, output logic [3:0] red, green, blue);
    wire [10:0] rom_addr;
    wire [7:0] rom_data;
    wire [3:0] palette_red, palette_green, palette_blue;

    assign rom_addr = (DrawX / 8) + (DrawY / 8) * 128;

    ROM rom_inst(.addr(rom_addr), .data(rom_data));
    palette palette_inst(.data(rom_data), .red(palette_red), .green(palette_green), .blue(palette_blue));

    reg [3:0] red_reg, green_reg, blue_reg;

    always @(posedge vga_clk) begin
        if (blank) begin
            red_reg <= 4'h0;
            green_reg <= 4'h0;
            blue_reg <= 4'h0;
        end else begin
            red_reg <= palette_red;
            green_reg <= palette_green;
            blue_reg <= palette_blue;
        end
    end

    assign red = red_reg;
    assign green = green_reg;
    assign blue = blue_reg;

endmodule

