module conv_apb(
    input wire PCLK,
    input wire PRESETB,
    input wire [31:0] PADDR,
    input wire PSEL,
    input wire PENABLE,
    input wire PWRITE,
    input wire [31:0] PWDATA,
    output wire [31:0] PRDATA,
    input wire [31:0] clk_counter,
    input wire conv_done,
    output reg conv_start,
    output reg [2:0] COMMAND,
    output reg [8:0] InCh,
    output reg [8:0] OutCh,
    output reg [5:0] FLength,
    input wire F_writedone,
    output reg F_writedone_respond,
    input wire B_writedone,
    output reg B_writedone_respond,
    input wire rdy_to_transmit,
    output reg rdy_to_transmit_respond,
    input wire transmit_done,
    output reg transmit_done_respond
);

reg [31:0] reg_InCh;
reg [31:0] reg_OutCh;
reg [31:0] reg_FLength;
reg [31:0] reg_COMMAND;
reg [31:0] reg_conv_start;
reg [31:0] reg_F_writedone_respond;
reg [31:0] reg_B_writedone_respond;
reg [31:0] reg_rdy_to_transmit_respond;
reg [31:0] reg_transmit_done_respond;

always @(posedge PCLK) begin
    if (PRESETB == 0) begin
        reg_InCh <= 0;
        reg_OutCh <= 0;
        reg_FLength <= 0;
        reg_COMMAND <= 0;
        reg_conv_start <= 0;
        reg_F_writedone_respond <= 0;
        reg_B_writedone_respond <= 0;
        reg_rdy_to_transmit_respond <= 0;
        reg_transmit_done_respond <= 0;
    end else begin
        if (PSEL && PENABLE && PWRITE) begin
            case (PADDR)
                32'h00000000: reg_InCh <= PWDATA;
                32'h00000004: reg_OutCh <= PWDATA;
                32'h00000008: reg_FLength <= PWDATA;
                32'h0000000C: reg_COMMAND <= PWDATA;
                32'h00000010: reg_conv_start <= PWDATA;
                32'h00000014: reg_F_writedone_respond <= PWDATA;
                32'h00000018: reg_B_writedone_respond <= PWDATA;
                32'h0000001C: reg_rdy_to_transmit_respond <= PWDATA;
                32'h00000020: reg_transmit_done_respond <= PWDATA;
            endcase
        end
    end
end

assign PRDATA = (PSEL && PENABLE && !PWRITE) ?
    (case (PADDR)
        32'h00000000: reg_InCh;
        32'h00000004: reg_OutCh;
        32'h00000008: reg_FLength;
        32'h0000000C: reg_COMMAND;
        32'h00000010: reg_conv_start;
        32'h00000014: reg_F_writedone_respond;
        32'h00000018: reg_B_writedone_respond;
        32'h0000001C: reg_rdy_to_transmit_respond;
        32'h00000020: reg_transmit_done_respond;
    endcase) : 32'h00000000;

assign InCh = reg_InCh[8:0];
assign OutCh = reg_OutCh[8:0];
assign FLength = reg_FLength[5:0];
assign conv_start = reg_conv_start[0];
assign COMMAND = reg_COMMAND[2:0];
assign F_writedone_respond = reg_F_writedone_respond[0];
assign B_writedone_respond = reg_B_writedone_respond[0];
assign rdy_to_transmit_respond = reg_rdy_to_transmit_respond[0];
assign transmit_done_respond = reg_transmit_done_respond[0];

endmodule

module decoder_2_4(input clk, input [1:0] in, output reg [3:0] out);

always @(posedge clk) begin
    case (in)
        2'b00: out <= 4'b0001;
        2'b01: out <= 4'b0010;
        2'b10: out <= 4'b0100;
        2'b11: out <= 4'b1000;
        default: out <= 4'b0000;
    endcase
end

endmodule

