module motor_rpm_count(
    input clk,
    input motor_rot_pulse,
    output reg [15:0] rpm_output
);

    reg [31:0] pulse_count = 50000000;
    reg last_scan_value = 1'b0;
    reg [15:0] pulse_count_qty = 16'd0;
    reg [15:0] output_count_qty = 16'd0;

    always @(posedge clk) begin
        pulse_count <= pulse_count - 1;
        if (pulse_count == 0) begin
            pulse_count <= 50000000;
            output_count_qty <= pulse_count_qty;
            pulse_count_qty <= 16'd0;
        end
        else if (motor_rot_pulse != last_scan_value) begin
            pulse_count_qty <= pulse_count_qty + 1;
            last_scan_value <= motor_rot_pulse;
        end
    end

    assign rpm_output = output_count_qty * 60;

endmodule

module edge_detect(
    input clk,
    input rst_n,
    input a,
    output reg rise,
    output reg down
);

reg a_prev;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        rise <= 1'b0;
        down <= 1'b0;
        a_prev <= 1'b0;
    end else begin
        if (a > a_prev) begin
            rise <= 1'b1;
            down <= 1'b0;
        end else if (a < a_prev) begin
            rise <= 1'b0;
            down <= 1'b1;
        end else begin
            rise <= 1'b0;
            down <= 1'b0;
        end
        a_prev <= a;
    end
end

endmodule

