module top_flag_ethiopia #(parameter CORDW=10)(
    input wire logic clk_pix,
    input wire logic sim_rst,
    output logic [CORDW-1:0] sdl_sx,
    output logic [CORDW-1:0] sdl_sy,
    output logic sdl_de,
    output logic [7:0] sdl_r,
    output logic [7:0] sdl_g,
    output logic [7:0] sdl_b
);

    // Sequential design due to its use of always_ff for output registration, with timing controlled by the pixel clock and reset.
    always_ff @(posedge clk_pix or posedge sim_rst) begin
        if (sim_rst) begin
            sdl_sx <= 0;
            sdl_sy <= 0;
            sdl_de <= 0;
            sdl_r <= 0;
            sdl_g <= 0;
            sdl_b <= 0;
        end else begin
            // Determine the vertical position on the screen using the sys signal.
            if (sy < 160) begin
                sdl_r <= 8'h00;
                sdl_g <= 8'hFF;
                sdl_b <= 8'h00;
            end else if (sy < 320) begin
                sdl_r <= 8'hFF;
                sdl_g <= 8'h00;
                sdl_b <= 8'h00;
            end else begin
                sdl_r <= 8'h00;
                sdl_g <= 8'h00;
                sdl_b <= 8'hFF;
            end

            // Expand the color signals from 4-bit to 8-bit representation by duplicating each nibble.
            sdl_r <= {sdl_r[3:0], sdl_r[3:0]};
            sdl_g <= {sdl_g[3:0], sdl_g[3:0]};
            sdl_b <= {sdl_b[3:0], sdl_b[3:0]};

            // Handle horizontal and vertical synchronization and produce the signal to indicate active display periods.
            if (sdl_de) begin
                sdl_sx <= sdl_sx + 1;
                if (sdl_sx == (1920 - 1)) begin
                    sdl_sx <= 0;
                    sdl_sy <= sdl_sy + 1;
                    if (sdl_sy == (1080 - 1)) begin
                        sdl_sy <= 0;
                    end
                end
            end
        end
    end

endmodule

