    output [N-1:0] S;
    output C_out;

    wire [N-1:0] C;
    assign C[0] = A[0] & B[0];
    assign S[0] = A[0] ^ B[0];

    genvar i;
    generate
        for (i = 1; i < N; i = i + 1) begin
            assign C[i] = A[i] & B[i] | (A[i] & C[i-1]) | (B[i] & C[i-1]);
            assign S[i] = A[i] ^ B[i] ^ C[i-1];
        end
    endgenerate

    assign C_out = C[N-1];
endmodule

