  reg [31:0] variable_pulse_threshold = 0;
  reg [31:0] slow_pulse_threshold = 18000000;
  reg [31:0] fast_pulse_threshold = 4800000;
  reg [31:0] variable_pulse_base = 2000000;
  reg [31:0] variable_pulse_max = 24000000;
  reg [31:0] variable_pulse_interval = 0;
  reg [31:0] slow_pulse_interval = 18000000;
  reg [31:0] fast_pulse_interval = 4800000;
  reg [31:0] variable_pulse_count = 0;
  reg [31:0] slow_pulse_count = 0;
  reg [31:0] fast_pulse_count = 0;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      counter <= 0;
      variable_pulse_threshold <= 0;
      slow_pulse_threshold <= 18000000;
      fast_pulse_threshold <= 4800000;
      variable_pulse_base <= 2000000;
      variable_pulse_max <= 24000000;
      variable_pulse_interval <= 0;
      slow_pulse_interval <= 18000000;
      fast_pulse_interval <= 4800000;
      variable_pulse_count <= 0;
      slow_pulse_count <= 0;
      fast_pulse_count <= 0;
    end else begin
      counter <= counter + 1;
      variable_pulse_threshold <= variable_pulse_base * variable_pulse_index / variable_pulse_max;
      variable_pulse_interval <= variable_pulse_threshold / 2;
      slow_pulse_interval <= slow_pulse_threshold / 2;
      fast_pulse_interval <= fast_pulse_threshold / 2;
      if (counter == variable_pulse_interval) begin
        variable_pulse_count <= variable_pulse_count + 1;
        variable_pulse_interval <= variable_pulse_threshold + variable_pulse_interval;
      end
      if (counter == slow_pulse_interval) begin
        slow_pulse_count <= slow_pulse_count + 1;
        slow_pulse_interval <= slow_pulse_threshold + slow_pulse_interval;
      end
      if (counter == fast_pulse_interval) begin
        fast_pulse_count <= fast_pulse_count + 1;
        fast_pulse_interval <= fast_pulse_threshold + fast_pulse_interval;
      end
    end
  end

  assign slow_pulse = (slow_pulse_count > 0);
  assign fast_pulse = (fast_pulse_count > 0);
  assign variable_pulse = (variable_pulse_count > 0);

endmodule

