module FSM_game(
    input wire iRST,
    input wire iCLK,
    input wire [1:0] iA,
    input wire [1:0] iB,
    output wire oA,
    output wire oB
);

    // Define states
    parameter DRAW = 2'b00;
    parameter B_LEAD = 2'b01;
    parameter B_WIN = 2'b10;
    parameter A_LEAD = 2'b11;
    parameter A_WIN = 2'b10;

    // Define current state and next state
    reg [1:0] sSTATE;
    reg [1:0] sNEXT_STATE;

    // Define output signals
    wire [1:0] WIN;
    assign oA = WIN[0];
    assign oB = WIN[1];

    // Define combinational logic for next state
    always @(*) begin
        case (sSTATE)
            DRAW: begin
                if (iA > iB)
                    sNEXT_STATE = A_LEAD;
                else if (iA < iB)
                    sNEXT_STATE = B_LEAD;
                else
                    sNEXT_STATE = DRAW;
            end
            B_LEAD: begin
                if (iA > iB)
                    sNEXT_STATE = A_LEAD;
                else if (iA < iB)
                    sNEXT_STATE = B_WIN;
                else
                    sNEXT_STATE = B_LEAD;
            end
            B_WIN: begin
                sNEXT_STATE = B_WIN;
            end
            A_LEAD: begin
                if (iA > iB)
                    sNEXT_STATE = A_WIN;
                else if (iA < iB)
                    sNEXT_STATE = B_LEAD;
                else
                    sNEXT_STATE = A_LEAD;
            end
            A_WIN: begin
                sNEXT_STATE = A_WIN;
            end
        endcase
    end

    // Define sequential logic for current state
    always @(posedge iCLK or negedge iRST) begin
        if (!iRST) begin
            sSTATE <= DRAW;
        end else begin
            sSTATE <= sNEXT_STATE;
        end
    end

    // Define combinational logic for output signals
    always @(*) begin
        case (sSTATE)
            DRAW: begin
                WIN = 2'b00;
            end
            B_LEAD: begin
                WIN = 2'b01;
            end
            B_WIN: begin
                WIN = 2'b10;
            end
            A_LEAD: begin
                WIN = 2'b11;
            end
            A_WIN: begin
                WIN = 2'b10;
            end
        endcase
    end

endmodule

