module array_mul4bit(a, b, prod);
    input [3:0] a;
    input [3:0] b;
    output [7:0] prod;

    wire [15:0] _andwire;
    wire [3:0] _half_adder_carry;
    wire [3:0] _full_adder_carry;

    // Generate all 16 possible AND products between bits of a and b
    assign _andwire = {a[0] & b[0], a[0] & b[1], a[0] & b[2], a[0] & b[3],
                       a[1] & b[0], a[1] & b[1], a[1] & b[2], a[1] & b[3],
                       a[2] & b[0], a[2] & b[1], a[2] & b[2], a[2] & b[3],
                       a[3] & b[0], a[3] & b[1], a[3] & b[2], a[3] & b[3]};

    // Half adder for the least significant bit
    assign prod[0] = a[0] ^ b[0];
    assign _half_adder_carry[0] = a[0] & b[0];

    // Full adder for the second least significant bit
    assign prod[1] = a[1] ^ b[1] ^ _half_adder_carry[0];
    assign _full_adder_carry[0] = (a[1] & b[1]) | (_half_adder_carry[0] & (a[1] ^ b[1]));

    // Full adder for the third least significant bit
    assign prod[2] = a[2] ^ b[2] ^ _full_adder_carry[0];
    assign _full_adder_carry[1] = (a[2] & b[2]) | (_full_adder_carry[0] & (a[2] ^ b[2]));

    // Full adder for the fourth least significant bit
    assign prod[3] = a[3] ^ b[3] ^ _full_adder_carry[1];
    assign _full_adder_carry[2] = (a[3] & b[3]) | (_full_adder_carry[1] & (a[3] ^ b[3]));

    // Half adder for the most significant bit
    assign prod[4] = _full_adder_carry[2];

    // Generate the remaining bits of the product using half adders and full adders
    genvar i;
    generate
        for (i = 5; i < 8; i = i + 1) begin
            assign prod[i] = _andwire[i-1] ^ _half_adder_carry[i-1] ^ _full_adder_carry[i-2];
            assign _half_adder_carry[i] = _andwire[i-1] & _half_adder_carry[i-1];
            assign _full_adder_carry[i-1] = (_andwire[i-1] & _full_adder_carry[i-2]) | (_half_adder_carry[i-1] & _half_adder_carry[i-2]);
        end
    endgenerate
