module isqrt(input [31:0] x, output reg [15:0] y);

  reg [31:0] r;
  reg [15:0] q;
  reg [4:0] i;

  always @* begin
    r <= x;
    q <= 0;
    i <= 0;

    while (i < 16) begin
      if (r >= (q << 16) + (1 << (31 - i))) begin
        r <= r - ((q << 16) + (1 << (31 - i)));
        q <= q + (1 << i);
      end
      q = q << 1;
      i = i + 1;
    end

    y <= q[15:0];
  end

endmodule

