module UART_rx(
module UART_rx(
    input wire clk,
    input wire reset,
    input wire rx_data_in,
    output reg [7:0] rx_data_out
);

    // Define states
    parameter IDLE = 2'b00;
    parameter START = 2'b01;
    parameter DATA = 2'b10;
    parameter STOP = 2'b11;

    // Define oversampling rate
    parameter OVERSAMPLE_RATE = 16;

    // Define baud rate counter
    reg [31:0] baud_rate_counter;
    reg [31:0] baud_rate_counter_max;

    // Define state machine
    reg [1:0] state;
    reg [3:0] bit_counter;
    reg [7:0] data_buffer;

    // Define oversampled clock
    reg oversampled_clk;
    reg oversampled_clk_prev;

    // Define data processing
    reg data_processing;
    reg data_processing_prev;

    // Define data ready
    reg data_ready;

    // Define baud rate
    parameter BAUD_RATE = 9600;
    parameter BAUD_RATE_DIVIDER = $floor(50000000 / BAUD_RATE);

    // Initialize variables
    initial begin
        state = IDLE;
        bit_counter = 0;
        data_buffer = 0;
        baud_rate_counter = 0;
        baud_rate_counter_max = BAUD_RATE_DIVIDER * OVERSAMPLE_RATE;
        oversampled_clk = 0;
        oversampled_clk_prev = 0;
        data_processing = 0;
        data_processing_prev = 0;
        data_ready = 0;
    end

    // Generate oversampled clock
    always @(posedge clk) begin
        if (baud_rate_counter == baud_rate_counter_max) begin
            baud_rate_counter <= 0;
            oversampled_clk <= ~oversampled_clk;
        end else begin
            baud_rate_counter <= baud_rate_counter + 1;
        end
    end

    // State machine
    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            bit_counter <= 0;
            data_buffer <= 0;
            data_processing <= 0;
            data_ready <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (rx_data_in == 0) begin
                        state <= START;
                        bit_counter <= 0;
                        data_processing <= 1;
                    end
                end
                START: begin
                    if (bit_counter == 0) begin
                        data_processing <= 0;
                    end else if (bit_counter == 8) begin
                        state <= DATA;
                        bit_counter <= 0;
                        data_processing <= 1;
                    end else begin
                        data_buffer[bit_counter-1] <= rx_data_in;
                        bit_counter <= bit_counter + 1;
                    end
                end
                DATA: begin
                    if (bit_counter == 8) begin
                        state <= STOP;
                        bit_counter <= 0;
                        data_processing <= 1;
                    end else begin
                        data_buffer[bit_counter] <= rx_data_in;
                        bit_counter <= bit_counter + 1;
                    end
                end
                STOP: begin
                    if (bit_counter == 0) begin
                        state <= IDLE;
                        bit_counter <= 0;
                        data_processing <= 0;
                        data_ready <= 1;
                        rx_data_out <= data_buffer;
                    end else begin
                        bit_counter <= bit_counter + 1;
                    end
                end
            endcase
        end
    end

    // Data processing
    always @(posedge oversampled_clk) begin
        if (data_processing) begin
            if (bit_counter == 0) begin
                data_processing <= 0;
            end else begin
                data_buffer[bit_counter-1] <= rx_data_in;
                bit_counter <= bit_counter + 1;
            end
        end
    end

    // Data ready
    always @(posedge clk) begin
        if (reset) begin
            data_ready <= 0;
        end else begin
            if (data_ready) begin
                data_ready <= 0;
            end else if (state == STOP && bit_counter == 0) begin
                data_ready <= 1;
            end
        end
    end

endmodule

module serial(clk, reset, rxD, sout, signal, counter);

    parameter n = 30;
    parameter count = 4;

    input clk, reset, rxD;
    output reg [n-1:0] sout;
    output reg signal;
    output reg [31:0] counter;

    reg [2:0] delay;
    reg [31:0] data_counter;

    wire [7:0] s_in;

    top_submodule top(clk, reset, rxD, s_in);

    always @(posedge clk) begin
        if (reset) begin
            sout <= 0;
            signal <= 0;
            counter <= 0;
            delay <= 0;
            data_counter <= 0;
        end else begin
            if (delay == 0) begin
                sout <= {sout[n-2:0], s_in};
                data_counter <= data_counter + 1;
                if (data_counter == count) begin
                    signal <= 1;
                    delay <= 1;
                    data_counter <= 0;
                end
            end else begin
                delay <= 0;
                signal <= 0;
            end
            counter <= data_counter;
        end
    end

endmodule

module top_submodule(clk, reset, rxD, s_in);

    input clk, reset, rxD;
    output reg [7:0] s_in;

    reg [3:0] shift_reg;

    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 0;
            s_in <= 0;
        end else begin
            shift_reg <= {shift_reg[2:0], rxD};
            if (shift_reg == 4'b1010) begin
                s_in <= 8'b00000001;
            end else if (shift_reg == 4'b0101) begin
                s_in <= 8'b00000010;
            end else if (shift_reg == 4'b1110) begin
                s_in <= 8'b00000100;
            end else if (shift_reg == 4'b0001) begin
                s_in <= 8'b00001000;
            end else begin
                s_in <= 8'b00000000;
            end
        end
