  parameter ref_clk_cycles_per_baud_period = 10; // Number of reference clock cycles per baud period
  parameter num_data_samples = 100; // Number of data samples to be tested

  // Input signals
  reg ser_info; // Serial data input
  reg reset; // Reset signal for system initialization
  reg ref_clk; // Reference clock source

  // Output signals
  wire [7:0] par_out; // Received parallel data
  wire Rx_valid; // Validity signal
  wire err_par; // Error signal
  wire err_stop; // Error signal

  // Instantiate UART_Rx module
  UART_Rx UART_Rx_inst (
    .ser_info(ser_info),
    .reset(reset),
    .ref_clk(ref_clk),
    .par_out(par_out),
    .Rx_valid(Rx_valid),
    .err_par(err_par),
    .err_stop(err_stop)
  );

  // Instantiate baud_gen module
  baud_gen baud_gen_inst (
    .ref_clk(ref_clk),
    .baud_clk(baud_clk)
  );

  // Counters
  reg [31:0] ref_clk_counter;
  reg [31:0] baud_clk_counter;
  reg [31:0] data_sample_counter;

  // Serial input data generation
  reg [7:0] stored_samples [num_data_samples-1:0];
  reg [3:0] bit_counter;
  reg [31:0] sample_counter;
  reg [7:0] serial_input;

  always @(posedge ref_clk) begin
    if (reset) begin
      ref_clk_counter <= 0;
      baud_clk_counter <= 0;
      data_sample_counter <= 0;
      bit_counter <= 0;
      sample_counter <= 0;
      serial_input <= 0;
    end else begin
      ref_clk_counter <= ref_clk_counter + 1;
      if (ref_clk_counter == ref_clk_cycles_per_baud_period) begin
        baud_clk_counter <= baud_clk_counter + 1;
        ref_clk_counter <= 0;
      end
      if (baud_clk_counter == baud_period) begin
        baud_clk_counter <= 0;
        if (data_sample_counter < num_data_samples) begin
          stored_samples[data_sample_counter] <= serial_input;
          data_sample_counter <= data_sample_counter + 1;
          bit_counter <= 0;
          sample_counter <= 0;
        end
      end else begin
        if (bit_counter < 8) begin
          serial_input <= {serial_input[6:0], stored_samples[sample_counter][bit_counter]};
          bit_counter <= bit_counter + 1;
        end else begin
          sample_counter <= sample_counter + 1;
          bit_counter <= 0;
        end
      end
    end
  end

  // Testbench
