    // Initialize system
    reset = 1;
    ref_clk = 0;
    ser_info = 0;
    #10 reset = 0;

    // Test UART_Rx
    repeat (num_data_samples) begin
      #(ref_clk_period*ref_clk_cycles_per_baud_period) ref_clk = 1;
      #(ref_clk_period*ref_clk_cycles_per_baud_period) ref_clk = 0;
