    assign flag_select = (sel == 2'b00) ? 3'b001 :
                         (sel == 2'b01) ? 3'b010 :
                         (sel == 2'b10) ? 3'b100 :
                                         3'b000;

    // Compute the flag output
    assign flag_update = (flag_select == 3'b001) ? {1'b0, zf, cf} :
                         (flag_select == 3'b010) ? {1'b0, zf, nf} :
                         (flag_select == 3'b100) ? {1'b0, cf, nf} :
                                                  3'b000;

    // Generate the flag register output
    assign flag_reg = (branch) ? flag_update : flag_reg;

    // Compute the branch output
    assign branch_out = (flag_select == 3'b001) ? (zf & branch) :
                        (flag_select == 3'b010) ? (zf & nf & branch) :
                        (flag_select == 3'b100) ? (cf & nf & branch) :
                                                  1'b0;
endmodule

