  reg [7:0] data;
  reg [3:0] bit_count;
  reg start_bit;
  reg stop_bit;

  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      data <= 8'b0;
      bit_count <= 4'b0;
      start_bit <= 1'b0;
      stop_bit <= 1'b0;
      done <= 1'b0;
    end else begin
      case (state)
        IDLE: begin
          if (in == 1'b0) begin
            state <= START;
            bit_count <= 4'b0;
          end
        end
        START: begin
          if (in == 1'b0) begin
            start_bit <= 1'b1;
            state <= DATA;
            bit_count <= 4'b0;
          end
        end
        DATA: begin
          if (bit_count == 4'b1111) begin
            data <= {in, data[7:1]};
            state <= STOP;
            bit_count <= 4'b0;
          end else begin
            data <= {in, data[7:1]};
            bit_count <= bit_count + 1;
          end
        end
        STOP: begin
          if (in == 1'b1) begin
            stop_bit <= 1'b1;
            state <= IDLE;
            done <= 1'b1;
          end else begin
            state <= START;
            bit_count <= 4'b0;
          end
        end
      endcase
    end
  end

