        START: begin
          if (bit_count == 4'b0) begin
            data <= 8'b0;
            bit_count <= bit_count + 1;
          end else if (bit_count == 4'b111) begin
            state <= DATA;
            bit_count <= 4'b0;
          end else begin
            data <= {in, data[7:1]};
