module TopModule(
    input clk,
    input reset,
    input data,
    input done_counting,
    input ack,
    output shift_ena,
    output counting,
    output done
);

    reg [2:0] state;
    reg [1:0] pattern;
    reg [3:0] count;

    always @(posedge clk) begin
        if (reset) begin
            state <= 3'b000;
            pattern <= 2'b00;
            count <= 4'b0000;
            shift_ena <= 1'b0;
            counting <= 1'b0;
            done <= 1'b0;
        end else begin
            case (state)
                3'b000: begin // Wait for start sequence
                    if (data == 1'b1) begin
                        pattern <= 2'b01;
                    end else if (data == 1'b0 && pattern == 2'b01) begin
                        pattern <= 2'b10;
                    end else if (data == 1'b1 && pattern == 2'b10) begin
                        pattern <= 2'b11;
                    end else if (data == 1'b0 && pattern == 2'b11) begin
                        state <= 3'b001;
                        pattern <= 2'b00;
                        count <= 4'b0000;
                        shift_ena <= 1'b1;
                    end else begin
                        pattern <= 2'b00;
                    end
                end
                3'b001: begin // Shift in 4 more bits
                    if (count == 4'b1111) begin
                        state <= 3'b010;
                        count <= 4'b0000;
                        shift_ena <= 1'b0;
                    end else begin
                        count <= count + 1;
                    end
                end
                3'b010: begin // Wait for counters to finish counting
                    if (done_counting) begin
                        state <= 3'b011;
                        counting <= 1'b1;
                    end
                end
                3'b011: begin // Notify user and wait for ack
                    if (ack) begin
                        state <= 3'b000;
                        counting <= 1'b0;
                        done <= 1'b1;
                    end
                end
            endcase
        end
    end

endmodule

