module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  input dig,
  output walk_left,
  output walk_right,
  output aaah,
  output digging
);

  // Define the states
  parameter STATE_WALK_LEFT = 2'b00;
  parameter STATE_WALK_RIGHT = 2'b01;
  parameter STATE_FALL = 2'b10;

  // Define the Moore state machine
  reg [1:0] state;
  always @(posedge clk) begin
    if (areset) begin
      state <= STATE_WALK_LEFT;
    end else begin
      case (state)
        STATE_WALK_LEFT: begin
          if (bump_left) begin
            state <= STATE_WALK_RIGHT;
          end else if (bump_right) begin
            state <= STATE_WALK_LEFT;
          end else if (ground) begin
            state <= STATE_FALL;
          end else if (dig) begin
            state <= STATE_WALK_LEFT;
          end
        end
        STATE_WALK_RIGHT: begin
          if (bump_right) begin
            state <= STATE_WALK_LEFT;
          end else if (bump_left) begin
            state <= STATE_WALK_RIGHT;
          end else if (ground) begin
            state <= STATE_FALL;
          end else if (dig) begin
            state <= STATE_WALK_RIGHT;
          end
        end
        STATE_FALL: begin
          if (ground) begin
            state <= STATE_WALK_LEFT;
          end else if (bump_left) begin
            state <= STATE_WALK_RIGHT;
          end else if (bump_right) begin
            state <= STATE_WALK_LEFT;
          end else if (dig) begin
            state <= STATE_FALL;
          end
        end
      endcase
    end
  end

  // Define the output signals
  assign walk_left = (state == STATE_WALK_LEFT);
  assign walk_right = (state == STATE_WALK_RIGHT);
  assign aaah = (state == STATE_FALL);
  assign digging = (state == STATE_WALK_LEFT || state == STATE_WALK_RIGHT) && dig;

