module TopModule (
module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  input dig,
  output walk_left,
  output walk_right,
  output aaah,
  output digging
);

  // Define the states
  parameter STATE_WALK_LEFT = 2'b00;
  parameter STATE_WALK_RIGHT = 2'b01;

  // Define the Moore state machine
  reg [1:0] state;
  always @(posedge clk) begin
    if (areset) begin
      state <= STATE_WALK_LEFT;
    end else begin
      case (state)
        STATE_WALK_LEFT: begin
          if (bump_right) begin
            state <= STATE_WALK_RIGHT;
          end else if (bump_left) begin
            state <= STATE_WALK_LEFT;
          end else if (ground) begin
            state <= STATE_WALK_LEFT;
          end else if (dig) begin
            state <= STATE_WALK_LEFT;
          end
        end
        STATE_WALK_RIGHT: begin
          if (bump_left) begin
            state <= STATE_WALK_LEFT;
          end else if (bump_right) begin
            state <= STATE_WALK_RIGHT;
          end else if (ground) begin
            state <= STATE_WALK_RIGHT;
          end else if (dig) begin
            state <= STATE_WALK_RIGHT;
          end
        end
      endcase
    end
  end

  // Define the outputs
  assign walk_left = (state == STATE_WALK_LEFT);
  assign walk_right = (state == STATE_WALK_RIGHT);
  assign aaah = (state == STATE_WALK_LEFT && ground) || (state == STATE_WALK_RIGHT && ground);
  assign digging = (state == STATE_WALK_LEFT && dig) || (state == STATE_WALK_RIGHT && dig);

endmodule

