module TopModule(input [1023:0] in, input [7:0] sel, output [3:0] out);

  wire [3:0] mux_out [0:255];
  integer i;

  // Implement 256-to-1 multiplexer
  for (i = 0; i < 256; i = i + 1) begin
    case (sel)
      8'b00000001: mux_out[i] = in[i*4 +: 4];
      8'b00000010: mux_out[i] = in[i*4 + 4 +: 4];
      8'b00000100: mux_out[i] = in[i*4 + 8 +: 4];
      8'b00001000: mux_out[i] = in[i*4 + 12 +: 4];
      8'b00010000: mux_out[i] = in[i*4 + 16 +: 4];
      8'b00100000: mux_out[i] = in[i*4 + 20 +: 4];
      8'b01000000: mux_out[i] = in[i*4 + 24 +: 4];
      8'b10000000: mux_out[i] = in[i*4 + 28 +: 4];
      default: mux_out[i] = 4'b0;
    endcase
  end

  // Select output based on sel
  case (sel)
    8'b00000001: out = mux_out[0];
    8'b00000010: out = mux_out[1];
    8'b00000100: out = mux_out[2];
    8'b00001000: out = mux_out[3];
    8'b00010000: out = mux_out[4];
    8'b00100000: out = mux_out[5];
    8'b01000000: out = mux_out[6];
    8'b10000000: out = mux_out[7];
    default: out = 4'b0;
  endcase

