    if (load) begin
        for (i = 0; i < 16; i = i + 1) begin
            grid[i] <= data[i*16 +: 16];
        end
    end else begin
        for (i = 0; i < 16; i = i + 1) begin
            for (j = 0; j < 16; j = j + 1) begin
                neighbour_count <= 0;
                for (k = -1; k <= 1; k = k + 1) begin
                    for (l = -1; l <= 1; l = l + 1) begin
                        if (k != 0 || l != 0) begin
                            neighbour_count <= neighbour_count + grid[(i+k+16)%16][(j+l+16)%16];
                        end
                    end
                end
                if (neighbour_count == 0) begin
                    grid[i][j] <= 0;
                end else if (neighbour_count == 2) begin
                    grid[i][j] <= grid[i][j];
                end else if (neighbour_count == 3) begin
                    grid[i][j] <= 1;
                end else begin
                    grid[i][j] <= 0;
                end
            end
        end
        for (i = 0; i < 16; i = i + 1) begin
            q[i*16 +: 16] <= grid[i];
        end
    end
end

