  reg [2:0] next_state;
  reg [2:0] grant;
  reg [2:0] priority;

  always @(posedge clk) begin
    if (!resetn) begin
      state <= 3'b000;
      grant <= 3'b000;
      priority <= 3'b000;
    end else begin
      state <= next_state;
      grant <= priority;
    end
