          next_state = 3'b010; // State BA
          priority = 3'b001;
        end else if (r[1]) begin
          next_state = 3'b011; // State CA
          priority = 3'b010;
        end else if (r[2]) begin
          next_state = 3'b100; // State DB
          priority = 3'b100;
        end else begin
          next_state = 3'b001; // State AA
          priority = 3'b000;
        end
      end
      3'b010: begin // State BA
        if (r[0]) begin
          next_state = 3'b010; // State BA
          priority = 3'b001;
        end else if (r[1]) begin
          next_state = 3'b011; // State CA
          priority = 3'b010;
        end else if (r[2]) begin
          next_state = 3'b100; // State DB
          priority = 3'b100;
        end else begin
          next_state = 3'b000; // State A
          priority = 3'b000;
        end
      end
      3'b011: begin // State CA
        if (r[0]) begin
          next_state = 3'b010; // State BA
          priority = 3'b001;
        end else if (r[1]) begin
          next_state = 3'b011; // State CA
          priority = 3'b010;
        end else if (r[2]) begin
          next_state = 3'b100; // State DB
          priority = 3'b100;
        end else begin
          next_state = 3'b000; // State A
          priority = 3'b000;
        end
      end
      3'b100: begin // State DB
        if (r[0]) begin
          next_state = 3'b010; // State BA
          priority = 3'b001;
        end else if (r[1]) begin
          next_state = 3'b011; // State CA
          priority = 3'b010;
        end else if (r[2]) begin
          next_state = 3'b100; // State DB
          priority = 3'b100;
        end else begin
          next_state = 3'b000; // State A
          priority = 3'b000;
        end
      end
      default: begin
        next_state = 3'b000; // State A
        priority = 3'b000;
      end
    endcase
  end

  always @(*) begin
    case (state)
      3'b000: begin // State A
        g = 3'b000;
      end
      3'b001: begin // State AA
