            S: next_state = (inputd == 1'b0) ? S1 : S11;
            S1: next_state = (inputd == 1'b0) ? S11 : S110;
            S11: next_state = (inputd == 1'b0) ? S110 : S110;
            S110: next_state = (inputd == 1'b0) ? S11 : S110;
            B0: next_state = (inputd == 1'b0) ? B1 : B2;
            B1: next_state = (inputd == 1'b0) ? B2 : B3;
            B2: next_state = (inputd == 1'b0) ? B3 : Count;
