module TopModule(inputclk,inputreset,inputdata,inputdone_counting,inputack,outputregshift_ena,outputregcounting,outputregdone);

  reg [3:0] state;
  reg [3:0] pattern;
  reg [3:0] delay;
  reg [3:0] counter;
  reg [3:0] timeout;
  reg [3:0] shift_ena;
  reg [3:0] counting;
  reg [3:0] done;

  always @(posedge inputclk) begin
    if (inputreset) begin
      state <= 0;
      pattern <= 0;
      delay <= 0;
      counter <= 0;
      timeout <= 0;
      shift_ena <= 0;
      counting <= 0;
      done <= 0;
    end else begin
      case (state)
        0: begin // Wait for start sequence
          if (inputdata == 1) begin
            pattern <= {pattern[2:0], inputdata};
            if (pattern == 4'b1101) begin
              state <= 1;
              delay <= 0;
              counter <= 0;
              timeout <= 0;
              shift_ena <= 0;
              counting <= 0;
              done <= 0;
            end else begin
              pattern <= 0;
            end
          end
        end
        1: begin // Detect delay
          delay <= delay + 1;
          if (delay == 4'b1111) begin
            state <= 2;
            counter <= 0;
            timeout <= 0;
            shift_ena <= 0;
            counting <= 0;
            done <= 0;
          end
        end
        2: begin // Count up
          counter <= counter + 1;
          if (counter == 4'b1111) begin
            state <= 3;
            timeout <= 0;
            shift_ena <= 0;
            counting <= 0;
            done <= 0;
          end
        end
        3: begin // Wait for inputdone_counting
          if (inputdone_counting) begin
            state <= 4;
            timeout <= 0;
            shift_ena <= 0;
            counting <= 0;
            done <= 0;
          end
        end
        4: begin // Notify user and wait for inputack
          shift_ena <= 1;
          counting <= 1;
          done <= 0;
          if (inputack) begin
            state <= 0;
            pattern <= 0;
            delay <= 0;
            counter <= 0;
            timeout <= 0;
            shift_ena <= 0;
            counting <= 0;
            done <= 1;
          end
        end
      endcase
    end
  end

  assign outputregshift_ena = shift_ena;
  assign outputregcounting = counting;
  assign outputregdone = done;

endmodule

module TopModule(inputclk,inputareset,inputbump_left,inputbump_right,inputground,inputdig,outputwalk_left,outputwalk_right,outputaaah,outputdigging);

  reg [1:0] state;
  reg [1:0] next_state;
  reg walk_left;
  reg walk_right;
  reg aaah;
  reg digging;

  always @(posedge inputclk or posedge inputareset) begin
    if (inputareset) begin
      state <= 2'b00;
      walk_left <= 1'b0;
      walk_right <= 1'b0;
      aaah <= 1'b0;
      digging <= 1'b0;
    end else begin
      state <= next_state;
      walk_left <= (state == 2'b01) ? 1'b1 : (state == 2'b10) ? 1'b0 : walk_left;
      walk_right <= (state == 2'b01) ? 1'b0 : (state == 2'b10) ? 1'b1 : walk_right;
      aaah <= (state == 2'b00) ? 1'b1 : 1'b0;
      digging <= (state == 2'b01) ? 1'b1 : (state == 2'b10) ? 1'b0 : digging;
    end
  end

  always @(*) begin
    case (state)
      2'b00: begin // Falling state
        if (inputground) begin
          next_state = 2'b00;
        end else if (inputbump_left) begin
          next_state = 2'b10;
        end else if (inputbump_right) begin
          next_state = 2'b01;
        end else if (inputdig) begin
          next_state = 2'b01;
        end else begin
          next_state = 2'b00;
        end
      end
      2'b01: begin // Walking right state
        if (inputground) begin
          next_state = 2'b00;
        end else if (inputbump_left) begin
          next_state = 2'b10;
        end else if (inputbump_right) begin
          next_state = 2'b01;
        end else if (inputdig) begin
          next_state = 2'b01;
        end else begin
          next_state = 2'b01;
        end
      end
      2'b10: begin // Walking left state
        if (inputground) begin
          next_state = 2'b00;
        end else if (inputbump_left) begin
          next_state = 2'b10;
        end else if (inputbump_right) begin
          next_state = 2'b01;
        end else if (inputdig) begin
          next_state = 2'b01;
        end else begin
          next_state = 2'b10;
        end
      end
      default: begin
        next_state = 2'b00;
      end
    endcase
  end

  assign outputwalk_left = walk_left;
  assign outputwalk_right = walk_right;
  assign outputaaah = aaah;
  assign outputdigging = digging;

endmodule

