  reg [6:0] index;
  reg predict_taken_reg;

  always @(posedge inputclk) begin
    if (inputareset) begin
      global_history <= 7'b0;
      predict_history_reg <= 7'b0;
      train_history_reg <= 7'b0;
      index <= 7'b0;
      predict_taken_reg <= 1'b0;
    end else begin
      if (inputpredict_valid) begin
        index <= predict_pc ^ global_history;
        predict_taken_reg <= PHT[index];
        predict_history_reg <= global_history;
      end
      if (inputtrain_valid) begin
        index <= train_pc ^ global_history;
        if (train_history_reg == predict_history_reg) begin
          if (train_taken_reg == predict_taken_reg) begin
            PHT[index] <= PHT[index] + 2'b01;
          end else begin
            PHT[index] <= PHT[index] - 2'b01;
          end
        end else begin
          PHT[index] <= PHT[index] + 2'b10;
        end
        global_history <= {global_history[5:0], train_taken_reg};
        train_history_reg <= global_history;
      end
    end
  end

  assign predict_taken = predict_taken_reg;
  assign predict_history = predict_history_reg;

endmodule

