module TopModule(
    input clk,
    input [7:0] in,
    input reset,
    output reg [23:0] out_bytes,
    output reg done
);

reg [7:0] byte_buffer [2:0];
reg [1:0] state;

parameter IDLE = 2'b00;
parameter BYTE1 = 2'b01;
parameter BYTE2 = 2'b10;
parameter BYTE3 = 2'b11;

always @(posedge clk) begin
    if (reset) begin
        state <= IDLE;
        out_bytes <= 24'b0;
        done <= 1'b0;
    end else begin
        case (state)
            IDLE: begin
                if (in[3] == 1'b1) begin
                    byte_buffer[0] <= in;
                    state <= BYTE1;
                end
            end
            BYTE1: begin
                byte_buffer[1] <= in;
                state <= BYTE2;
            end
            BYTE2: begin
                byte_buffer[2] <= in;
                state <= BYTE3;
            end
            BYTE3: begin
                out_bytes <= {byte_buffer[2], byte_buffer[1], byte_buffer[0]};
                done <= 1'b1;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

