module TopModule(
    input wire clk,
    input wire reset,
    input wire data,
    output reg [3:0] count,
    output reg counting,
    output reg done,
    input wire ack
);

    reg [3:0] delay;
    reg [3:0] state;
    reg [3:0] remaining_time;
    reg [3:0] pattern;
    reg [3:0] pattern_count;
    reg [3:0] pattern_remaining;
    reg [3:0] pattern_delay;
    reg [3:0] pattern_state;
    reg [3:0] pattern_remaining_time;
    reg [3:0] pattern_counting;
    reg [3:0] pattern_done;
    reg [3:0] pattern_ack;

    always @(posedge clk) begin
        if (reset) begin
            state <= 0;
            delay <= 0;
            count <= 0;
            remaining_time <= 0;
            pattern <= 0;
            pattern_count <= 0;
            pattern_remaining <= 0;
            pattern_delay <= 0;
            pattern_state <= 0;
            pattern_remaining_time <= 0;
            pattern_counting <= 0;
            pattern_done <= 0;
            pattern_ack <= 0;
        end else begin
            case (state)
                0: begin // idle state
                    if (data == 1) begin
                        pattern <= 1;
                        pattern_count <= 1;
                        pattern_remaining <= 1;
                        pattern_delay <= 0;
                        pattern_state <= 1;
                        pattern_remaining_time <= 0;
                        pattern_counting <= 1;
                        pattern_done <= 0;
                        pattern_ack <= 0;
                        state <= 1;
                    end
                end
                1: begin // pattern 1 state
                    if (data == 0) begin
                        pattern <= 0;
                        pattern_count <= 0;
                        pattern_remaining <= 0;
                        pattern_delay <= 0;
                        pattern_state <= 2;
                        pattern_remaining_time <= 0;
                        pattern_counting <= 0;
                        pattern_done <= 0;
                        pattern_ack <= 0;
                        state <= 2;
                    end else if (pattern_count == 1) begin
                        pattern <= 1;
                        pattern_count <= 2;
                        pattern_remaining <= 2;
                        pattern_delay <= 0;
                        pattern_state <= 1;
                        pattern_remaining_time <= 0;
                        pattern_counting <= 1;
                        pattern_done <= 0;
                        pattern_ack <= 0;
                        state <= 1;
                    end
                end
                2: begin // pattern 0 state
                    if (data == 1) begin
                        pattern <= 1;
                        pattern_count <= 1;
                        pattern_remaining <= 1;
                        pattern_delay <= 0;
                        pattern_state <= 1;
                        pattern_remaining_time <= 0;
                        pattern_counting <= 1;
                        pattern_done <= 0;
                        pattern_ack <= 0;
                        state <= 1;
                    end else if (pattern_count == 0) begin
                        pattern <= 0;
                        pattern_count <= 1;
                        pattern_remaining <= 1;
                        pattern_delay <= 0;
                        pattern_state <= 2;
                        pattern_remaining_time <= 0;
                        pattern_counting <= 0;
                        pattern_done <= 0;
                        pattern_ack <= 0;
                        state <= 2;
                    end
                end
            endcase

            if (pattern_counting) begin
                pattern_remaining_time <= pattern_remaining_time - 1;
                if (pattern_remaining_time == 0) begin
                    pattern_counting <= 0;
                    pattern_done <= 1;
                    pattern_ack <= 1;
                end
            end else if (pattern_done) begin
                pattern_counting <= 0;
                pattern_done <= 0;
                pattern_ack <= 0;
                state <= 0;
            end else if (pattern_ack) begin
                pattern_counting <= 0;
                pattern_done <= 0;
                pattern_ack <= 0;
                state <= 0;
            end

            if (pattern_counting) begin
                count <= count + 1;
                remaining_time <= remaining_time - 1;
                if (remaining_time == 0) begin
                    done <= 1;
                    state <= 0;
                end
            end else begin
                count <= 0;
                remaining_time <= delay;
                done <= 0;
            end
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            counting <= 0;
        end else begin
            if (pattern_counting) begin
                counting <= 1;
            end else begin
                counting <= 0;
            end
        end
    end

endmodule
